    // Keep the SEH boundary out of stateful runtime methods: MSVC rejects
    // __try in functions that also require C++ object unwinding.  Listener
    // identity capture calls one native resolver while the stock lifecycle is
    // still mutable, so a stale UObject must become a failed preflight rather
    // than an access violation.
    static inline bool RollbackSafeInvokePtrReturnsPtr(
        void* (__fastcall* fn)(void*), void* self, void** out) noexcept
    {
        if (out) *out = nullptr;
        if (!fn || !self || !out) return false;
        __try
        {
            *out = fn(self);
            return *out != nullptr;
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            *out = nullptr;
            return false;
        }
    }

    static inline bool RollbackSafeInvokeCharaPresentationCallback(
        void (__fastcall* fn)(uintptr_t, const void*),
        uintptr_t actor, const void* event) noexcept
    {
        if (!fn || !actor) return false;
        __try
        {
            fn(actor, event);
            return true;
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return false;
        }
    }

    static_assert(
        (kRollbackProductionSummaryWindowCapacity
            & (kRollbackProductionSummaryWindowCapacity - 1u)) == 0,
        "production summary window must be a power of two");
    static constexpr size_t kRollbackProductionFrameHistoryMask =
        kRollbackProductionSummaryWindowCapacity - 1u;
    // At batch entry, every uncommitted presentation frame is retained by
    // the live summary window. During the batch, consensus can retire that
    // entire window before finish_gekko_batch commits presentation, while
    // simulation can fill one new window. Two windows therefore bound all
    // accepted, distinct uncommitted frame buckets. The next frame is
    // rejected by the summary-ring ownership check and the ledger remains
    // fail-closed.
    static constexpr size_t
        kRollbackProductionSideEffectFrameBucketCount =
            kRollbackProductionSummaryWindowCapacity * 2u;

    static_assert(
        sizeof(RollbackSecondaryEventAuthorityMessage)
            <= kRollbackRoutedMaxPayloadBytes,
        "secondary-event authority must fit one authenticated datagram");
    static_assert(
        sizeof(RollbackMotionBankAuthorityMessage)
            <= kRollbackRoutedMaxPayloadBytes,
        "motion-bank authority must fit one authenticated datagram");
    static_assert(
        sizeof(RollbackStageWindAuthorityMessage)
            <= kRollbackProtocolV2MaxPayloadBytes,
        "stage-wind authority must fit one authenticated datagram");

    class RollbackNanosecondCounterScope
    {
    public:
        RollbackNanosecondCounterScope(
            uint64_t& total, uint64_t& calls) noexcept
            : m_total(total), m_calls(calls),
              m_started(std::chrono::steady_clock::now())
        {
        }

        ~RollbackNanosecondCounterScope() noexcept
        {
            m_total += static_cast<uint64_t>(
                std::chrono::duration_cast<std::chrono::nanoseconds>(
                    std::chrono::steady_clock::now() - m_started).count());
            ++m_calls;
        }

    private:
        uint64_t& m_total;
        uint64_t& m_calls;
        std::chrono::steady_clock::time_point m_started;
    };

