    enum class RollbackProductionState : uint8_t
    {
        Disabled,
        WaitingForContext,
        WaitingForPeer,
        WaitingForSessionContract,
        WaitingForLaunchBarrier,
        WaitingForGekko,
        Active,
        Fatal,
        Stopping,
        ReturningToLobby,
        WaitingForRoundTransition,
    };

    enum class RollbackSteamSessionLifecycleState : uint8_t
    {
        AwaitNativeSession = 0,
        NativeSessionReady = 1,
        BootstrapRunning = 2,
        HorseReady = 3,
        RetryDelay = 4,
        RetryExhausted = 5,
        Revoked = 6,
    };

    enum class RollbackNativeHookKind : uint8_t
    {
        PerFrame = 0,
        InputPair = 1,
        SimulationLoop = 2,
        RoundOverDecision = 3,
        TerminalGameFlowNotify = 4,
        NewRoundFinalize = 5,
        PreNewRoundTransition = 6,
        PaletteWriter = 7,
        Count = 8,
    };

    static constexpr const char* RollbackProductionStateName(
        RollbackProductionState state) noexcept
    {
        switch (state)
        {
        case RollbackProductionState::Disabled: return "disabled";
        case RollbackProductionState::WaitingForContext: return "waiting-for-context";
        case RollbackProductionState::WaitingForPeer: return "waiting-for-peer";
        case RollbackProductionState::WaitingForSessionContract: return "waiting-for-session-contract";
        case RollbackProductionState::WaitingForLaunchBarrier: return "waiting-for-launch-barrier";
        case RollbackProductionState::WaitingForGekko: return "waiting-for-gekko";
        case RollbackProductionState::Active: return "active";
        case RollbackProductionState::Fatal: return "fatal";
        case RollbackProductionState::Stopping: return "stopping";
        case RollbackProductionState::ReturningToLobby: return "returning-to-lobby";
        case RollbackProductionState::WaitingForRoundTransition: return "waiting-for-round-transition";
        }
        return "unknown";
    }

