    static inline uint64_t ComputeRollbackPairEpoch(
        const RollbackProductionConfig& config,
        const RollbackSnapshotManifest& manifest,
        uint64_t session_epoch = 0) noexcept
    {
        const uint64_t round_epoch = ComputeRollbackPairEpochMaterial(
            config.expected_build_id,
            config.expected_schema_id,
            config.local_peer,
            config.remote_peer,
            config.rollback_window,
            config.input_delay,
            config.lifecycle_mode,
            manifest.epoch.round_start_digest,
            manifest.epoch.stage_layout_digest,
            manifest.epoch.native_stage_identity,
            manifest.epoch.round_ordinal,
            config.deterministic_input.hash()
                ^ (config.replay_input.hash() + 0x9E3779B97F4A7C15ull));
        RollbackHash hash {};
        hash.add_scalar(session_epoch);
        hash.add_scalar(round_epoch);
        return hash.value ? hash.value : 1;
    }

    static inline uint64_t ComputeRollbackSteamSessionEpoch(
        const RollbackSessionContractMessage& message,
        uint64_t handshake_generation) noexcept
    {
        RollbackHash hash {};
        const uint64_t steam_low = (std::min)(
            message.local_steam_id, message.remote_steam_id);
        const uint64_t steam_high = (std::max)(
            message.local_steam_id, message.remote_steam_id);
        hash.add_scalar(message.lobby_id);
        hash.add_scalar(message.owner_steam_id);
        hash.add_scalar(steam_low);
        hash.add_scalar(steam_high);
        hash.add_scalar(message.host_nonce);
        hash.add_scalar(message.contract_hash);
        hash.add_scalar(handshake_generation);
        return hash.value ? hash.value : 1;
    }

    static inline uint64_t ComputeRollbackLifecycleDigest(
        RollbackLifecycleMode mode,
        const RollbackLifecycleEpoch& epoch) noexcept
    {
        RollbackHash hash {};
        hash.add_scalar(static_cast<uint8_t>(mode));
        hash.add_scalar(epoch.round_ordinal);
        hash.add_scalar(epoch.round_start_digest);
        hash.add_scalar(epoch.stage_layout_digest);
        hash.add_scalar(epoch.native_stage_identity);
        hash.add_scalar(epoch.battle_main_state);
        hash.add_scalar(epoch.battle_status);
        return hash.value ? hash.value : 1;
    }

