        static void __fastcall result_screen_post_tick_hook(void* state)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime || !runtime->m_result_screen_post_tick_trampoline)
                return;
            const auto original = reinterpret_cast<ResultScreenPostTickFn>(
                runtime->m_result_screen_post_tick_trampoline);
            CallbackLease lease(runtime);
            const bool owns_boundary = lease
                && runtime->m_hook_owns_tick
                && runtime->m_config.lifecycle_mode
                    == RollbackLifecycleMode::StockOnlinePvp
                && runtime->m_round_phase
                    == RollbackRoundPhase::StockInterRound
                && reinterpret_cast<uintptr_t>(state)
                    == runtime->m_image_base
                        + kRollbackProductionRvaWorldModeRoundResult;
            if (!owns_boundary)
            {
                original(state);
                return;
            }

            const uintptr_t stage_info_address = runtime->m_image_base
                + kRollbackProductionRvaStageInfoInitialized;
            uint32_t saved_stage_info_initialized = 0;
            if (!SafeReadUInt32(reinterpret_cast<const void*>(
                        stage_info_address),
                    &saved_stage_info_initialized))
            {
                runtime->fail_closed(
                    "native-result-cinematic-gate-unreadable");
                return;
            }
            const bool override_stage_info =
                saved_stage_info_initialized == 0;
            if (override_stage_info
                && !SafeWriteUInt32(reinterpret_cast<void*>(
                        stage_info_address),
                    1))
            {
                runtime->fail_closed(
                    "native-result-cinematic-gate-write-failed");
                return;
            }

            uint32_t mode_frame = 0;
            uint32_t phase_end = 0;
            const bool coordinate_readable = state
                && SafeReadUInt32(reinterpret_cast<const uint8_t*>(state)
                        + 0x08,
                    &mode_frame)
                && SafeReadUInt32(reinterpret_cast<const uint8_t*>(state)
                        + 0x18,
                    &phase_end);
            original(state);

            if (override_stage_info)
            {
                if (!SafeWriteUInt32(reinterpret_cast<void*>(
                            stage_info_address),
                        saved_stage_info_initialized))
                {
                    runtime->fail_closed(
                        "native-result-cinematic-gate-restore-failed");
                    return;
                }
                uint32_t verified = UINT32_MAX;
                if (!SafeReadUInt32(reinterpret_cast<const void*>(
                            stage_info_address),
                        &verified)
                    || verified != saved_stage_info_initialized)
                {
                    runtime->fail_closed(
                        "native-result-cinematic-gate-verify-failed");
                    return;
                }
            }
            if (override_stage_info && coordinate_readable
                && mode_frame > phase_end
                && runtime->m_config.replay_trace_compare)
            {
                ReplayTraceFields fields;
                fields.uinteger("round_generation",
                        runtime->m_round_generation)
                    .uinteger("target_generation",
                        runtime->m_round_generation + 1u)
                    .uinteger("mode_frame", mode_frame)
                    .uinteger("phase_end", phase_end)
                    .string("reason",
                        "private-hgcpu-cinematic-ring-outside-rollback-contract");
                ReplayDebugTrace::instance().event(
                    "rollback_result_screen_cinematic_suppressed", fields);
            }
        }

        static void __fastcall pre_new_round_transition_hook()
        {
            static thread_local uint32_t hook_depth = 0;
            static thread_local bool release_original_inflight = false;
            struct HookDepthLease
            {
                uint32_t& depth;
                explicit HookDepthLease(uint32_t& value) noexcept
                    : depth(value)
                {
                    ++depth;
                }
                ~HookDepthLease() noexcept { --depth; }
            } hook_depth_lease(hook_depth);
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            runtime->record_native_hook_entry(
                RollbackNativeHookKind::PreNewRoundTransition);
            CallbackLease lease(runtime);
            if (!runtime->m_pre_new_round_transition_trampoline) return;
            const auto original = reinterpret_cast<PreNewRoundTransitionFn>(
                runtime->m_pre_new_round_transition_trampoline);
            auto trace_checkpoint = [&](const char* phase) noexcept
            {
                if (!ReplayDebugTrace::instance().enabled()) return;
                void* current = nullptr;
                void* queued = nullptr;
                const uintptr_t pump = runtime->m_image_base
                    + kRollbackProductionRvaWorldModePump;
                uint32_t transition_completed = 0;
                uint32_t pump_scratch_state = 0;
                int32_t subdriver_state = 0;
                void* subdriver = nullptr;
                uint32_t pre_new_round_frame = 0;
                uint32_t pre_new_round_phase_timer = 0;
                uint32_t new_round_frame = 0;
                uint32_t new_round_phase_timer = 0;
                const bool world_mode_readable =
                    SafeReadPtr(reinterpret_cast<const void*>(pump), &current)
                    && SafeReadPtr(reinterpret_cast<const void*>(pump + 8),
                        &queued)
                    && SafeReadBytes(reinterpret_cast<const void*>(pump + 16),
                        &transition_completed,
                        sizeof(transition_completed))
                    && SafeReadBytes(reinterpret_cast<const void*>(pump + 32),
                        &pump_scratch_state,
                        sizeof(pump_scratch_state))
                    && SafeReadBytes(reinterpret_cast<const void*>(pump + 36),
                        &subdriver_state, sizeof(subdriver_state))
                    && SafeReadPtr(reinterpret_cast<const void*>(pump + 56),
                        &subdriver)
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            runtime->m_image_base
                                + kRollbackProductionRvaPreNewRoundWorldMode
                                + 8),
                        &pre_new_round_frame,
                        sizeof(pre_new_round_frame))
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            runtime->m_image_base
                                + kRollbackProductionRvaPreNewRoundWorldMode
                                + 12),
                        &pre_new_round_phase_timer,
                        sizeof(pre_new_round_phase_timer))
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            runtime->m_image_base
                                + kRollbackProductionRvaNewRoundWorldMode
                                + 8),
                        &new_round_frame, sizeof(new_round_frame))
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            runtime->m_image_base
                                + kRollbackProductionRvaNewRoundWorldMode
                                + 12),
                        &new_round_phase_timer,
                        sizeof(new_round_phase_timer));
                RollbackRoundResultCinematicEvidence cinematic {};
                (void)CaptureRollbackRoundResultCinematicEvidence(
                    runtime->m_image_base, cinematic);
                ReplayTraceFields fields;
                fields.string("request_id", runtime->m_config.request_id)
                    .string("client_role", runtime->m_config.client_role)
                    .string("phase", phase)
                    .uinteger("hook_depth", hook_depth)
                    .boolean("release_original_inflight",
                        release_original_inflight)
                    .boolean("hook_owns_tick", runtime->m_hook_owns_tick)
                    .uinteger("round_generation",
                        runtime->m_round_generation)
                    .uinteger("round_ordinal",
                        runtime->m_manifest.epoch.round_ordinal)
                    .uinteger("round_phase",
                        static_cast<uint8_t>(runtime->m_round_phase))
                    .boolean("local_valid",
                        runtime->m_pre_new_round_gate.local_valid())
                    .boolean("peer_valid",
                        runtime->m_pre_new_round_gate.peer_valid())
                    .boolean("released",
                        runtime->m_pre_new_round_gate.released())
                    .boolean("release_pending_validation",
                        runtime->m_pre_new_round_release_pending_validation)
                    .boolean("world_mode_readable", world_mode_readable)
                    .hex("world_mode_current",
                        reinterpret_cast<uintptr_t>(current))
                    .hex("world_mode_queued",
                        reinterpret_cast<uintptr_t>(queued))
                    .uinteger("world_mode_transition_completed",
                        transition_completed)
                    .uinteger("world_mode_pump_scratch_state",
                        pump_scratch_state)
                    .integer("world_mode_subdriver_state",
                        subdriver_state)
                    .hex("world_mode_subdriver",
                        reinterpret_cast<uintptr_t>(subdriver))
                    .uinteger("pre_new_round_frame",
                        pre_new_round_frame)
                    .uinteger("pre_new_round_phase_timer",
                        pre_new_round_phase_timer)
                    .uinteger("new_round_frame", new_round_frame)
                    .uinteger("new_round_phase_timer",
                        new_round_phase_timer)
                    .uinteger("native_tick_serial",
                        runtime->m_native_tick_serial.load(
                            std::memory_order_acquire))
                    .uinteger("inter_round_wind_coordinate",
                        runtime->m_stock_inter_round_wind_coordinate)
                    .uinteger("inter_round_wind_mode",
                        static_cast<uint8_t>(
                            runtime->m_stock_inter_round_wind_mode));
                AddRollbackRoundResultCinematicTraceFields(
                    fields, cinematic);
                ReplayDebugTrace::instance().event(
                    "rollback_pre_new_round_hook_checkpoint", fields);
            };
            trace_checkpoint("entry");
            const bool gate_active = lease
                && runtime->m_hook_owns_tick
                && runtime->m_config.lifecycle_mode
                    == RollbackLifecycleMode::StockOnlinePvp
                && runtime->m_round_phase
                    == RollbackRoundPhase::StockInterRound;
            if (!gate_active)
            {
                runtime->record_native_hook_pass_through(
                    RollbackNativeHookKind::PreNewRoundTransition);
                original();
                return;
            }
            runtime->record_native_hook_owned(
                RollbackNativeHookKind::PreNewRoundTransition);
            RollbackPreNewRoundBarrierMessage evidence {};
            const bool first_arrival =
                !runtime->m_pre_new_round_gate.local_valid();
            if (RollbackPreNewRoundAwaitsFinalRoundResultCapture(
                    first_arrival,
                    runtime->m_inter_round_carried_state_gate.captured(),
                    runtime->m_stock_inter_round_wind_iteration_admitted,
                    runtime->m_stock_inter_round_wind_mode
                        == RollbackInterRoundWindMode::RoundResult,
                    runtime->m_stock_inter_round_wind_coordinate,
                    kRollbackProductionRoundResultTransitionFrame))
            {
                // This callback is reentrant inside the final RoundResult
                // native iteration. Suppress it once so the outer iteration
                // can run its deterministic tail and publish carried state.
                runtime->m_pre_new_round_final_transition_deferred = true;
                return;
            }
            if (first_arrival
                && (!runtime->capture_pre_new_round_barrier(evidence)
                    || !runtime->m_pre_new_round_gate.arrive(evidence)))
            {
                runtime->fail_closed(runtime->m_pre_new_round_gate
                        .report().failed
                    ? runtime->m_pre_new_round_gate.report().failure
                    : runtime->m_pre_new_round_capture_failure
                        ? runtime->m_pre_new_round_capture_failure
                        : "pre-new-round-entry-invalid");
                return;
            }
            if (!first_arrival
                && runtime->m_pre_new_round_release_pending_validation)
            {
                (void)runtime->
                    validate_pre_new_round_pending_validation_reentry();
                trace_checkpoint("post-release-reentry-rejected");
                runtime->fail_closed(
                    "pre-new-round-post-release-reentry-invalid");
                return;
            }
            if (!first_arrival
                && !runtime->validate_pre_new_round_held_reentry())
            {
                trace_checkpoint("held-reentry-rejected");
                runtime->fail_closed(
                    "pre-new-round-held-reentry-invalid");
                return;
            }
            const auto& gate_report = runtime->m_pre_new_round_gate.report();
            runtime->m_status.native_pre_new_round_hook_arrivals =
                gate_report.arrivals;
            runtime->m_status.native_pre_new_round_entry_digest =
                runtime->m_pre_new_round_gate.local().entry_digest;
            runtime->m_status.native_pre_new_round_target_generation =
                runtime->m_pre_new_round_gate.local().target_round_generation;
            runtime->m_status.native_pre_new_round_target_ordinal =
                runtime->m_pre_new_round_gate.local().target_round_ordinal;
            runtime->m_status.native_pre_new_round_local_stage =
                static_cast<uint8_t>(
                    runtime->m_pre_new_round_gate.local().stage);
            if (first_arrival)
            {
                runtime->m_status.native_pre_new_round_first_entry_serial =
                    ++runtime->m_pre_new_round_transition_serial;
                if (!runtime->enqueue_local_pre_new_round_barrier())
                {
                    runtime->fail_closed(
                        "pre-new-round-barrier-queue-failed");
                    return;
                }
            }
            const RollbackNativePreNewRoundAction action =
                runtime->m_pre_new_round_gate.action(true);
            runtime->m_status.native_pre_new_round_holds =
                runtime->m_pre_new_round_gate.report().holds;
            if (action == RollbackNativePreNewRoundAction::Hold)
            {
                if (runtime->m_status
                        .native_pre_new_round_first_hold_serial == 0)
                {
                    runtime->m_status
                        .native_pre_new_round_first_hold_serial =
                            ++runtime->m_pre_new_round_transition_serial;
                }
                return;
            }
            if (action != RollbackNativePreNewRoundAction::Release)
            {
                runtime->fail_closed(runtime->m_pre_new_round_gate
                        .report().failed
                    ? runtime->m_pre_new_round_gate.report().failure
                    : "pre-new-round-release-invalid");
                return;
            }
            RollbackRoundResultCinematicEvidence cinematic_release {};
            const bool cinematic_readable =
                CaptureRollbackRoundResultCinematicEvidence(
                    runtime->m_image_base, cinematic_release);
            const RollbackNativePreNewRoundCinematicReleaseObservation
                cinematic_observation {
                    cinematic_readable && cinematic_release.readable,
                    cinematic_release.state,
                    cinematic_release.trigger,
                    cinematic_release.aux_trigger,
                    cinematic_release.palette_state[0],
                    cinematic_release.palette_state[1],
                    cinematic_release.block_interactive_ops,
                };
            if (!RollbackNativePreNewRoundCinematicReadyForRelease(
                    cinematic_observation))
            {
                // Do not consume the bilateral release yet. The stock
                // cinematic cleanup may restore its HgCpu buffer after this
                // callback, which would erase the queued NewRound mode. A
                // later E60 PostTick arrival in the idle phase performs the
                // one authoritative carried-state restore and transition.
                trace_checkpoint("release-deferred-cinematic-cleanup");
                return;
            }
            if (!runtime->
                    restore_round_result_carried_state_before_pre_new_round())
            {
                runtime->fail_closed(
                    "pre-new-round-carried-state-restore-failed");
                return;
            }
            if (!runtime->m_pre_new_round_gate.mark_released())
            {
                runtime->fail_closed(runtime->m_pre_new_round_gate
                        .report().failed
                    ? runtime->m_pre_new_round_gate.report().failure
                    : "pre-new-round-release-invalid");
                return;
            }
            runtime->m_status.native_pre_new_round_release_serial =
                ++runtime->m_pre_new_round_transition_serial;
            runtime->m_pre_new_round_release_pending_validation = true;
            trace_checkpoint("before-release-original");
            release_original_inflight = true;
            original();
            release_original_inflight = false;
            trace_checkpoint("after-release-original");
            ++runtime->m_status.native_pre_new_round_original_calls;
            runtime->m_status.native_pre_new_round_releases =
                runtime->m_pre_new_round_gate.report().releases;
            runtime->m_status.native_pre_new_round_local_stage =
                static_cast<uint8_t>(
                    runtime->m_pre_new_round_gate.local().stage);
            if (!runtime->enqueue_local_pre_new_round_barrier())
            {
                runtime->fail_closed(
                    "pre-new-round-accepted-barrier-queue-failed");
                return;
            }
            void* queued = nullptr;
            if (!SafeReadPtr(reinterpret_cast<const void*>(runtime->m_image_base
                        + kRollbackProductionRvaWorldModePump + 8),
                    &queued)
                || reinterpret_cast<uintptr_t>(queued)
                    != runtime->m_image_base
                        + kRollbackProductionRvaNewRoundWorldMode)
            {
                runtime->fail_closed(
                    "pre-new-round-native-queue-invalid");
            }
        }

        static bool __fastcall round_over_decision_hook(
            void* battle_manager)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return false;
            runtime->record_native_hook_entry(
                RollbackNativeHookKind::RoundOverDecision);
            CallbackLease lease(runtime);
            if (!runtime->m_round_over_decision_trampoline)
                return false;
            if (!lease)
            {
                runtime->record_native_hook_pass_through(
                    RollbackNativeHookKind::RoundOverDecision);
                return reinterpret_cast<RoundOverDecisionFn>(
                    runtime->m_round_over_decision_trampoline)(battle_manager);
            }
            const bool original_result =
                reinterpret_cast<RoundOverDecisionFn>(
                    runtime->m_round_over_decision_trampoline)(
                        battle_manager);
            const bool production_gate_active = runtime->m_hook_owns_tick
                && runtime->m_config.lifecycle_mode
                    == RollbackLifecycleMode::StockOnlinePvp;
            if (production_gate_active)
                runtime->record_native_hook_owned(
                    RollbackNativeHookKind::RoundOverDecision);
            else
                runtime->record_native_hook_pass_through(
                    RollbackNativeHookKind::RoundOverDecision);
            if (!production_gate_active) return original_result;
            if (runtime->m_stock_match_identity.valid
                && reinterpret_cast<uintptr_t>(battle_manager)
                    != runtime->m_stock_match_identity.battle_manager)
            {
                runtime->fail_closed(
                    "native-round-over-match-identity-mismatch");
                return false;
            }
            const bool filtered = runtime->m_native_terminal_gate
                .filter_round_over_result(
                    runtime->m_round_phase, original_result);
            runtime->sync_native_terminal_gate_status();
            if (runtime->m_native_terminal_gate.report().failed)
            {
                runtime->fail_closed(
                    runtime->m_native_terminal_gate.report().failure);
                return false;
            }
            return filtered;
        }

        static bool override_read32(
            void*, uintptr_t address, uint32_t& value) noexcept
        {
            return SafeReadUInt32(
                reinterpret_cast<const void*>(address), &value);
        }

        static bool override_write32(
            void*, uintptr_t address, uint32_t value) noexcept
        {
            return SafeWriteUInt32(reinterpret_cast<void*>(address), value);
        }

        static bool override_write64(
            void*, uintptr_t address, uint64_t value) noexcept
        {
            return SafeWriteBytes(reinterpret_cast<void*>(address),
                &value, sizeof(value));
        }

        bool run_stock_inter_round_tick(
            TickFn original, RollbackProductionTickArgs* args) noexcept
        {
            if (!original || !args)
            {
                fail_closed("stock-inter-round-tick-args-invalid");
                return false;
            }
            // Inter-round calls are stock-owned. In particular, do not alter
            // either fighter's current MoveVM move ID at +0x324.
            original(args);
            ++m_status.round_stock_pass_through_calls;
            ++m_status.stock_observer_trampoline_calls;
            return true;
        }

        void on_tick(RollbackProductionTickArgs* args) noexcept
        {
            TickFn original = reinterpret_cast<TickFn>(m_tick_trampoline);
            RollbackProductionTickArgs frozen_frame_zero_args {};
            bool executing_frozen_frame_zero = false;
            ++m_status.production_simulation_tick_calls;
            if (m_round_phase == RollbackRoundPhase::StockInterRound)
            {
                if (args)
                {
                    m_last_tick_args = *args;
                    m_last_tick_args_valid = true;
                }
                // Rearm authority is the outer SimulationLoop entry. A
                // PerFrame callback can occur inside a multi-delta native
                // catch-up call and is therefore too late to freeze without
                // allowing the enclosing callback/round-state tail to run.
                (void)run_stock_inter_round_tick(original, args);
                return;
            }
            if (m_round_phase == RollbackRoundPhase::BaselineFrozen)
            {
                // The first qualifying next-round call is stored by the hook.
                // No stock gameplay call is allowed until bilateral baseline
                // acceptance starts the new Gekko epoch.
                return;
            }
            if (m_round_phase == RollbackRoundPhase::StartingGekko)
            {
                if (!m_frozen_frame_zero_pending
                    || !m_frozen_frame_zero_args_valid)
                {
                    fail_closed("frozen-frame-zero-args-missing");
                    return;
                }
                frozen_frame_zero_args = m_frozen_frame_zero_args;
                args = &frozen_frame_zero_args;
                executing_frozen_frame_zero = true;
            }
            if (m_round_phase == RollbackRoundPhase::MatchComplete)
            {
                if (original) original(args);
                ++m_status.stock_observer_trampoline_calls;
                return;
            }
            if (!m_hook_owns_tick)
            {
                if (m_stock_attach_observing)
                {
                    // Preserve the arguments from the first qualifying
                    // pre-control call. Once frozen, later hook entries must
                    // neither run stock nor replace frame zero's arguments.
                    if (!m_stock_boundary_frozen && args)
                    {
                        m_last_tick_args = *args;
                        m_last_tick_args_valid = true;
                    }
                }
                if (ShouldSuppressStockPerFrameForRoundTransition(
                        m_stock_round_transition_rearm,
                        m_stock_boundary_frozen))
                {
                    return;
                }
                if (original)
                {
                    if (m_stock_attach_observing)
                        ++m_status.stock_observer_trampoline_calls;
                    original(args);
                }
                return;
            }
            RollbackNanosecondCounterScope owned_tick_timing(
                m_status.owned_tick_nanoseconds,
                m_status.owned_tick_calls);
            const DWORD current_thread = GetCurrentThreadId();
            if (m_simulation_thread_id == 0)
                m_simulation_thread_id = current_thread;
            else if (m_simulation_thread_id != current_thread)
            {
                fail_closed("production-tick-thread-changed");
                return;
            }
            if (m_status.state != RollbackProductionState::Active
                && m_status.state != RollbackProductionState::WaitingForGekko)
            {
                // Once production owns the boundary, fatal/stopping states
                // freeze the round. Never fall back to stock simulation.
                return;
            }
            if (!args || !original)
            {
                fail_closed("invalid-per-frame-hook-args");
                return;
            }
            m_last_tick_args = *args;
            m_last_tick_args_valid = true;
            if (!RollbackGekkoMayUpdateSession(
                    m_gekko_frame_high_water, m_gekko_update_calls))
            {
                fail_closed("gekko-signed-frame-ceiling-reached");
                return;
            }
            RollbackLiveToken live {};
            bool live_captured = false;
            bool live_matches = false;
            {
                RollbackNanosecondCounterScope lifecycle_timing(
                    m_status.lifecycle_token_nanoseconds,
                    m_status.lifecycle_token_calls);
                live_captured = CaptureRollbackLiveToken(
                    m_image_base, m_manifest.epoch, live);
                live_matches = live_captured
                    && RollbackLiveTokenMatchesEpoch(
                        m_manifest.epoch, live, m_config.lifecycle_mode);
            }
            if (!live_captured)
            {
                fail_closed("lifecycle-token-capture-failed");
                return;
            }
            m_status.lifecycle_expected_round_ordinal =
                m_manifest.epoch.round_ordinal;
            m_status.lifecycle_live_round_ordinal = live.round_ordinal;
            m_status.lifecycle_expected_battle_main_state =
                m_manifest.epoch.battle_main_state;
            m_status.lifecycle_live_battle_main_state =
                live.battle_main_state;
            m_status.lifecycle_expected_battle_status =
                m_manifest.epoch.battle_status;
            m_status.lifecycle_live_battle_status = live.battle_status;
            m_status.lifecycle_expected_auto_advance =
                m_manifest.epoch.auto_advance_armed;
            m_status.lifecycle_live_auto_advance =
                live.auto_advance_armed;
            m_status.lifecycle_expected_round_start_digest =
                m_manifest.epoch.round_start_digest;
            m_status.lifecycle_live_round_start_digest =
                live.round_start_digest;
            if (!live_matches)
            {
                const uint32_t mismatch_mask =
                    RollbackLiveTokenMismatchMask(
                        m_manifest.epoch, live, m_config.lifecycle_mode);
                m_status.lifecycle_mismatch_mask = mismatch_mask;
                m_status.lifecycle_expected_round_ordinal =
                    m_manifest.epoch.round_ordinal;
                m_status.lifecycle_live_round_ordinal = live.round_ordinal;
                m_status.lifecycle_expected_battle_main_state =
                    m_manifest.epoch.battle_main_state;
                m_status.lifecycle_live_battle_main_state =
                    live.battle_main_state;
                m_status.lifecycle_expected_battle_status =
                    m_manifest.epoch.battle_status;
                m_status.lifecycle_live_battle_status = live.battle_status;
                m_status.lifecycle_expected_auto_advance =
                    m_manifest.epoch.auto_advance_armed;
                m_status.lifecycle_live_auto_advance =
                    live.auto_advance_armed;
                m_status.lifecycle_expected_round_start_digest =
                    m_manifest.epoch.round_start_digest;
                m_status.lifecycle_live_round_start_digest =
                    live.round_start_digest;
                const bool next_stock_round =
                    m_config.lifecycle_mode
                        == RollbackLifecycleMode::StockOnlinePvp
                    && RollbackStockRoundResultHandoffEligible(
                        m_manifest.epoch.round_ordinal,
                        m_manifest.epoch.battle_status,
                        live.round_ordinal,
                        live.battle_status,
                        mismatch_mask);
                if (next_stock_round
                    && m_round_terminal_quiesced
                    && m_round_terminal_barrier_complete
                    && m_native_terminal_gate
                        .waiting_for_native_transition())
                {
                    // The accepted native result producer has advanced the
                    // persistent manager. Only the later service observation
                    // may enter StockInterRound.
                    return;
                }
                if (!next_stock_round)
                {
                    fail_closed("lifecycle-token-mismatch");
                    return;
                }
            }
            m_status.stock_round_transition_last_state =
                live.battle_status;
            capture_round_result_diagnostics();
            const RollbackUdpWorkerStatus network = m_network->status();
            if (!verify_active_peer_liveness(network)) return;

            if (m_round_terminal_quiesced)
            {
                auto action = DecideRollbackNativeTerminalBarrierAction(
                    m_round_phase, m_round_terminal_quiesced,
                    m_round_terminal_barrier_complete);
                if (action == RollbackNativeTerminalBarrierAction::Service)
                {
                    if (!service_round_transition_barrier()) return;
                    action = DecideRollbackNativeTerminalBarrierAction(
                        m_round_phase, m_round_terminal_quiesced,
                        m_round_terminal_barrier_complete);
                }
                if (action == RollbackNativeTerminalBarrierAction::Promote)
                {
                    // Freeze this PerFrame call. The next enclosing native
                    // simulation-loop entry is the one accepted stock handoff.
                    set_round_phase(RollbackRoundPhase::TerminalAccepted);
                }
                return;
            }

#if HORSE_ENABLE_GEKKONET
            const bool terminal_proposal_active =
                m_local_round_transition_barrier_valid
                && m_local_round_transition_barrier.stage
                    == RollbackRoundTransitionBarrierStage::Proposed;
            const bool terminal_overlap_complete =
                !m_round_terminal_capture_end.valid
                || !m_current_frame.valid
                || !RollbackFrameIsAfter(
                    m_round_terminal_capture_end.value,
                    m_current_frame.value);
            const RollbackNativeTerminalGekkoPump terminal_pump =
                DecideRollbackNativeTerminalGekkoPump(
                    m_round_phase,
                    m_round_terminal_local_edge_seen,
                    terminal_overlap_complete,
                    terminal_proposal_active,
                    m_round_terminal_pending);
            if (terminal_pump
                == RollbackNativeTerminalGekkoPump::DrainControlOnly)
            {
                const bool control_ok = drain_round_terminal_transport();
                const bool retry_ok = control_ok
                    && resend_terminal_candidate();
                (void)finish_gekko_batch(control_ok && retry_ok);
                return;
            }
            if (terminal_pump
                == RollbackNativeTerminalGekkoPump::CorrectionFlush)
            {
                // The bounded overlap window has closed, or an exact
                // pair-matched candidate has selected the terminal frame.
                // Keep polling, Save/Load, and rollback correction alive
                // without simulating another ordinary frame.
                const bool events_ok =
                    m_gekko.flush_terminal_corrections(
                        args->camera_input);
                m_gekko_session_started = m_gekko.session_started();
                m_status.gekko_ready = m_gekko_session_started;
                m_status.gekko_correction_flush_calls =
                    m_gekko.correction_flush_calls();
                const RollbackUdpWorkerStatus post_flush_network =
                    m_network->status();
                if (!post_flush_network.peer_ready
                    || post_flush_network.failure
                        != RollbackUdpWorkerFailure::None
                    || post_flush_network.handshake_generation
                        != m_session_handshake_generation)
                {
                    fail_closed(
                        "peer-generation-changed-during-terminal-flush");
                    return;
                }
                if (!events_ok
                    && (m_status.state
                            == RollbackProductionState::Active
                        || m_status.state
                            == RollbackProductionState::WaitingForGekko))
                {
                    fail_closed(
                        "gekko-terminal-correction-flush-failed");
                    return;
                }
                if (events_ok && !resend_terminal_candidate())
                    return;
                (void)finish_gekko_batch(events_ok);
                return;
            }
            const uint64_t* source =
                m_config.native_input_source_slot == 0
                ? args->input_p1 : args->input_p2;
            uint64_t native_input = 0;
            if (!source || !SafeReadBytes(source, &native_input,
                                          sizeof(native_input)))
            {
                fail_closed("local-input-read-failed");
                return;
            }
            uint32_t local_input = static_cast<uint32_t>(native_input);
            // The wrapper advances this clock only for Gekko's ordinary
            // Advance event. Rollback and runahead callback frames cannot
            // shift the deterministic fixture schedule.
            const uint64_t fixture_update = m_fixture_clock_armed
                ? m_gekko.next_input_frame()
                : 0u;
            uint64_t fixture_schedule_update = fixture_update;
            if (m_fixture_clock_armed
                && m_config.replay_input.enabled)
            {
                if (!m_fixture_submission_origin_valid)
                {
                    m_fixture_submission_origin = fixture_update;
                    m_fixture_submission_origin_valid = true;
                }
                fixture_schedule_update =
                    fixture_update - m_fixture_submission_origin;
            }
            m_fixture_active_submission_frame =
                static_cast<uint32_t>(fixture_schedule_update);
            bool fixture_barrier_ready = true;
            if (m_fixture_clock_armed
                && !service_fixture_barrier(
                    static_cast<uint32_t>(fixture_schedule_update),
                    fixture_barrier_ready))
            {
                fail_closed("fixture-barrier-service-failed");
                return;
            }
            if (!fixture_barrier_ready)
            {
                m_status.failure = "waiting-for-fixture-barrier";
                return;
            }
            if (m_fixture_clock_armed
                && !m_status.fixture_converged
                && fixture_schedule_update
                    >= m_config.deterministic_input.correction_start)
            {
                m_fixture_correction_pending = true;
            }
            const RollbackFrameStamp& summary_expected =
                m_summary_consensus.expected();
            if (fixture_schedule_update <= UINT32_MAX
                && RollbackProductionSummaryBackpressureRequired(
                    static_cast<uint32_t>(fixture_schedule_update),
                    summary_expected.valid,
                    summary_expected.valid
                        ? summary_expected.value : 0u))
            {
                ++m_status.summary_consensus_backpressure_ticks;
                const bool poll_ok = m_gekko.poll();
                const bool recovery_ok =
                    send_oldest_unacknowledged_summary()
                    && send_summary_ack_window();
                const bool batch_finished =
                    finish_gekko_batch(poll_ok && recovery_ok);
                if (!poll_ok || !recovery_ok || !batch_finished)
                {
                    fail_closed("summary-consensus-backpressure-poll-failed");
                }
                m_gekko_update_calls = m_gekko.update_calls();
                return;
            }
            if (m_fixture_clock_armed)
            {
                if (m_config.replay_input.enabled)
                {
                    uint32_t replay_index = 0;
                    if (!m_replay_input_source.input(
                            m_active_replay_input_config,
                            m_config.local_player_slot,
                            static_cast<uint32_t>(fixture_schedule_update),
                            m_config.input_delay,
                            local_input,
                            replay_index))
                    {
                        const uint64_t proof_end = static_cast<uint64_t>(
                            m_config.deterministic_input.correction_start)
                            + m_config.deterministic_input.hold_updates
                            + m_config.rollback_window;
                        if (fixture_schedule_update <= proof_end)
                        {
                            fail_closed(
                                "replay-input-stream-ended-before-correction");
                            return;
                        }
                        // The selected round is a bounded test script. Once
                        // its correction proof is complete, neutral input is
                        // safer than wrapping into unrelated round data.
                        local_input = kRollbackFixtureNeutralInput;
                        m_status.replay_input_exhausted = true;
                    }
                    else
                    {
                        if (!m_status.replay_input_first_observed)
                        {
                            m_status.replay_input_first_observed = true;
                            m_status.replay_input_first_submission_frame =
                                static_cast<uint32_t>(
                                    fixture_schedule_update);
                            m_status.replay_input_first_index = replay_index;
                        }
                        m_status.replay_input_last_submission_frame =
                            static_cast<uint32_t>(fixture_schedule_update);
                        m_status.replay_input_last_index = replay_index;
                    }
                    ++m_status.replay_input_submissions;
                    if (local_input != 0)
                        ++m_status.replay_input_nonzero_submissions;
                    m_replay_input_submission_hash.add_scalar(replay_index);
                    m_replay_input_submission_hash.add_scalar(local_input);
                    m_status.replay_input_submission_hash =
                        m_replay_input_submission_hash.value;
                }
                else
                {
                    local_input = RollbackFixtureInputForSlot(
                        m_config.deterministic_input,
                        m_config.local_player_slot,
                        fixture_schedule_update,
                        local_input);
                }
            }
            if (m_fixture_clock_armed
                && local_input != 0
                && local_input != static_cast<uint32_t>(native_input))
                ++m_status.fixture_nonzero_inputs;
            const bool fixture_delay_owner =
                m_config.local_player_slot
                    == m_config.deterministic_input.delay_owner_slot;
            if (m_fixture_clock_armed
                && RollbackFixtureShouldBeginDatagramHold(
                    m_config.deterministic_input,
                    m_config.local_player_slot,
                    fixture_schedule_update))
            {
                m_fixture_hold_active = true;
            }
            if (executing_frozen_frame_zero
                && !restore_frame_zero_baseline_before_update())
            {
                fail_closed("frame-zero-baseline-restore-failed");
                return;
            }
            bool events_ok = m_gekko.update(
                local_input, args->camera_input);
            m_gekko_session_started = m_gekko.session_started();
            m_status.gekko_ready = m_gekko_session_started;
            if (m_fixture_hold_active && fixture_delay_owner)
            {
                if (RollbackFixtureShouldReleaseDatagrams(
                        m_config.deterministic_input,
                        fixture_schedule_update + 1u))
                {
                    if (m_fixture_packet_count == 0)
                    {
                        fail_closed("fixture-no-datagrams-held");
                        return;
                    }
                    m_fixture_hold_active = false;
                    if (!release_fixture_datagrams())
                    {
                        fail_closed("fixture-datagram-release-failed");
                        return;
                    }
                }
            }
            m_gekko_update_calls = m_gekko.update_calls();
            const RollbackUdpWorkerStatus post_update_network =
                m_network->status();
            if (!post_update_network.peer_ready
                || post_update_network.failure
                    != RollbackUdpWorkerFailure::None
                || post_update_network.handshake_generation
                    != m_session_handshake_generation)
            {
                fail_closed("peer-generation-changed-during-update");
                return;
            }
            if (!events_ok
                && (m_status.state == RollbackProductionState::Active
                    || m_status.state
                        == RollbackProductionState::WaitingForGekko))
                fail_closed("gekko-event-batch-failed");
            const bool batch_finished = finish_gekko_batch(events_ok);
            if (executing_frozen_frame_zero)
            {
                if (!batch_finished
                    || m_status.state == RollbackProductionState::Fatal)
                {
                    if (m_status.state != RollbackProductionState::Fatal)
                        fail_closed("frozen-frame-zero-batch-incomplete");
                    return;
                }
                // The first peer update can contain only bootstrap traffic.
                // Keep using the retained boundary arguments until Gekko
                // actually emits logical Advance frame 0.
                if (!m_first_advance_frame.valid) return;
                if (m_round_restart_pending_frame_zero
                    && (m_new_round_active_transition_deferred
                        || m_status
                            .native_new_round_transition_release_generation
                            != m_round_generation))
                {
                    fail_closed(
                        "native-new-round-frame-zero-transition-missing");
                    return;
                }
                if (m_first_advance_frame.value != 0)
                {
                    fail_closed("frozen-frame-zero-not-executed");
                    return;
                }
                m_frozen_frame_zero_pending = false;
                m_frozen_frame_zero_args_valid = false;
                if (!m_precontrol_iteration.complete_frame_zero())
                {
                    fail_closed("precontrol-frame-zero-release-invalid");
                    return;
                }
                m_status.precontrol_iteration_frozen = false;
                m_status.precontrol_shutdown_authorized = false;
                ++m_status.precontrol_frame_zero_executions;
                m_native_terminal_gate.begin_round();
                m_terminal_game_flow_notify_manager = 0;
                m_terminal_game_flow_notify_frame.clear();
                m_terminal_game_flow_notification_released = false;
                m_terminal_handoff_clock_aligned = false;
                m_native_inter_round_clock_wait_streak = 0;
                m_terminal_handoff_delta_observation_pending = false;
                m_terminal_handoff_delta_observation_is_first = false;
                set_round_phase(RollbackRoundPhase::Active);
                m_status.state = RollbackProductionState::Active;
                m_status.failure = "ok";
                if (m_round_restart_pending_frame_zero)
                {
                    ++m_status.stock_round_transition_rearms;
                    m_round_restart_pending_frame_zero = false;
                }
            }
#else
            (void)args;
#endif
        }

        bool finish_gekko_batch(bool events_ok) noexcept
        {
#if HORSE_ENABLE_GEKKONET
            // Native presentation dispatch is allowed only after every event
            // in the Gekko batch has completed.
            if (events_ok
                && m_status.state == RollbackProductionState::Active
                && m_pending_effect_confirmation.valid)
            {
                const uint32_t confirmed =
                    m_pending_effect_confirmation.value;
                m_pending_effect_confirmation.clear();
                const bool fixture_target_confirmation =
                    m_fixture_presentation_checkpoint_ready
                    && m_fixture_correction_pending
                    && confirmed == RollbackFixtureCheckpointFrame(
                        m_config.deterministic_input);
                if (fixture_target_confirmation
                    && !m_fixture_checkpoint_gate.begin_confirmation(
                        m_manifest.epoch.generation, confirmed))
                {
                    fail_closed("fixture-checkpoint-confirm-order-invalid");
                    return false;
                }
                if (!m_ledger.confirm_through(
                        m_manifest.epoch.generation,
                        confirmed, &commit_side_effect, this)
                    || !m_ledger.report().ok)
                {
                    fail_closed(m_ledger.report().failure);
                }
                else if (!m_config.native_correction_only
                    && !reconcile_confirmed_breakable_presentation(
                        confirmed))
                {
                    fail_closed(
                        "confirmed-stage-presentation-reconciliation-failed");
                }
                else if (!m_config.native_correction_only
                    && m_model_reconciliation_pending
                    && !reconcile_confirmed_presentation(confirmed))
                {
                    fail_closed("confirmed-model-reconciliation-failed");
                }
                else if (!m_config.native_correction_only
                    && m_model_reconciliation_pending)
                {
                    m_model_reconciliation_pending = false;
                }
                update_presentation_status();
                if (m_fixture_presentation_checkpoint_ready
                    && m_fixture_correction_pending
                    && !m_pending_presentation_checkpoint.valid)
                {
                    const uint32_t target = RollbackFixtureCheckpointFrame(
                        m_config.deterministic_input);
                    if (confirmed != target)
                    {
                        fail_closed("fixture-checkpoint-target-mismatch");
                    }
                    const bool predictor = m_config.local_player_slot
                        != m_config.deterministic_input.delay_owner_slot;
                    const auto& witness =
                        m_fixture_effect_witness.state();
                    const auto& report = m_ledger.report();
                    if (m_status.state != RollbackProductionState::Fatal
                        && RollbackFixtureRequiresFirstLoadEffectWitness(
                            predictor, m_config.replay_input.enabled)
                        && (!witness.valid
                            || witness.epoch
                                != m_manifest.epoch.generation))
                    {
                        fail_closed("fixture-first-load-witness-missing");
                    }
                    if (m_status.state != RollbackProductionState::Fatal
                        && !RollbackFixtureTaggedEvidenceValid(
                            report.fixture_queued_by_type,
                            report.fixture_discarded_by_type,
                            report.fixture_committed_by_type,
                            report.fixture_committed_digest_by_type,
                            predictor,
                            !m_config.replay_input.enabled))
                    {
                        fail_closed(predictor
                            ? "fixture-tagged-effect-conservation-failed"
                            : "fixture-tagged-effect-on-delay-sender");
                    }
                    if (m_status.state != RollbackProductionState::Fatal
                        && !m_fixture_checkpoint_gate.commit_validated(
                            m_manifest.epoch.generation, confirmed))
                    {
                        fail_closed(
                            "fixture-checkpoint-commit-order-invalid");
                    }
                    if (m_status.state != RollbackProductionState::Fatal)
                    {
                        if (!capture_presentation_checkpoint(confirmed))
                        {
                            fail_closed(
                                "presentation-checkpoint-capture-failed");
                        }
                        else
                        {
                            if (!m_fixture_checkpoint_gate
                                    .checkpoint_captured(
                                        m_manifest.epoch.generation,
                                        confirmed))
                            {
                                fail_closed(
                                    "fixture-checkpoint-capture-order-invalid");
                            }
                            else
                            {
                                m_fixture_correction_pending = false;
                                m_fixture_presentation_checkpoint_ready =
                                    false;
                            }
                        }
                    }
                }
                emit_presentation_checkpoint(confirmed);
            }
            if (events_ok
                && m_pending_terminal_candidate_proposal_frame.valid
                && !m_local_round_transition_barrier_valid
                && m_status.state == RollbackProductionState::Active)
            {
                const uint32_t frame =
                    m_pending_terminal_candidate_proposal_frame.value;
                const uint64_t hash =
                    m_pending_terminal_candidate_proposal_hash;
                m_pending_terminal_candidate_proposal_frame.clear();
                m_pending_terminal_candidate_proposal_hash = 0;
                if (!propose_confirmed_round_terminal(frame, hash))
                    return false;
            }
            if (events_ok && !m_config.native_correction_only
                && m_status.state == RollbackProductionState::Active
                && m_local_round_transition_barrier_valid
                && m_local_round_transition_barrier.stage
                    == RollbackRoundTransitionBarrierStage::Proposed)
            {
                events_ok = service_round_terminal_proposal();
            }
            if (events_ok && !m_config.native_correction_only
                && m_round_terminal_pending
                && m_status.state == RollbackProductionState::Active)
            {
                const RollbackFrameStamp& next_expected =
                    m_summary_consensus.expected();
                bool terminal_tail_ready = false;
                if (!inspect_terminal_pair_proof_tail(terminal_tail_ready))
                    return false;
                const auto action =
                    DecideRollbackProductionTerminalFrontierAction(
                        m_round_terminal_pending,
                        m_round_terminal_quiesced,
                        next_expected.valid,
                        next_expected.valid ? next_expected.value : 0,
                        m_last_summary_published.valid,
                        m_last_summary_published.valid
                            ? m_last_summary_published.value : 0,
                        terminal_tail_ready,
                        m_terminal_pair_proof_tail_finalized,
                        m_status.stock_round_terminal_confirmed_frame);
                if (action
                    == RollbackProductionTerminalFrontierAction::PollAndRetry)
                {
                    // Keep the correction/idle pump alive while the separately
                    // authenticated terminal-tail evidence is incomplete.
                    // Ordinary summary consensus is frozen after agreement.
                    return true;
                }
                if (action
                    == RollbackProductionTerminalFrontierAction::
                        FinalizePairProofTail)
                {
                    // This schedules confirmed presentation through the agreed
                    // terminal frame. A second batch/service pass commits those
                    // effects before restoring and quiescing the round.
                    return finalize_terminal_pair_proof_tail();
                }
                if (action != RollbackProductionTerminalFrontierAction::Quiesce)
                {
                    fail_closed("terminal-frontier-action-invalid");
                    return false;
                }
                return quiesce_confirmed_round_terminal();
            }
            return events_ok
                && m_status.state != RollbackProductionState::Fatal;
#else
            (void)events_ok;
            return false;
#endif
        }

#if HORSE_ENABLE_GEKKONET
        bool process_game_event(
            GekkoGameEvent& event,
            const void* camera_input) noexcept
        {
            if (m_status.state != RollbackProductionState::Active
                && m_status.state != RollbackProductionState::WaitingForGekko)
                return false;
            switch (event.type)
            {
            case GekkoSaveEvent:
                return process_save(event);
            case GekkoLoadEvent:
                return process_load(event);
            case GekkoAdvanceEvent:
                return process_advance(event, camera_input);
            default:
                return true;
            }
        }

        bool process_save(GekkoGameEvent& event) noexcept
        {
            if (!event.data.save.state
                || !event.data.save.state_len || !event.data.save.checksum)
            {
                fail_closed("invalid-gekko-save-event");
                return false;
            }
            uint32_t frame = 0;
            if (!RollbackGekkoStateFrameToKey(
                    event.data.save.frame, frame))
            {
                fail_closed("gekko-signed-frame-ceiling-reached");
                return false;
            }
            const bool baseline = event.data.save.frame
                == kRollbackGekkoBaselineFrame;
            if (!baseline)
            {
                RollbackObserveGekkoFrame(
                    m_gekko_frame_high_water, frame);
            }
            if ((!baseline && (!m_current_frame.valid
                              || m_current_frame.value != frame))
                || (baseline && m_current_frame.valid
                    && m_current_frame.value != frame))
            {
                fail_closed("gekko-save-live-frame-mismatch");
                return false;
            }
            if (m_post_advance_frame.valid
                && m_post_advance_frame.value == frame
                && m_post_advance_epoch == m_manifest.epoch.generation)
            {
                // Advance already captured this exact frame directly into the
                // reusable provisional slot. Save only commits it.
            }
            else
            {
                RollbackStepStateReport captured {};
                {
                    RollbackNanosecondCounterScope capture_timing(
                        m_status.state_capture_nanoseconds,
                        m_status.state_capture_calls);
                    captured = CaptureRollbackStepState(
                        m_image_base,
                        m_manifest,
                        m_post_advance_state,
                        m_config.lifecycle_mode,
                        false,
                        &m_stage_identity,
                        &m_capture_scratch.hgcpu,
                        &m_snapshot_capacity_limits,
                        m_native_callback_coverage.input_state_object,
                        &m_stage_wind_pool,
                        &m_palette_variant_writer_registry,
                        &m_presentation_semantic_identity);
                    if (captured.native_input_callback_ok)
                        ++m_status.native_input_callback_snapshot_captures;
                }
                m_status.explicit_capture_nanoseconds +=
                    captured.explicit_capture_nanoseconds;
                m_status.hgcpu_capture_nanoseconds +=
                    captured.hgcpu_capture_nanoseconds;
                m_status.explicit_cleanup_nanoseconds +=
                    captured.explicit_cleanup_nanoseconds;
                m_status.stage_capture_nanoseconds +=
                    captured.stage_capture_nanoseconds;
                m_status.wind_capture_nanoseconds +=
                    captured.wind_capture_nanoseconds;
                m_status.capture_finalize_nanoseconds +=
                    captured.capture_finalize_nanoseconds;
                m_status.hgcpu_emergency_capture_nanoseconds +=
                    captured.hgcpu_report.emergency_capture_nanoseconds;
                m_status.hgcpu_native_capture_nanoseconds +=
                    captured.hgcpu_report.native_capture_nanoseconds;
                m_status.hgcpu_emergency_restore_nanoseconds +=
                    captured.hgcpu_report.emergency_restore_nanoseconds;
                m_status.hgcpu_khit_capture_nanoseconds +=
                    captured.hgcpu_report.khit_capture_nanoseconds;
                m_status.hgcpu_timer_capture_nanoseconds +=
                    captured.hgcpu_report.timer_capture_nanoseconds;
                m_status.hgcpu_hash_finalize_nanoseconds +=
                    captured.hgcpu_report.hash_finalize_nanoseconds;
                if (!captured.ok)
                {
                    fail_closed(captured.failure);
                    return false;
                }
                mark_snapshot_capture_coverage();
            }
            if (baseline)
            {
                const RollbackFrameZeroBaselineSnapshot saved_baseline =
                    frame_zero_snapshot(m_post_advance_state);
                m_status.frame_zero_save_lcg =
                    saved_baseline.rng.lcg_state;
                m_status.frame_zero_save_lfsr_hash =
                    saved_baseline.rng.lfsr_hash;
                m_status.frame_zero_save_lfsr_index =
                    saved_baseline.rng.lfsr_index;
                uint32_t source_index = UINT32_MAX;
                (void)m_active_replay_input_config.consumed_index(
                    0, m_config.input_delay, source_index);
                emit_rng_checkpoint(
                    "gekko-baseline-save", saved_baseline.rng, 0,
                    source_index, saved_baseline.canonical_hash);
                emit_stage_wind_phase_diagnostic(
                    "gekko-save-minus-one",
                    m_post_advance_state.stage_wind);
                if (m_frame_zero_baseline_gate.record_baseline_save(
                        saved_baseline)
                    != RollbackFrameZeroBaselineResult::Accepted)
                {
                    RngTraceHook::instance().discard_window();
                    ++m_status.frame_zero_checkpoint_failures;
                    fail_closed("gekko-baseline-save-mismatch");
                    return false;
                }
                m_status.frame_zero_baseline_save_verified = true;
                m_status.frame_zero_baseline_phase =
                    static_cast<uint8_t>(
                        m_frame_zero_baseline_gate.phase());
                if (m_round_generation == 1)
                {
                    if (!verify_initial_new_round_baseline_save(
                            m_post_advance_state.explicit_snapshot))
                        return false;
                }
                else if (m_round_restart_pending_frame_zero)
                {
                    if (!verify_new_round_baseline_save(
                            m_post_advance_state.explicit_snapshot))
                        return false;
                }
                else
                {
                    fail_closed("new-round-baseline-context-invalid");
                    return false;
                }
            }
            else if (frame <= 3)
            {
                emit_stage_wind_phase_diagnostic(
                    "gekko-save-post-advance",
                    m_post_advance_state.stage_wind);
            }
            if ((m_store.occupied() == 0
                    && !m_store.prepare(
                        m_post_advance_state, m_config.rollback_window))
                || (m_terminal_store.occupied() == 0
                    && !m_terminal_store.prepare(
                        m_post_advance_state, m_config.rollback_window)))
            {
                fail_closed("snapshot-arena-prepare-failed");
                return false;
            }
            RollbackSnapshotHandle handle {};
            const RollbackSnapshotStoreReport saved = m_store.save_recycling(
                m_manifest.epoch.generation,
                frame,
                m_post_advance_state.combined_hash,
                m_post_advance_state.canonical_hash,
                m_post_advance_state,
                m_current_frame.valid ? m_current_frame
                                      : RollbackFrameStamp::From(frame),
                m_config.rollback_window,
                handle);
            if (!saved.ok)
            {
                fail_closed(saved.failure);
                return false;
            }
            // save_recycling swapped in the arena slot's empty, preallocated
            // buffers. Keep them for the next Advance capture.
            m_post_advance_state.recycle_for_capture();
            m_post_advance_frame.clear();
            m_post_advance_epoch = 0;
            std::memcpy(event.data.save.state, &handle, sizeof(handle));
            *event.data.save.state_len = sizeof(handle);
            *event.data.save.checksum = static_cast<uint32_t>(
                handle.canonical_hash ^ (handle.canonical_hash >> 32));
            ++m_status.saves;
            return true;
        }

        bool revoke_terminal_candidate_authority(uint32_t frame) noexcept
        {
            const size_t slot =
                frame & kRollbackProductionFrameHistoryMask;
            if (m_pair_terminal_candidate_valid[slot]
                && m_pair_terminal_candidate_frame[slot] == frame)
            {
                m_pair_terminal_candidate_valid[slot] = false;
                m_pair_terminal_candidate_frame[slot] = 0;
                m_pair_terminal_candidate_hash[slot] = 0;
            }
            if (m_pending_terminal_candidate_proposal_frame.valid
                && m_pending_terminal_candidate_proposal_frame.value == frame)
            {
                m_pending_terminal_candidate_proposal_frame.clear();
                m_pending_terminal_candidate_proposal_hash = 0;
            }
            if (m_round_terminal_candidate_frame.valid
                && m_round_terminal_candidate_frame.value == frame)
            {
                m_round_terminal_candidate_pair_matched = false;
                m_round_terminal_candidate_frame.clear();
                m_round_terminal_candidate_handle = {};
                m_status.stock_round_terminal_candidate_pair_matched = false;
                m_status.stock_round_terminal_candidate_handle_valid = false;
                m_status.stock_round_terminal_candidate_frame = 0;
                m_status.stock_round_terminal_candidate_generation = 0;
            }
            const bool local_selected =
                m_local_round_transition_barrier_valid
                && m_local_round_transition_barrier.confirmed_frame == frame;
            const bool remote_selected =
                m_remote_round_transition_barrier_valid
                && m_remote_round_transition_barrier.confirmed_frame == frame;
            if ((local_selected || remote_selected)
                && (m_round_terminal_pending || m_round_terminal_quiesced))
            {
                fail_closed("terminal-candidate-replaced-after-agreement");
                return false;
            }
            if (local_selected)
            {
                if (m_local_round_transition_barrier.stage
                    != RollbackRoundTransitionBarrierStage::Proposed)
                {
                    fail_closed("terminal-candidate-replaced-after-restore");
                    return false;
                }
                m_local_round_transition_barrier = {};
                m_local_round_transition_barrier_valid = false;
                m_status.stock_round_terminal_local_stage = 0;
                m_status.stock_round_terminal_local_tail_start = 0;
                m_status.stock_round_terminal_resend_start = 0;
                m_status.stock_round_terminal_confirmed_frame = 0;
                m_status.stock_round_terminal_canonical_hash = 0;
                m_status.stock_round_transition_wait_ticks = 0;
            }
            if (remote_selected)
            {
                if (m_remote_round_transition_barrier.stage
                    != RollbackRoundTransitionBarrierStage::Proposed)
                {
                    fail_closed("peer-terminal-candidate-replaced-after-restore");
                    return false;
                }
                m_remote_round_transition_barrier = {};
                m_remote_round_transition_barrier_valid = false;
                m_status.stock_round_terminal_peer_stage = 0;
                m_status.stock_round_terminal_peer_tail_start = 0;
            }
            return true;
        }

        bool can_invalidate_terminal_candidates_after(
            uint32_t frame) const noexcept
        {
            return !(m_local_round_transition_barrier_valid
                && RollbackFrameIsAfter(
                    m_local_round_transition_barrier.confirmed_frame,
                    frame)
                && (m_round_terminal_quiesced
                    || m_local_round_transition_barrier.stage
                        != RollbackRoundTransitionBarrierStage::Proposed));
        }

        bool invalidate_terminal_candidates_after(uint32_t frame) noexcept
        {
            bool invalidates_proposal = false;
            if (m_pending_terminal_candidate_proposal_frame.valid
                && RollbackFrameIsAfter(
                    m_pending_terminal_candidate_proposal_frame.value,
                    frame))
            {
                m_pending_terminal_candidate_proposal_frame.clear();
                m_pending_terminal_candidate_proposal_hash = 0;
            }
            m_terminal_candidate_resend_frame.clear();
            if (m_local_round_transition_barrier_valid
                && RollbackFrameIsAfter(
                    m_local_round_transition_barrier.confirmed_frame,
                    frame))
            {
                invalidates_proposal = true;
                if (m_round_terminal_quiesced
                    || m_local_round_transition_barrier.stage
                        != RollbackRoundTransitionBarrierStage::Proposed)
                {
                    fail_closed(
                        "terminal-candidate-load-after-restore");
                    return false;
                }
            }
            for (size_t slot = 0;
                 slot < kRollbackProductionSummaryWindowCapacity; ++slot)
            {
                if (m_remote_terminal_candidate_valid[slot]
                    && RollbackFrameIsAfter(
                        m_remote_terminal_candidates[slot].frame, frame))
                {
                    m_remote_terminal_candidate_valid[slot] = false;
                }
                if (m_pair_terminal_candidate_valid[slot])
                {
                    const uint32_t candidate_frame =
                        m_pair_terminal_candidate_frame[slot];
                    if (RollbackFrameIsAfter(candidate_frame, frame))
                    {
                        m_pair_terminal_candidate_valid[slot] = false;
                        m_pair_terminal_candidate_frame[slot] = 0;
                        m_pair_terminal_candidate_hash[slot] = 0;
                    }
                }
            }
            if (m_round_terminal_candidate_frame.valid
                && RollbackFrameIsAfter(
                    m_round_terminal_candidate_frame.value, frame))
            {
                m_round_terminal_candidate_pair_matched = false;
                m_round_terminal_candidate_frame.clear();
                m_round_terminal_candidate_handle = {};
                m_status.stock_round_terminal_candidate_pair_matched = false;
                m_status.stock_round_terminal_candidate_handle_valid = false;
                m_status.stock_round_terminal_candidate_frame = 0;
                m_status.stock_round_terminal_candidate_generation = 0;
            }
            if (invalidates_proposal)
            {
                m_local_round_transition_barrier = {};
                m_remote_round_transition_barrier = {};
                m_local_round_transition_barrier_valid = false;
                m_remote_round_transition_barrier_valid = false;
                m_round_terminal_pending = false;
                m_status.stock_round_terminal_local_stage = 0;
                m_status.stock_round_terminal_peer_stage = 0;
                m_status.stock_round_terminal_confirmed_frame = 0;
                m_status.stock_round_terminal_canonical_hash = 0;
                m_status.stock_round_transition_wait_ticks = 0;
            }
            return true;
        }

        bool process_load(
            GekkoGameEvent& event,
            bool terminal_checkpoint = false) noexcept
        {
            if (event.data.load.state_len
                    != sizeof(RollbackSnapshotHandle)
                || !event.data.load.state)
            {
                fail_closed("invalid-gekko-load-event");
                return false;
            }
            uint32_t frame = 0;
            if (!RollbackGekkoStateFrameToKey(
                    event.data.load.frame, frame))
            {
                fail_closed("gekko-signed-frame-ceiling-reached");
                return false;
            }
            if (event.data.load.frame != kRollbackGekkoBaselineFrame)
                RollbackObserveGekkoFrame(m_gekko_frame_high_water, frame);
            RollbackSnapshotHandle handle {};
            std::memcpy(&handle, event.data.load.state, sizeof(handle));
            if (handle.frame != frame)
            {
                fail_closed("gekko-load-frame-handle-mismatch");
                return false;
            }
            const RollbackStepState* state = nullptr;
            const RollbackSnapshotStoreReport loaded = terminal_checkpoint
                ? m_terminal_store.load(handle, state)
                : m_store.load(handle, state);
            if (!loaded.ok || !state
                || handle.epoch != m_manifest.epoch.generation)
            {
                fail_closed(!loaded.ok ? loaded.failure
                    : "gekko-load-epoch-mismatch");
                return false;
            }
            const bool rolled_back_terminal_edge =
                RollbackDiscardedJournaledTerminalEdge(
                    m_round_terminal_local_edge_seen,
                    m_round_terminal_local_edge_frame.valid,
                    m_round_terminal_local_edge_frame.value,
                    handle.frame);
            const bool rolled_back_terminal_notification =
                RollbackShouldDiscardDeferredTerminalNotification(
                    m_terminal_game_flow_notify_frame, handle.frame);
            if (!CanInvalidateRollbackProductionSummariesAfter(
                    m_local_summaries, m_local_summary_valid,
                    handle.frame))
            {
                fail_closed("gekko-load-after-confirmed-summary");
                return false;
            }
            if (!can_invalidate_terminal_candidates_after(handle.frame))
            {
                fail_closed("terminal-candidate-load-after-restore");
                return false;
            }
            if (rolled_back_terminal_edge)
            {
                const auto target_queue_disposition =
                    ClassifyRollbackNativeRoundStateQueue(
                        state->native_round_state.current_state,
                        state->native_round_state.count == 0
                            ? nullptr
                            : state->native_round_state.entries.data(),
                        state->native_round_state.count,
                        state->native_round_state.count);
                if (target_queue_disposition
                    == RollbackNativeRoundStateQueueDisposition::
                        TerminalTransition)
                {
                    fail_closed(
                        "terminal-edge-load-restored-terminal-queue");
                    return false;
                }
            }
            if (rolled_back_terminal_notification
                && !m_native_terminal_gate
                        .can_discard_game_flow_notification())
            {
                fail_closed(
                    "native-terminal-notification-discard-after-release");
                return false;
            }
            // Save F is captured after Advance F. Load F resumes at F+1, so
            // frame-F effects belong to the restored state and must survive.
            std::array<uint32_t, 4> pending_first {};
            std::array<uint32_t, 4> pending_last {};
            std::array<uint32_t, 4> pending_count {};
            static constexpr RollbackSideEffectType observed_types[] = {
                RollbackSideEffectType::Audio,
                RollbackSideEffectType::Vfx,
                RollbackSideEffectType::Camera,
                RollbackSideEffectType::ConfirmedTransition,
            };
            for (size_t i = 0; i < std::size(observed_types); ++i)
            {
                (void)m_ledger.pending_frame_range(
                    observed_types[i], pending_first[i], pending_last[i],
                    pending_count[i]);
            }
            const auto presentation_before_load = m_ledger.report();
            std::array<uint32_t, 4> discarded_first {};
            std::array<uint32_t, 4> discarded_last {};
            std::array<uint32_t, 4> discarded_count {};
            std::array<uint64_t, 4> discarded_digest {};
            for (size_t i = 0; i < std::size(observed_types); ++i)
            {
                (void)m_ledger.pending_frame_range_after(
                    handle.epoch, observed_types[i], handle.frame,
                    discarded_first[i], discarded_last[i],
                    discarded_count[i]);
                uint32_t witness_count = 0;
                (void)m_ledger.pending_witness_after(
                    handle.epoch, observed_types[i], handle.frame,
                    witness_count, discarded_digest[i]);
                if (witness_count != discarded_count[i])
                {
                    fail_closed("presentation-discard-witness-count-mismatch");
                    return false;
                }
            }
            bool arm_fixture_correction = false;
            const bool possible_fixture_load = m_fixture_correction_pending
                && m_config.local_player_slot
                    != m_config.deterministic_input.delay_owner_slot
                && !m_fixture_effect_witness.state().valid
                && RollbackFixtureLoadAffectsEvidence(
                    m_config.deterministic_input, m_config.input_delay,
                    handle.frame);
            if (possible_fixture_load)
            {
                std::array<uint64_t, 4> witness_count {};
                for (size_t i = 0; i < std::size(observed_types); ++i)
                {
                    witness_count[i] = discarded_count[i];
                }
                const uint32_t affected_frame = handle.frame
                        < m_config.deterministic_input.correction_start
                    ? m_config.deterministic_input.correction_start
                    : m_config.deterministic_input.correction_start + 1u;
                const auto& predicted =
                    m_input_history[
                        affected_frame
                            & kRollbackProductionFrameHistoryMask];
                if (m_gekko_frame_high_water.valid
                    && predicted.valid && predicted.epoch == handle.epoch
                    && predicted.frame == affected_frame)
                {
                    arm_fixture_correction = true;
                }
            }
            // Re-resolve the complete weak-callback graph immediately before
            // the restore corridor. This is the atomic identity preflight for
            // lifecycle-local presentation fields; no native state has been
            // mutated on this Load path yet.
            if (!inventory_presentation_listener_targets()
                || !state->presentation_semantic.valid
                || !m_presentation_semantic_identity.same_identity_as(
                    state->presentation_semantic.identity))
            {
                fail_closed(
                    "presentation-semantic-load-preflight-failed");
                return false;
            }
            m_post_advance_state.recycle_for_capture();
            m_post_advance_frame.clear();
            m_post_advance_epoch = 0;
            m_emergency_restore_state.recycle_for_capture();
            const uint64_t emergency_capacity_before =
                RollbackStepStateCapacityHash(
                    m_emergency_restore_state);
            const uint64_t verification_capacity_before =
                RollbackStepStateCapacityHash(m_verification_state);
            const RollbackStepStateReport restored = RestoreRollbackStepState(
                m_image_base, *state, true, m_config.lifecycle_mode,
                false, true, &m_verification_state,
                &m_capture_scratch.hgcpu, &m_stage_wind_pool,
                &m_palette_variant_writer_registry,
                &m_emergency_restore_state,
                &m_presentation_semantic_identity);
            if (restored.native_input_callback_ok)
                ++m_status.native_input_callback_snapshot_restores;
            m_status.restore_nanoseconds += restored.restore_nanoseconds;
            ++m_status.restore_calls;
            m_status.verification_nanoseconds +=
                restored.verification_nanoseconds;
            ++m_status.verification_calls;
            const bool verification_matches =
                restored.verification_ok
                && restored.verification_canonical_hash
                    == handle.canonical_hash;
            if (!restored.ok)
            {
                const auto& compare =
                    restored.verification_hgcpu_compare;
                ReplayTraceFields fields;
                fields.string("failure", restored.failure)
                    .uinteger("local_player_slot",
                              m_config.local_player_slot)
                    .uinteger("frame", frame)
                    .hex("handle_canonical_hash", handle.canonical_hash)
                    .hex("expected_canonical_hash",
                         restored.expected_canonical_hash)
                    .hex("verification_canonical_hash",
                         restored.verification_canonical_hash)
                    .hex("expected_explicit_hash",
                         restored.expected_explicit_hash)
                    .hex("verification_explicit_hash",
                         restored.verification_explicit_hash)
                    .hex("expected_stage_hash",
                         restored.expected_stage_hash)
                    .hex("verification_stage_hash",
                         restored.verification_stage_hash)
                    .hex("expected_wind_hash",
                         state->stage_wind.canonical_hash)
                    .hex("verification_wind_hash",
                         m_verification_state.stage_wind.canonical_hash)
                    .boolean("hgcpu_policy_match",
                             compare.policy_match)
                    .boolean("hgcpu_hash_match", compare.hash_match)
                    .boolean("hgcpu_topology_match",
                             compare.topology_match)
                    .hex("expected_hgcpu_hash",
                         state->hgcpu.canonical_hash)
                    .hex("verification_hgcpu_hash",
                         m_verification_state.hgcpu.canonical_hash)
                    .hex("expected_khit_topology_hash",
                         compare.topology_hash_a)
                    .hex("verification_khit_topology_hash",
                         compare.topology_hash_b)
                    .boolean("motion_bank_match",
                             compare.motion_bank_match)
                    .boolean("motion_tail_match",
                             compare.motion_tail_match)
                    .boolean("secondary_event_stack_match",
                             compare.secondary_event_stack_match)
                    .boolean("timer_node_match",
                             compare.timer_node_match)
                    .uinteger("hgcpu_mismatch_count",
                              compare.mismatch_count)
                    .uinteger("hgcpu_unignored_mismatch_count",
                              compare.unignored_mismatch_count)
                    .uinteger("first_unignored_mismatch_offset",
                              compare.first_unignored_mismatch_offset)
                    .string("first_ignored_reason",
                            compare.first_ignored_reason)
                    .boolean("frame_counter_match",
                             m_verification_state.frame_counter
                                 == state->frame_counter)
                    .boolean("latest_input_match",
                             std::memcmp(
                                 m_verification_state.latest_input,
                                 state->latest_input,
                                 sizeof(state->latest_input)) == 0)
                    .boolean("camera_args_match",
                             std::memcmp(
                                 m_verification_state.camera_args,
                                 state->camera_args,
                                 sizeof(state->camera_args)) == 0);
                ReplayDebugTrace::instance().event(
                    "rollback_restore_verification_failure", fields);
                fail_closed(restored.failure);
                return false;
            }

            auto reject_after_native_restore =
                [&](const char* failure) noexcept {
                    m_verification_state.recycle_for_capture();
                    const RollbackStepStateReport undo =
                        RestoreRollbackStepState(
                            m_image_base, m_emergency_restore_state, false,
                            m_config.lifecycle_mode, false, true,
                            &m_verification_state,
                            &m_capture_scratch.hgcpu,
                            &m_stage_wind_pool,
                            &m_palette_variant_writer_registry, nullptr,
                            &m_presentation_semantic_identity);
                    const bool undo_verified = undo.ok
                        && undo.verification_ok
                        && undo.verification_canonical_hash
                            == m_emergency_restore_state.canonical_hash
                        && RollbackStepStateCapacityHash(
                                m_verification_state)
                            == verification_capacity_before
                        && RollbackStepStateCapacityHash(
                                m_emergency_restore_state)
                            == emergency_capacity_before
                        && repair_native_derived_callback_state();
                    fail_closed(undo_verified
                        ? failure : "rollback-load-emergency-undo-failed");
                    return false;
                };

            if (RollbackStepStateCapacityHash(m_verification_state)
                    != verification_capacity_before)
                return reject_after_native_restore(
                    "rollback-verification-capacity-growth");
            if (!restored.emergency_captured
                || RollbackStepStateCapacityHash(
                        m_emergency_restore_state)
                    != emergency_capacity_before)
                return reject_after_native_restore(
                    "rollback-emergency-capacity-growth");
            if (!verification_matches)
            {
                return reject_after_native_restore(
                    "gekko-load-canonical-restore-mismatch");
            }
            // Align the deferred terminal journal with the restored native
            // grace state before validating callback coverage. A Load before
            // the producer restores grace 0 and discards the future notice;
            // a Load of the producer frame preserves both notice and grace.
            const RollbackNativeLoadRepairResult load_repair =
                CompleteRollbackNativeLoadRepair(
                    restored.ok, verification_matches,
                    [this]() noexcept {
                        return repair_native_derived_callback_state();
                    });
            // The final stock simulation callback rebuilds ALuxActor's
            // cached move-property maps after PerFrame. Those caches are
            // derived from the authoritative provider and are intentionally
            // excluded from the gameplay snapshot. Rebuild them immediately
            // after Load so the first rollback Advance cannot observe cache
            // values from the discarded speculative future.
            if (load_repair
                != RollbackNativeLoadRepairResult::Repaired)
            {
                return reject_after_native_restore(
                    "gekko-load-derived-callback-repair-failed");
            }

            // Commit local rollback bookkeeping only after native restore,
            // exact recapture, and derived-state repair have all succeeded.
            // Every rejecting condition above is read-only or has a complete
            // preallocated native undo path.
            if (rolled_back_terminal_notification
                && !m_native_terminal_gate
                        .discard_game_flow_notification())
            {
                return reject_after_native_restore(
                    m_native_terminal_gate.report().failure);
            }
            if (!InvalidateRollbackProductionSummariesAfter(
                    m_local_summaries, m_local_summary_valid, handle.frame))
            {
                return reject_after_native_restore(
                    "gekko-load-after-confirmed-summary");
            }
            if (!invalidate_terminal_candidates_after(handle.frame))
                return reject_after_native_restore(
                    "terminal-candidate-load-after-restore");
            if (rolled_back_terminal_edge)
            {
                m_round_terminal_local_edge_seen = false;
                m_round_terminal_local_result_type = 0;
                m_round_terminal_local_edge_frame.clear();
                m_round_terminal_capture_end.clear();
            }
            if (rolled_back_terminal_notification)
            {
                m_terminal_game_flow_notify_manager = 0;
                m_terminal_game_flow_notify_frame.clear();
                m_terminal_game_flow_notification_released = false;
                sync_native_terminal_gate_status();
            }

            m_ledger.rollback_after(handle.epoch, handle.frame);
            (void)m_audio_playback_map.discard_reserved_after(
                handle.epoch, handle.frame);
            m_vfx_slot_shadow.discard_reserved_after(
                handle.epoch, handle.frame);
            const auto& presentation_after_load = m_ledger.report();
            if (arm_fixture_correction)
            {
                std::array<uint64_t, 4> witness_count {};
                for (size_t i = 0; i < std::size(observed_types); ++i)
                    witness_count[i] = discarded_count[i];
                const uint32_t affected_frame = handle.frame
                        < m_config.deterministic_input.correction_start
                    ? m_config.deterministic_input.correction_start
                    : m_config.deterministic_input.correction_start + 1u;
                const auto& predicted = m_input_history[
                    affected_frame
                        & kRollbackProductionFrameHistoryMask];
                if (m_fixture_correction_gate.arm(
                        m_config.deterministic_input,
                        m_config.input_delay, handle.epoch, handle.frame,
                        m_gekko_frame_high_water.value, predicted.input,
                        discarded_first, witness_count,
                        discarded_digest))
                {
                    ++m_status.fixture_load_candidates;
                }
            }
            ReplayTraceFields presentation_load;
            presentation_load
                .uinteger("load_frame", handle.frame)
                .uinteger("audio_first", pending_first[0])
                .uinteger("audio_last", pending_last[0])
                .uinteger("audio_pending", pending_count[0])
                .uinteger("vfx_first", pending_first[1])
                .uinteger("vfx_last", pending_last[1])
                .uinteger("vfx_pending", pending_count[1])
                .uinteger("camera_first", pending_first[2])
                .uinteger("camera_last", pending_last[2])
                .uinteger("camera_pending", pending_count[2])
                .uinteger("transition_first", pending_first[3])
                .uinteger("transition_last", pending_last[3])
                .uinteger("transition_pending", pending_count[3])
                .uinteger("discarded_before",
                    presentation_before_load.discarded)
                .uinteger("discarded_after",
                    presentation_after_load.discarded);
            ReplayDebugTrace::instance().event(
                "rollback_presentation_load_boundary", presentation_load);
            m_status.last_restore_expected_hash = handle.canonical_hash;
            m_status.last_restore_observed_hash =
                restored.verification_canonical_hash;
            m_status.final_restore_verified = true;
            if (event.data.load.frame == kRollbackGekkoBaselineFrame)
                m_status.baseline_restore_verified = true;
            else
                m_status.prediction_restore_verified = true;
            m_current_frame = handle.frame;
            ++m_status.loads;
            m_model_reconciliation_pending =
                !m_config.native_correction_only;
            m_stage_reconciliation_pending =
                !m_config.native_correction_only;
            return true;
        }

        bool process_advance(
            GekkoGameEvent& event,
            const void* camera_input) noexcept
        {
            if (event.data.adv.frame >= 0
                && !RollbackGekkoFrameIsProductionSafe(
                    event.data.adv.frame))
            {
                fail_closed("gekko-signed-frame-ceiling-reached");
                return false;
            }
            const RollbackGekkoGameplayInputDecodeReport decoded =
                DecodeRollbackGekkoGameplayInputs(
                    event.data.adv.frame,
                    event.data.adv.inputs,
                    event.data.adv.input_len,
                    2);
            if (!decoded.ok)
            {
                fail_closed(decoded.failure);
                return false;
            }
            RollbackObserveGekkoFrame(
                m_gekko_frame_high_water, decoded.frame);
            RollbackDecodedGameplayInput p0 {};
            RollbackDecodedGameplayInput p1 {};
            if (!GetRollbackGekkoDecodedGameplayInput(decoded, 0, p0)
                || !GetRollbackGekkoDecodedGameplayInput(decoded, 1, p1))
            {
                fail_closed("gekko-player-input-missing");
                return false;
            }
            const std::array<uint32_t, 2> compact_input {
                p0.input_value, p1.input_value,
            };
            const uint32_t frame = static_cast<uint32_t>(event.data.adv.frame);
            std::array<uint32_t, 2> authored_fixture_input {};
            bool authored_fixture_input_valid = false;
            if (m_config.replay_input.enabled)
            {
                std::array<uint32_t, 2> expected {};
                uint32_t expected_index = 0;
                bool neutral_tail = false;
                for (uint8_t slot = 0; slot < 2; ++slot)
                {
                    uint32_t slot_index = 0;
                    bool slot_neutral_tail = false;
                    if (!m_replay_input_source.consumed_input_or_neutral_tail(
                            m_active_replay_input_config, slot, frame,
                            m_config.input_delay, expected[slot], slot_index,
                            slot_neutral_tail)
                        || (slot != 0 && slot_index != expected_index))
                    {
                        fail_closed("replay-consumed-input-unavailable");
                        return false;
                    }
                    neutral_tail = neutral_tail || slot_neutral_tail;
                    expected_index = slot_index;
                }
                if (neutral_tail)
                    ++m_status.replay_consumed_neutral_tail_checks;
                authored_fixture_input = expected;
                authored_fixture_input_valid = true;
                ++m_status.replay_prediction_checks;
                if (!m_status.replay_first_consumed_observed)
                {
                    m_status.replay_first_consumed_observed = true;
                    m_status.replay_first_consumed_logical_frame = frame;
                    m_status.replay_first_consumed_index = expected_index;
                    for (uint8_t slot = 0; slot < 2; ++slot)
                    {
                        m_status.replay_first_consumed_expected[slot] =
                            expected[slot];
                        m_status.replay_first_consumed_actual[slot] =
                            compact_input[slot];
                    }
                }
                if (frame == 0
                    && !m_status.replay_round_frame_zero_observed)
                {
                    m_status.replay_round_frame_zero_observed = true;
                    m_status.replay_round_frame_zero_logical_frame = frame;
                    m_status.replay_round_frame_zero_source_index =
                        expected_index;
                    m_status.replay_round_frame_zero_replay_round =
                        m_active_replay_input_config.round_index;
                    m_status.replay_round_frame_zero_generation =
                        m_round_generation;
                    for (uint8_t slot = 0; slot < 2; ++slot)
                    {
                        m_status.replay_round_frame_zero_expected[slot] =
                            expected[slot];
                        m_status.replay_round_frame_zero_actual[slot] =
                            compact_input[slot];
                    }
                }
                if (compact_input != expected)
                {
                    // Remote inputs are allowed to differ while predicted.
                    // Exact replay alignment is enforced only after the pair
                    // crosses the contiguous confirmation frontier below.
                    ++m_status.replay_prediction_mismatches;
                }
            }
            else if (RollbackFixtureUpdateActive(
                    m_config.deterministic_input, frame))
            {
                for (uint8_t slot = 0; slot < 2; ++slot)
                {
                    authored_fixture_input[slot] =
                        RollbackFixtureInputForSlot(
                            m_config.deterministic_input, slot, frame, 0);
                }
                authored_fixture_input_valid = true;
            }
            if (authored_fixture_input_valid)
            {
                const RollbackFixtureCorrectionAction correction_action =
                    m_fixture_correction_gate.observe_advance(
                        m_manifest.epoch.generation, frame,
                        event.data.adv.rolling_back, compact_input,
                        authored_fixture_input,
                        m_config.deterministic_input.delay_owner_slot);
                if (correction_action
                    == RollbackFixtureCorrectionAction::Promoted)
                {
                    ++m_status.fixture_load_promotions;
                    const RollbackFixtureCorrectionCandidate candidate =
                        m_fixture_correction_gate.candidate();
                    if (!m_fixture_effect_witness.begin_load(
                            candidate.epoch, candidate.load_frame,
                            candidate.discarded_count,
                            candidate.discarded_digest))
                    {
                        fail_closed("fixture-effect-witness-promotion-invalid");
                        return false;
                    }
                    m_status.fixture_correction_load_frame =
                        candidate.load_frame;
                    for (size_t type = 0;
                         type < kRollbackSideEffectTypeCount; ++type)
                    {
                        m_status.fixture_discarded_effect_seen[type] =
                            candidate.discarded_count[type] != 0;
                        m_status.fixture_discarded_effect_frame[type] =
                            candidate.discarded_first_frame[type];
                        m_status.fixture_replayed_effect_seen[type] = false;
                        m_status.fixture_replayed_effect_frame[type] = 0;
                    }
                    m_fixture_correction_gate.reset();
                }
                else if (correction_action
                    == RollbackFixtureCorrectionAction::RejectedUnrelated)
                {
                    ++m_status.fixture_load_rejections;
                }
            }
            std::array<uint32_t, 2> previous_input {};
            if (frame != 0)
            {
                const auto& previous = m_input_history[
                    (frame - 1u) & kRollbackProductionFrameHistoryMask];
                if (!previous.valid
                    || previous.epoch != m_manifest.epoch.generation
                    || previous.frame != frame - 1u)
                {
                    fail_closed("rollback-input-history-missing");
                    return false;
                }
                previous_input = previous.input;
            }
            uint64_t native_input[2] {
                PackRollbackNativeEngineInput(
                    compact_input[0], previous_input[0]),
                PackRollbackNativeEngineInput(
                    compact_input[1], previous_input[1]),
            };
            using CameraHistory = RollbackHistoricalCameraArgs<128>;
            CameraHistory::Bytes intercepted_camera {};
            const CameraHistory::Bytes* intercepted = nullptr;
            if (!event.data.adv.rolling_back)
            {
                if (!camera_input
                    || !SafeReadBytes(camera_input,
                        intercepted_camera.data(),
                        intercepted_camera.size()))
                {
                    fail_closed("camera-argument-read-failed");
                    return false;
                }
                intercepted = &intercepted_camera;
            }
            CameraHistory::Bytes historical_camera {};
            RollbackProductionTickArgs temporary {
                &native_input[0], &native_input[1], historical_camera.data(),
            };
            const RollbackHistoricalCameraArgsReport camera =
                m_camera_history.select(
                    m_manifest.epoch.generation,
                    frame,
                    event.data.adv.rolling_back,
                    intercepted,
                    historical_camera);
            if (!camera.ok)
            {
                switch (camera.failure)
                {
                case RollbackHistoricalCameraArgsFailure::MissingRollbackFrame:
                    fail_closed("historical-camera-argument-missing");
                    break;
                case RollbackHistoricalCameraArgsFailure::RetentionCollision:
                    fail_closed("historical-camera-retention-collision");
                    break;
                case RollbackHistoricalCameraArgsFailure::IntegrityMismatch:
                    fail_closed("historical-camera-integrity-mismatch");
                    break;
                default:
                    fail_closed("historical-camera-invalid-argument");
                    break;
                }
                return false;
            }
            m_effect_epoch = m_manifest.epoch.generation;
            m_effect_frame = frame;
            m_effect_ordinals.reset();
            m_audio_create_ordinal = 0;
            m_vfx_create_ordinal = 0;
            m_owned_native_input = {native_input[0], native_input[1]};
            m_owned_consumed_input = {};
            m_owned_consumed_secondary_input = {};
            m_owned_input_call_mask = 0;
            std::array<uintptr_t, 2> fighters {};
            if (!accepted_fighter_pointers(fighters[0], fighters[1]))
            {
                fail_closed("authoritative-input-fighter-identity-mismatch");
                m_effect_frame.clear();
                return false;
            }
            if (frame == 0 && !event.data.adv.rolling_back
                && !commit_frame_zero_pre_advance())
            {
                fail_closed("frame-zero-pre-advance-mismatch");
                m_effect_frame.clear();
                return false;
            }
            RngTraceHook& rng_trace = RngTraceHook::instance();
            const bool trace_frame_rng =
                ShouldTraceRollbackNativeRngCallers(
                    frame, kRollbackReplayRngTracePrefixFrames,
                    event.data.adv.rolling_back,
                    ReplayDebugTrace::instance().enabled(),
                    rng_trace.install());
            uint32_t trace_source_index = UINT32_MAX;
            if (trace_frame_rng)
            {
                if (m_config.replay_input.enabled)
                {
                    (void)m_active_replay_input_config.consumed_index(
                        frame, m_config.input_delay, trace_source_index);
                }
                if (frame == 0 && !event.data.adv.rolling_back
                    && rng_trace.active())
                {
                    rng_trace.end_window(
                        m_config.replay_deep_trace_diagnostics,
                        "rollback-frame-zero",
                        "bootstrap-before-native-advance-0",
                        0, 0, 0, -1, -1,
                        static_cast<int32_t>(
                            m_active_replay_input_config.round_index),
                        0, static_cast<int32_t>(trace_source_index),
                        m_pair_epoch, m_round_generation);
                }
                else if (rng_trace.active())
                {
                    // Diagnostic-only ownership evidence. Capture the
                    // simulation thread's CRT consumers that ran after the
                    // preceding owned frame and before this one. This window
                    // is deliberately bounded to the trace prefix below and
                    // does not change native RNG state or call scheduling.
                    rng_trace.end_window(
                        m_config.replay_deep_trace_diagnostics,
                        "rollback-inter-frame",
                        "post-native-to-next-pre-native",
                        static_cast<int32_t>(trace_source_index),
                        static_cast<int32_t>(frame), -1, -1, -1,
                        static_cast<int32_t>(
                            m_active_replay_input_config.round_index),
                        static_cast<int32_t>(frame),
                        static_cast<int32_t>(trace_source_index),
                        m_pair_epoch, m_round_generation);
                }
                RollbackRngTuple pre_native {};
                if (!capture_live_rng_tuple(pre_native))
                {
                    fail_closed("traced-frame-pre-native-rng-read-failed");
                    m_effect_frame.clear();
                    return false;
                }
                emit_rng_checkpoint(
                    frame == 0
                        ? "pre-native-advance-0"
                        : "pre-native-advance",
                    pre_native, frame, trace_source_index, 0, false);
                rng_trace.begin_window();
            }
            bool native_iteration_ok = false;
            {
                RollbackNanosecondCounterScope native_tick_timing(
                    m_status.native_tick_nanoseconds,
                    m_status.native_tick_calls);
                if (event.data.adv.rolling_back)
                {
                    RollbackResimScope scope(m_effect_epoch, frame);
                    native_iteration_ok =
                        run_owned_native_simulation_iteration(
                            temporary.camera_input, true);
                    if (native_iteration_ok)
                        ++m_status.rollback_advances;
                    if (native_iteration_ok
                        && m_fixture_correction_pending
                        && frame
                            > m_status.fixture_rollback_replay_high_water)
                    {
                        m_status.fixture_rollback_replay_high_water = frame;
                    }
                    if (native_iteration_ok
                        && m_config.deterministic_input.enabled)
                    {
                        m_status.fixture_prediction_diverged = true;
                    }
                }
                else
                {
                    native_iteration_ok =
                        run_owned_native_simulation_iteration(
                            temporary.camera_input, false);
                }
            }
            if (trace_frame_rng)
            {
                rng_trace.end_window(
                    m_config.replay_deep_trace_diagnostics,
                    frame == 0
                        ? "rollback-frame-zero"
                        : "rollback-logical-frame",
                    frame == 0 ? "native-advance-0" : "native-advance",
                    static_cast<int32_t>(trace_source_index),
                    static_cast<int32_t>(frame), -1, -1, -1,
                    static_cast<int32_t>(
                        m_active_replay_input_config.round_index),
                    static_cast<int32_t>(frame),
                    static_cast<int32_t>(trace_source_index),
                    m_pair_epoch, m_round_generation);
                if (frame == 0 && !event.data.adv.rolling_back)
                    rng_trace.begin_window();
                else if (!event.data.adv.rolling_back
                    && frame + 1u
                        < kRollbackReplayRngTracePrefixFrames)
                    rng_trace.begin_window();
            }
            if (!native_iteration_ok)
            {
                m_effect_frame.clear();
                return false;
            }
            if (!event.data.adv.rolling_back
                && (frame == 0 || trace_frame_rng))
            {
                RollbackRngTuple post_native {};
                if (!capture_live_rng_tuple(post_native))
                {
                    ++m_status.frame_zero_checkpoint_failures;
                    fail_closed("frame-zero-post-native-rng-read-failed");
                    m_effect_frame.clear();
                    return false;
                }
                emit_rng_checkpoint(
                    frame == 0
                        ? "post-native-advance-0"
                        : "post-native-advance",
                    post_native, frame,
                    trace_frame_rng
                        ? trace_source_index
                        : m_status.replay_round_frame_zero_source_index,
                    0, false);
            }
            if (m_network == &m_route_network)
            {
                RollbackRouteKind attributed_route =
                    m_route_network.selected_route();
                bool deadline_missed = false;
                if (m_route_deadline_tracker.observe_advance(
                        event.data.adv.rolling_back,
                        m_route_network.selected_route(),
                        attributed_route,
                        deadline_missed))
                {
                    m_route_network.observe_input_deadline(
                        attributed_route, deadline_missed);
                }
            }
            bool consumer_read_ok = true;
            for (size_t slot = 0; slot < 2; ++slot)
            {
                consumer_read_ok = SafeReadUInt32(
                    reinterpret_cast<const void*>(fighters[slot] + 0x2150),
                    &m_owned_consumed_input[slot]) && consumer_read_ok;
                consumer_read_ok = SafeReadUInt32(
                    reinterpret_cast<const void*>(fighters[slot] + 0x2158),
                    &m_owned_consumed_secondary_input[slot])
                    && consumer_read_ok;
            }
            if (!consumer_read_ok)
            {
                fail_closed("authoritative-input-consumer-read-failed");
                m_effect_frame.clear();
                return false;
            }
            m_owned_input_call_mask = 0x3;
            if (m_status.state != RollbackProductionState::Active
                && m_status.state != RollbackProductionState::WaitingForGekko)
            {
                m_effect_frame.clear();
                return false;
            }
            m_current_frame = frame;
            ++m_status.advances;

            if (!observe_fixture_move_state(frame, fighters.data()))
            {
                m_effect_frame.clear();
                fail_closed("fixture-move-state-read-failed");
                return false;
            }

            // Prove ownership from the complete stock input-consumer path, not
            // from the deterministic fixture schedule. Replay-authored input
            // may press a button well before or after the correction window.
            // Direction bits are intentionally excluded because the stock
            // transform list can remap them before publication on the fighter.
            // One known button bit and its rising edge must survive on the
            // same slot, proving the high-word move-start path as well.
            if (!m_status.native_input_ownership_verified)
            {
                uint64_t observed[2] {};
                if (!SafeReadUInt64(reinterpret_cast<const void*>(
                        m_image_base + 0x4855700), &observed[0])
                    || !SafeReadUInt64(reinterpret_cast<const void*>(
                        m_image_base + 0x4855708), &observed[1]))
                {
                    fail_closed("native-input-ownership-source-read-failed");
                    m_effect_frame.clear();
                    return false;
                }
                const bool source_exact = observed[0] == native_input[0]
                    && observed[1] == native_input[1];
                const RollbackNativeInputActionEvidence action =
                    EvaluateRollbackNativeInputActionEvidence(
                        m_owned_native_input,
                        m_owned_consumed_input,
                        m_owned_consumed_secondary_input,
                        kRollbackFixtureBasicActionInput);
                m_status.native_input_ownership_verified =
                    IsRollbackNativeInputOwnershipVerified({
                        m_owned_expected_input_pair_published,
                        m_owned_native_per_frame_completed,
                        source_exact,
                        action.action_edge_submitted,
                        action.action_edge_preserved,
                        m_owned_input_call_mask,
                    });
            }

            if (m_config.deterministic_input.enabled
                && frame >= m_config.deterministic_input.correction_start
                    - kRollbackFixtureApproachUpdates
                && frame < m_config.deterministic_input.correction_start
                    + m_config.deterministic_input.hold_updates)
            {
                uint64_t observed[2] {};
                if (!SafeReadUInt64(reinterpret_cast<const void*>(
                        m_image_base + 0x4855700), &observed[0])
                    || !SafeReadUInt64(reinterpret_cast<const void*>(
                        m_image_base + 0x4855708), &observed[1]))
                {
                    fail_closed("fixture-engine-input-read-failed");
                    m_effect_frame.clear();
                    return false;
                }
                ++m_status.fixture_engine_inputs_observed;
                m_status.fixture_last_engine_input[0] = observed[0];
                m_status.fixture_last_engine_input[1] = observed[1];
                if (((native_input[0] | native_input[1])
                        & kRollbackFixtureBasicActionInput) != 0
                    && m_status.fixture_action_engine_input[0] == 0
                    && m_status.fixture_action_engine_input[1] == 0)
                {
                    // Preserve the first action sample, which contains the
                    // rising-edge word. Later held samples intentionally have
                    // a zero secondary word and used to overwrite the useful
                    // ownership evidence in the one-second status record.
                    m_status.fixture_action_engine_input[0] = observed[0];
                    m_status.fixture_action_engine_input[1] = observed[1];
                    m_status.fixture_action_chara_input[0] =
                        m_owned_consumed_input[0];
                    m_status.fixture_action_chara_input[1] =
                        m_owned_consumed_input[1];
                    m_status.fixture_action_chara_secondary_input[0] =
                        m_owned_consumed_secondary_input[0];
                    m_status.fixture_action_chara_secondary_input[1] =
                        m_owned_consumed_secondary_input[1];
                }
                const bool source_exact = observed[0] == native_input[0]
                    && observed[1] == native_input[1];
                if (!source_exact)
                {
                    ++m_status.fixture_engine_input_mismatches;
                }
                if (m_owned_input_call_mask != 0x3)
                {
                    fail_closed("fixture-chara-input-consumer-missing");
                    m_effect_frame.clear();
                    return false;
                }
                ++m_status.fixture_chara_inputs_observed;
                m_status.fixture_last_chara_input[0] =
                    m_owned_consumed_input[0];
                m_status.fixture_last_chara_input[1] =
                    m_owned_consumed_input[1];
                m_status.fixture_last_chara_secondary_input[0] =
                    m_owned_consumed_secondary_input[0];
                m_status.fixture_last_chara_secondary_input[1] =
                    m_owned_consumed_secondary_input[1];
                bool action_bits_preserved = true;
                for (size_t slot = 0; slot < 2; ++slot)
                {
                    const uint32_t source_action =
                        static_cast<uint32_t>(native_input[slot])
                            & kRollbackFixtureBasicActionInput;
                    if (source_action != 0
                        && (m_owned_consumed_input[slot]
                            & source_action) != source_action)
                    {
                        action_bits_preserved = false;
                    }
                    const uint32_t source_edge = static_cast<uint32_t>(
                        native_input[slot] >> 32)
                        & kRollbackFixtureBasicActionInput;
                    if (source_edge != 0)
                    {
                        if ((m_owned_consumed_secondary_input[slot]
                                & source_edge) == source_edge)
                        {
                            ++m_status.fixture_basic_action_edges_observed;
                        }
                        else
                        {
                            ++m_status
                                .fixture_chara_secondary_input_mismatches;
                        }
                    }
                }
                if (!action_bits_preserved)
                {
                    ++m_status.fixture_chara_input_mismatches;
                }
                // The engine globals and exact input-pair publication prove
                // the source. The stock consumer may remap directions and
                // route native slots, so full +0x2150/+0x2158 equality remains
                // diagnostic; only the submitted action bits are invariant.
            }

            {
                RollbackNanosecondCounterScope transition_timing(
                    m_status.transition_capture_nanoseconds,
                    m_status.transition_capture_calls);
                m_last_advance_round_transition_observed = false;
                if (!capture_and_queue_transitions(
                        frame, event.data.adv.rolling_back))
                {
                    m_effect_frame.clear();
                    if (m_status.state != RollbackProductionState::Fatal)
                        fail_closed("transition-state-capture-failed");
                    return false;
                }
            }
            if (m_post_advance_frame.valid)
            {
                m_effect_frame.clear();
                fail_closed("gekko-advance-before-prior-save");
                return false;
            }
            RollbackStepStateReport captured {};
            {
                RollbackNanosecondCounterScope capture_timing(
                    m_status.state_capture_nanoseconds,
                    m_status.state_capture_calls);
                captured = CaptureRollbackStepState(
                    m_image_base,
                    m_manifest,
                    m_post_advance_state,
                    m_config.lifecycle_mode,
                    false,
                    &m_stage_identity,
                    &m_capture_scratch.hgcpu,
                    &m_snapshot_capacity_limits,
                    m_native_callback_coverage.input_state_object,
                    &m_stage_wind_pool,
                    &m_palette_variant_writer_registry,
                    &m_presentation_semantic_identity);
                if (captured.native_input_callback_ok)
                    ++m_status.native_input_callback_snapshot_captures;
            }
            m_status.explicit_capture_nanoseconds +=
                captured.explicit_capture_nanoseconds;
            m_status.hgcpu_capture_nanoseconds +=
                captured.hgcpu_capture_nanoseconds;
            m_status.palette_variant_capture_nanoseconds +=
                captured.palette_variant_capture_nanoseconds;
            m_status.explicit_cleanup_nanoseconds +=
                captured.explicit_cleanup_nanoseconds;
            m_status.stage_capture_nanoseconds +=
                captured.stage_capture_nanoseconds;
            m_status.wind_capture_nanoseconds +=
                captured.wind_capture_nanoseconds;
            m_status.capture_finalize_nanoseconds +=
                captured.capture_finalize_nanoseconds;
            m_status.hgcpu_emergency_capture_nanoseconds +=
                captured.hgcpu_report.emergency_capture_nanoseconds;
            m_status.hgcpu_native_capture_nanoseconds +=
                captured.hgcpu_report.native_capture_nanoseconds;
            m_status.hgcpu_emergency_restore_nanoseconds +=
                captured.hgcpu_report.emergency_restore_nanoseconds;
            m_status.hgcpu_khit_capture_nanoseconds +=
                captured.hgcpu_report.khit_capture_nanoseconds;
            m_status.hgcpu_timer_capture_nanoseconds +=
                captured.hgcpu_report.timer_capture_nanoseconds;
            m_status.hgcpu_hash_finalize_nanoseconds +=
                captured.hgcpu_report.hash_finalize_nanoseconds;
            if (!captured.ok)
            {
                m_effect_frame.clear();
                fail_closed(captured.failure);
                return false;
            }
            mark_snapshot_capture_coverage();
            if (!event.data.adv.rolling_back
                && (frame == 0 || trace_frame_rng))
            {
                RollbackRngTuple post_capture {};
                RollbackRngTuple live_post_capture {};
                if (!capture_snapshot_rng_tuple(
                        m_post_advance_state, post_capture)
                    || !capture_live_rng_tuple(live_post_capture)
                    || live_post_capture != post_capture)
                {
                    if (frame == 0)
                        ++m_status.frame_zero_checkpoint_failures;
                    m_effect_frame.clear();
                    fail_closed(
                        frame == 0
                            ? "frame-zero-post-advance-rng-cleanup-mismatch"
                            : "traced-frame-post-advance-rng-cleanup-mismatch");
                    return false;
                }
                emit_rng_checkpoint(
                    frame == 0
                        ? "post-advance-snapshot-cleanup"
                        : "post-advance-snapshot-cleanup-traced-frame",
                    live_post_capture, frame,
                    trace_frame_rng
                        ? trace_source_index
                        : m_status.replay_round_frame_zero_source_index,
                    m_post_advance_state.canonical_hash, false);
            }
            if (!m_stage_presentation_history.record(
                    m_manifest.epoch.generation,
                    frame,
                    m_post_advance_state.breakable_stage))
            {
                m_effect_frame.clear();
                fail_closed("breakable-presentation-history-record-failed");
                return false;
            }
            m_effect_frame.clear();
            RollbackProductionFrameSummary summary {};
            summary.epoch = m_pair_epoch;
            summary.frame = frame;
            summary.canonical_hash = m_post_advance_state.canonical_hash;
            summary.component_hash[0] =
                m_post_advance_state.hgcpu.canonical_hash;
            summary.component_hash[1] =
                m_post_advance_state.explicit_snapshot.canonical_hash;
            summary.component_hash[2] =
                m_post_advance_state.breakable_stage.canonical_hash;
            summary.component_hash[3] =
                m_post_advance_state.stage_wind.canonical_hash;
            summary.hgcpu_peer = RollbackBuildHgCpuPeerBreakdown(
                m_post_advance_state.hgcpu);
            summary.hgcpu_peer.motion_decode_scratch_hash =
                HashRollbackMotionDecodeScratchSnapshot(
                    m_post_advance_state.motion_decode_scratch);
            summary.hgcpu_peer.motion_pose_residue_hash =
                HashRollbackMotionPoseResidueRollbackState(
                    m_post_advance_state.motion_pose_residue);
            summary.native_round_state_hash =
                m_post_advance_state.native_round_state.hash;
            summary.native_simulation_state_hash =
                m_post_advance_state.native_simulation_state.hash;
            summary.palette_variant_canonical_hash =
                m_post_advance_state.palette_variants.canonical_hash;
            summary.palette_variant_active_mask =
                m_post_advance_state.palette_variants.active_mask;
            m_status.palette_variant_canonical_hash =
                summary.palette_variant_canonical_hash;
            m_status.palette_variant_local_integrity_hash =
                m_post_advance_state.palette_variants.integrity_hash;
            m_status.palette_variant_active_mask =
                summary.palette_variant_active_mask;
            uint8_t post_battle_status = 0xFF;
            uint16_t committed_round_result_type = 0;
            if (!SafeReadUInt8(
                    reinterpret_cast<const void*>(
                        m_manifest.epoch.battle_manager + 0x1480),
                    &post_battle_status)
                || !SafeReadBytes(
                    reinterpret_cast<const void*>(m_image_base
                        + kRollbackProductionRvaLastRoundResultType),
                    &committed_round_result_type,
                    sizeof(committed_round_result_type)))
            {
                fail_closed("post-advance-round-result-unreadable");
                return false;
            }
            if (IsRollbackCommittedRoundResultBoundary(
                    m_manifest.epoch.battle_status,
                    post_battle_status,
                    committed_round_result_type))
            {
                m_status.stock_round_transition_last_state =
                    post_battle_status;
                m_status.lifecycle_live_battle_status =
                    post_battle_status;
                if (ShouldCaptureRollbackTerminalCheckpoint(
                        true, m_last_advance_round_transition_observed)
                    && !m_round_terminal_local_edge_seen)
                {
                    m_round_terminal_local_edge_seen = true;
                    m_round_terminal_local_result_type =
                        committed_round_result_type;
                    m_round_terminal_local_edge_frame =
                        RollbackFrameStamp::From(frame);
                    m_round_terminal_capture_end = RollbackFrameStamp::From(
                        frame + m_config.rollback_window);
                }
            }
            // Publish a terminal control summary only after this peer has
            // observed its journaled native transition edge. The broader
            // committed-result predicate can become true a frame earlier on
            // the non-authoritative peer and is not sufficient for handoff.
            if (m_round_terminal_local_edge_seen)
            {
                summary.terminal_round_result = 1;
                summary.round_result_type =
                    m_round_terminal_local_result_type;
            }
            if (m_round_terminal_capture_end.valid
                && !RollbackFrameIsAfter(
                    frame, m_round_terminal_capture_end.value)
                && !capture_round_terminal_candidate(frame))
            {
                return false;
            }
            const RollbackProductionSummaryDetailReport detail =
                BuildRollbackProductionSummaryDetails(
                    m_post_advance_state.explicit_snapshot, summary);
            if (!detail.ok)
            {
                fail_closed(detail.failure);
                return false;
            }
            summary.input[0] = p0.input_value;
            summary.input[1] = p1.input_value;
            if (m_config.replay_trace_compare)
            {
                trace_replay_comparison_frame(
                    frame,
                    event.data.adv.rolling_back,
                    event.data.adv.running_ahead,
                    summary,
                    previous_input);
            }
            if (m_config.deterministic_input.enabled
                && frame >= m_config.deterministic_input.correction_start
                    - kRollbackFixtureApproachUpdates
                && frame < m_config.deterministic_input.correction_start
                    + m_config.deterministic_input.hold_updates
                    + m_config.rollback_window
                && (p0.input_value != 0 || p1.input_value != 0))
            {
                ++m_status.fixture_inputs_observed;
            }
            if (m_config.deterministic_input.enabled
                && ((p0.input_value | p1.input_value)
                    & kRollbackFixtureBasicActionInput) != 0)
            {
                ++m_status.fixture_basic_actions_observed;
            }
            const size_t summary_slot =
                frame & kRollbackProductionFrameHistoryMask;
            const bool local_summary_collision =
                m_local_summary_valid[summary_slot]
                && m_local_summaries[summary_slot].frame != frame;
            const bool remote_summary_collision =
                m_remote_summary_valid[summary_slot]
                && m_remote_summaries[summary_slot].frame != frame;
            if (local_summary_collision || remote_summary_collision)
            {
                const RollbackFrameStamp& expected =
                    m_summary_consensus.expected();
                m_status.summary_consensus_expected_valid = expected.valid;
                m_status.summary_consensus_expected =
                    expected.valid ? expected.value : 0;
                m_status.summary_collision_incoming_frame = frame;
                m_status.summary_collision_slot =
                    static_cast<uint32_t>(summary_slot);
                m_status.summary_collision_local_valid =
                    m_local_summary_valid[summary_slot];
                m_status.summary_collision_local_frame =
                    m_local_summaries[summary_slot].frame;
                m_status.summary_collision_local_flags =
                    m_local_summaries[summary_slot].flags;
                m_status.summary_collision_remote_valid =
                    m_remote_summary_valid[summary_slot];
                m_status.summary_collision_remote_frame =
                    m_remote_summaries[summary_slot].frame;
                m_status.summary_collision_remote_flags =
                    m_remote_summaries[summary_slot].flags;
                fail_closed("unacknowledged-summary-ring-overwrite");
                return false;
            }
            if (m_local_summary_valid[summary_slot]
                && m_local_summaries[summary_slot].frame == frame
                && m_local_summaries[summary_slot].flags
                    == kRollbackProductionSummaryConfirmed)
            {
                fail_closed("gekko-rewound-confirmed-summary");
                return false;
            }
            m_local_summaries[summary_slot] = summary;
            m_local_summary_valid[summary_slot] = true;
            m_input_history[summary_slot] = {
                m_manifest.epoch.generation,
                frame,
                compact_input,
                true,
            };
            m_post_advance_frame = frame;
            m_post_advance_epoch = m_manifest.epoch.generation;
            m_status.corrected_frame = frame;
            if (m_round_terminal_local_edge_seen
                && !send_terminal_candidate(frame))
            {
                return false;
            }
            if (!event.data.adv.rolling_back
                && !event.data.adv.running_ahead)
            {
                if (!m_first_advance_frame.valid)
                    m_first_advance_frame = frame;
                if (!publish_confirmed_summary(frame)) return false;
            }
            if (!m_ledger.report().ok)
            {
                fail_closed(m_ledger.report().failure);
                return false;
            }
            return true;
        }

        static void add_replay_trace_fighter_fields(
            ReplayTraceFields& fields,
            const char* prefix,
            const ReplayScrubDiag::CharaMoveVmSnap& fighter) noexcept
        {
            const std::string p(prefix ? prefix : "p");
            auto key = [&p](const char* suffix) { return p + suffix; };
            fields.boolean(key("_readable").c_str(), fighter.readable)
                .uinteger(key("_move_id").c_str(), fighter.current_move_id)
                .uinteger(key("_move_frame").c_str(), fighter.current_move_frame)
                .real(key("_pos_x").c_str(), fighter.pos_x)
                .real(key("_pos_y").c_str(), fighter.pos_y)
                .real(key("_pos_z").c_str(), fighter.pos_z)
                .real(key("_position_target_x").c_str(),
                    fighter.position_target_x)
                .real(key("_position_target_y").c_str(),
                    fighter.position_target_y)
                .real(key("_position_target_z").c_str(),
                    fighter.position_target_z)
                .real(key("_position_target_lerp_weight").c_str(),
                    fighter.position_target_lerp_weight)
                .real(key("_vel_x").c_str(), fighter.vel_x)
                .real(key("_vel_y").c_str(), fighter.vel_y)
                .real(key("_vel_z").c_str(), fighter.vel_z)
                .real(key("_ground_vel_x").c_str(), fighter.ground_vel_x)
                .real(key("_ground_vel_y").c_str(), fighter.ground_vel_y)
                .real(key("_ground_vel_z").c_str(), fighter.ground_vel_z)
                .real(key("_one_shot_x").c_str(), fighter.one_shot_x)
                .real(key("_one_shot_z").c_str(), fighter.one_shot_z)
                .uinteger(key("_root_motion_carry_mode").c_str(),
                    fighter.root_motion_carry_mode)
                .real(key("_root_motion_carry_x").c_str(),
                    fighter.root_motion_carry_x)
                .real(key("_root_motion_carry_z").c_str(),
                    fighter.root_motion_carry_z)
                // Preserve the old diagnostic names for trace-reader
                // compatibility. They are aliases, not separate state.
                .real(key("_expected_motion_x").c_str(),
                    fighter.root_motion_carry_x)
                .real(key("_expected_motion_z").c_str(),
                    fighter.root_motion_carry_z)
                .real(key("_smoothed_root_motion_x").c_str(),
                    fighter.smoothed_root_motion_x)
                .real(key("_smoothed_root_motion_z").c_str(),
                    fighter.smoothed_root_motion_z)
                .real(key("_raw_root_motion_x").c_str(),
                    fighter.raw_root_motion_x)
                .real(key("_raw_root_motion_z").c_str(),
                    fighter.raw_root_motion_z)
                .real(key("_frame_delta_x").c_str(), fighter.frame_delta_x)
                .real(key("_frame_delta_z").c_str(), fighter.frame_delta_z)
                .uinteger(key("_pose_finalize_tick_counter").c_str(),
                    fighter.pose_finalize_tick_counter)
                .uinteger(key("_look_at_blend_frame_counter").c_str(),
                    fighter.pose_finalize_tick_counter)
                .uinteger(key("_hit_slide_slot").c_str(),
                    fighter.hit_slide_slot)
                .hex(key("_latched_hit_slide_input_dir").c_str(),
                    fighter.latched_hit_slide_input_dir)
                .real(key("_hit_pushback_x").c_str(),
                    fighter.hit_pushback_x)
                .real(key("_hit_pushback_z").c_str(),
                    fighter.hit_pushback_z)
                .real(key("_hit_pushback_decay_scale").c_str(),
                    fighter.hit_pushback_decay_scale)
                .real(key("_root_motion_blend_weight").c_str(),
                    fighter.root_motion_blend_weight)
                .real(key("_move_time_scale_a").c_str(),
                    fighter.move_time_scale_a)
                .real(key("_move_time_scale_b").c_str(),
                    fighter.move_time_scale_b)
                .real(key("_movevm_time_dilation_scalar").c_str(),
                    fighter.movevm_time_dilation_scalar)
                .real(key("_hit_cue_root_weight").c_str(),
                    fighter.hit_cue_root_weight)
                .real(key("_facing").c_str(), fighter.facing)
                .real(key("_pose_pos_x").c_str(), fighter.pose_pos_x)
                .real(key("_pose_pos_y").c_str(), fighter.pose_pos_y)
                .real(key("_pose_pos_z").c_str(), fighter.pose_pos_z)
                .real(key("_render_pos_x").c_str(), fighter.render_pos_x)
                .real(key("_render_pos_y").c_str(), fighter.render_pos_y)
                .real(key("_render_pos_z").c_str(), fighter.render_pos_z)
                .real(key("_vital_scale").c_str(), fighter.vital_scale)
                .real(key("_vital_candidate").c_str(), fighter.vital_candidate)
                .real(key("_vital_ko_gate").c_str(), fighter.vital_ko_gate)
                .real(key("_vital_displayed").c_str(), fighter.vital_displayed)
                .hex(key("_vital_category_bits").c_str(),
                    fighter.vital_category_bits)
                .integer(key("_vital_state").c_str(), fighter.vital_state)
                .uinteger(key("_hitstun").c_str(), fighter.in_hitstun)
                .uinteger(key("_blockstun").c_str(), fighter.in_blockstun)
                .hex(key("_hit_reaction_result").c_str(),
                    fighter.hit_reaction_result)
                .uinteger(key("_hit_state").c_str(),
                    fighter.in_hitstun ? 1u
                    : (fighter.in_blockstun ? 2u : 0u))
                .uinteger(key("_sc_mode").c_str(), fighter.soul_charge_mode)
                .uinteger(key("_sc_state").c_str(), fighter.soul_charge_state)
                .hex(key("_sc_trigger_bits").c_str(),
                    fighter.soul_charge_trigger_bits)
                .uinteger(key("_sc_kind_group").c_str(),
                    fighter.soul_charge_kind_group)
                .uinteger(key("_sc_match_counter").c_str(),
                    fighter.soul_charge_match_counter);
            AddRollbackHitCueRootMotionTraceFields(
                fields, prefix, fighter);
        }

        static void add_replay_trace_fighter_witness_fields(
            ReplayTraceFields& fields,
            const char* prefix,
            const ReplayScrubDiag::CharaMoveVmSnap& fighter) noexcept
        {
            const std::string p(prefix ? prefix : "p");
            const auto key = [&p](const char* suffix) {
                return p + suffix;
            };
            fields.uinteger(key("_move_id").c_str(),
                    fighter.current_move_id)
                .uinteger(key("_move_frame").c_str(),
                    fighter.current_move_frame)
                .real(key("_pos_x").c_str(), fighter.pos_x)
                .real(key("_pos_y").c_str(), fighter.pos_y)
                .real(key("_pos_z").c_str(), fighter.pos_z)
                .real(key("_vel_x").c_str(), fighter.vel_x)
                .real(key("_vel_y").c_str(), fighter.vel_y)
                .real(key("_vel_z").c_str(), fighter.vel_z)
                .real(key("_facing").c_str(), fighter.facing)
                .real(key("_pose_pos_x").c_str(), fighter.pose_pos_x)
                .real(key("_pose_pos_y").c_str(), fighter.pose_pos_y)
                .real(key("_pose_pos_z").c_str(), fighter.pose_pos_z)
                .real(key("_render_pos_x").c_str(), fighter.render_pos_x)
                .real(key("_render_pos_y").c_str(), fighter.render_pos_y)
                .real(key("_render_pos_z").c_str(), fighter.render_pos_z)
                .real(key("_vital_scale").c_str(), fighter.vital_scale)
                .real(key("_vital_candidate").c_str(),
                    fighter.vital_candidate)
                .real(key("_vital_ko_gate").c_str(), fighter.vital_ko_gate)
                .real(key("_vital_displayed").c_str(),
                    fighter.vital_displayed)
                .hex(key("_vital_category_bits").c_str(),
                    fighter.vital_category_bits)
                .integer(key("_vital_state").c_str(), fighter.vital_state)
                .uinteger(key("_hitstun").c_str(), fighter.in_hitstun)
                .uinteger(key("_blockstun").c_str(), fighter.in_blockstun)
                .hex(key("_hit_reaction_result").c_str(),
                    fighter.hit_reaction_result)
                .uinteger(key("_hit_state").c_str(),
                    fighter.in_hitstun ? 1u
                    : (fighter.in_blockstun ? 2u : 0u))
                .uinteger(key("_sc_mode").c_str(),
                    fighter.soul_charge_mode)
                .uinteger(key("_sc_state").c_str(),
                    fighter.soul_charge_state)
                .hex(key("_sc_trigger_bits").c_str(),
                    fighter.soul_charge_trigger_bits)
                .uinteger(key("_sc_kind_group").c_str(),
                    fighter.soul_charge_kind_group)
                .uinteger(key("_sc_match_counter").c_str(),
                    fighter.soul_charge_match_counter);
        }

        void emit_replay_trace_frame(
            const RollbackReplayTraceFrame& frame,
            bool pair_confirmed,
            bool speculative,
            bool rolling_back,
            bool running_ahead,
            bool terminal_pair_proof = false) noexcept
        {
            if (!frame.valid || !ReplayDebugTrace::instance().enabled())
                return;
            ReplayTraceFields fields;
            fields.uinteger("replay_round", frame.replay_round)
                .hex("round_epoch", frame.round_epoch)
                .uinteger("round_generation", frame.round_generation)
                .uinteger("logical_frame", frame.logical_frame)
                .uinteger("source_index", frame.source_index)
                .boolean("pair_confirmed", pair_confirmed)
                .boolean("terminal_pair_proof", terminal_pair_proof)
                .boolean("speculative", speculative)
                .boolean("rolling_back", rolling_back)
                .boolean("running_ahead", running_ahead)
                .hex("canonical_hash", frame.canonical_hash)
                .uinteger("oracle_schema_version",
                    kRollbackReplayOracleSchemaVersion)
                .hex("oracle_gameplay_hash_v1",
                    frame.oracle_gameplay_hash_v1)
                .hex("oracle_gameplay_hash_v9",
                    frame.oracle_gameplay_hash_v9)
                .hex("oracle_gameplay_hash_v10",
                    frame.oracle_gameplay_hash_v10)
                .hex("oracle_gameplay_hash_v11",
                    frame.oracle_gameplay_hash_v11)
                .hex("oracle_gameplay_hash_v12",
                    frame.oracle_gameplay_hash_v12)
                .hex("oracle_presentation_hash",
                    frame.oracle_presentation_hash)
                .hex("hgcpu_hash", frame.component_hash[0])
                .hex("explicit_hash", frame.component_hash[1])
                .hex("breakable_hash", frame.component_hash[2])
                .hex("wind_hash", frame.component_hash[3])
                .hex("stage_wind_gameplay_hash",
                    frame.stage_wind_gameplay_hash)
                .hex("hgcpu_peer_hash", frame.hgcpu_peer_hash)
                .hex("explicit_range_digest", frame.explicit_range_digest)
                .hex("ccpu_canonical_hash", frame.ccpu_canonical_hash)
                .hex("native_round_state_hash",
                    frame.native_round_state_hash)
                .hex("native_simulation_state_hash",
                    frame.native_simulation_state_hash)
                .hex("palette_variant_canonical_hash",
                    frame.palette_variant_canonical_hash)
                .hex("palette_variant_local_integrity_hash",
                    frame.palette_variant_local_integrity_hash)
                .uinteger("palette_variant_active_mask",
                    frame.palette_variant_active_mask)
                .hex("input_history_hash", frame.input_history_hash)
                .hex("rng_lcg_state", frame.rng_lcg_state)
                .hex("rng_lfsr_hash", frame.rng_lfsr_hash)
                .uinteger("rng_lfsr_index", frame.rng_lfsr_index)
                .boolean("rng_gameplay_crt_present",
                    frame.rng_gameplay_crt_present)
                .hex("rng_gameplay_crt_state",
                    frame.rng_gameplay_crt_state)
                .hex("rng_gameplay_crt_seed",
                    frame.rng_gameplay_crt_seed)
                .uinteger("rng_gameplay_crt_draw_ordinal",
                    frame.rng_gameplay_crt_draw_ordinal)
                .boolean("secondary_event_previous_variant_readable",
                    frame.secondary_event_previous_variant_readable)
                .hex("p1_secondary_event_previous_variant",
                    frame.secondary_event_previous_variant[0])
                .hex("p2_secondary_event_previous_variant",
                    frame.secondary_event_previous_variant[1])
                .hex("breakable_gameplay_digest",
                    frame.breakable_gameplay_digest)
                .hex("breakable_presentation_digest",
                    frame.breakable_presentation_digest)
                .hex("chara_animation_gameplay_digest",
                    frame.chara_animation_gameplay_digest)
                .boolean("stage_wind_readable", true)
                .hex("stage_wind_canonical_hash",
                    frame.component_hash[3])
                .hex("stage_wind_combined_rng_hash",
                    frame.stage_wind_combined_rng_hash)
                .hex("stage_wind_emitter_hash",
                    frame.stage_wind_emitter_hash)
                .hex("stage_wind_root_scheduler_hash",
                    frame.stage_wind_root_scheduler_hash)
                .hex("stage_wind_root_outputs_hash",
                    frame.stage_wind_root_outputs_hash)
                .hex("stage_wind_presentation_hash",
                    frame.stage_wind_presentation_hash)
                .hex("stage_wind_graph_nodes_hash",
                    frame.stage_wind_graph_nodes_hash)
                .hex("stage_wind_graph_hash",
                    frame.stage_wind_graph_hash)
                .uinteger("stage_wind_emitter_count",
                    frame.stage_wind_emitter_count)
                .uinteger("stage_wind_graph_count",
                    frame.stage_wind_graph_count)
                .uinteger("stage_wind_output_active",
                    frame.stage_wind_output_active)
                .uinteger("stage_wind_active_bank",
                    frame.stage_wind_active_bank)
                .integer("stage_wind_pending_count",
                    frame.stage_wind_pending_count)
                .integer("stage_wind_schedule_state",
                    frame.stage_wind_schedule_state)
                .integer("stage_wind_effect_pair_scheduled",
                    frame.stage_wind_effect_pair_scheduled)
                .uinteger("round_result_count", frame.round_control[0])
                .uinteger("round_result_limit", frame.round_control[1])
                .uinteger("round_current_index", frame.round_control[2])
                .uinteger("round_applied_index", frame.round_control[3])
                .uinteger("round_result_flow", frame.round_control[4])
                .hex("p1_gekko_input", frame.input[0])
                .hex("p2_gekko_input", frame.input[1])
                .hex("p1_native_input", frame.native_input[0])
                .hex("p2_native_input", frame.native_input[1])
                .hex("p1_consumed_input", frame.consumed_input[0])
                .hex("p2_consumed_input", frame.consumed_input[1])
                .hex("p1_consumed_secondary_input",
                    frame.consumed_secondary_input[0])
                .hex("p2_consumed_secondary_input",
                    frame.consumed_secondary_input[1]);
            const bool compact_trace = speculative
                || m_config.replay_trace_input_only;
            if (compact_trace)
            {
                fields.string("trace_detail",
                    m_config.replay_trace_input_only
                        ? "input-correction-witness"
                        : "speculative-correction-witness");
                add_replay_trace_fighter_witness_fields(
                    fields, "p1", frame.fighter[0]);
                add_replay_trace_fighter_witness_fields(
                    fields, "p2", frame.fighter[1]);
                ReplayDebugTrace::instance().event(
                    "rollback_replay_trace_frame", fields);
                return;
            }
            RollbackRoundResultCinematicEvidence cinematic {};
            (void)CaptureRollbackRoundResultCinematicEvidence(
                m_image_base, cinematic);
            AddRollbackRoundResultCinematicTraceFields(
                fields, cinematic);
            AddRollbackFloatingPointEnvironmentTraceFields(fields);
            for (size_t player = 0; player < 2; ++player)
            {
                const char* prefix = player == 0 ? "p1" : "p2";
                const auto& palette = frame.ai_palette[player];
                const auto key = [&](const char* suffix) {
                    return std::string(prefix) + "_ai_palette_" + suffix;
                };
                fields.boolean(key("readable").c_str(), palette.readable)
                    .hex(key("scalar_hash").c_str(), palette.scalar_hash)
                    .hex(key("active_motion_bank_rva").c_str(),
                        palette.active_motion_bank_rva)
                    .hex(key("key_buffer_rva").c_str(),
                        palette.key_buffer_rva)
                    .hex(key("bone_data_bank_rva").c_str(),
                        palette.bone_data_bank_rva)
                    .integer(key("current_mode").c_str(),
                        palette.scalars.current_mode)
                    .integer(key("mode").c_str(),
                        palette.scalars.ai_mode)
                    .real(key("phase").c_str(),
                        palette.scalars.phase)
                    .real(key("phase_velocity").c_str(),
                        palette.scalars.phase_velocity)
                    .real(key("phase_scale").c_str(),
                        palette.scalars.phase_scale)
                    .integer(key("repeat_count").c_str(),
                        palette.scalars.repeat_count)
                    .real(key("random_threshold").c_str(),
                        palette.scalars.random_threshold)
                    .integer(key("disabled").c_str(),
                        palette.scalars.disabled)
                    .integer(key("publish_disabled").c_str(),
                        palette.scalars.publish_disabled)
                    .integer(key("lookup_index").c_str(),
                        palette.scalars.lookup_index)
                    .uinteger(key("publish_tick_count").c_str(),
                        palette.scalars.publish_tick_count);
            }
            for (size_t index = 0;
                 index < frame.stage_wind_output_forces.size(); ++index)
            {
                const std::string key =
                    "stage_wind_output_force_" + std::to_string(index);
                fields.real(
                    key.c_str(), frame.stage_wind_output_forces[index]);
            }
            const RollbackReplayStageWindTraceDetail* wind_detail = nullptr;
            if (pair_confirmed && m_config.replay_trace_compare
                && m_replay_stage_wind_trace_details)
            {
                const RollbackReplayStageWindTraceDetail& candidate =
                    m_replay_stage_wind_trace_details[
                        frame.logical_frame
                        & kRollbackProductionFrameHistoryMask];
                if (candidate.valid
                    && candidate.round_epoch == frame.round_epoch
                    && candidate.logical_frame == frame.logical_frame)
                    wind_detail = &candidate;
            }
            if (m_config.replay_trace_compare)
            {
                fields.boolean(
                    "stage_wind_semantic_detail_valid",
                    wind_detail != nullptr);
            }
            for (uint32_t index = 0;
                 index < frame.stage_wind_graph_count
                    && index < frame.stage_wind_node_vtable_rva.size();
                 ++index)
            {
                const std::string prefix =
                    "stage_wind_node_" + std::to_string(index);
                fields.hex((prefix + "_vtable_rva").c_str(),
                        frame.stage_wind_node_vtable_rva[index])
                    .hex((prefix + "_hash").c_str(),
                        frame.stage_wind_node_hash[index])
                    .hex((prefix + "_common_hash").c_str(),
                        frame.stage_wind_node_common_hash[index])
                    .hex((prefix + "_body_hash").c_str(),
                        frame.stage_wind_node_body_hash[index])
                    .hex((prefix + "_tail_hash").c_str(),
                        frame.stage_wind_node_tail_hash[index]);
                if (frame.logical_frame <= 3)
                {
                    for (uint32_t word = 0; word < 16; ++word)
                    {
                        const std::string key =
                            prefix + "_word_"
                            + std::to_string(
                                0x30 + word * sizeof(uint32_t));
                        fields.hex(key.c_str(),
                            frame.stage_wind_node_common_words[index][word]);
                    }
                }
                if (wind_detail)
                {
                    const RollbackStageWindSemanticRanges ranges =
                        RollbackStageWindNodeSemanticRanges(
                            frame.stage_wind_node_vtable_rva[index],
                            frame.stage_wind_node_bytes[index]);
                    for (uint32_t range_index = 0;
                         range_index < ranges.count; ++range_index)
                    {
                        const RollbackStageWindSemanticRange range =
                            ranges.values[range_index];
                        const uint32_t begin = (std::max)(
                            0x70u, static_cast<uint32_t>(range.offset));
                        const uint32_t end =
                            static_cast<uint32_t>(range.offset)
                            + static_cast<uint32_t>(range.bytes);
                        for (uint32_t offset = begin;
                             offset + sizeof(uint32_t) <= end;
                             offset += sizeof(uint32_t))
                        {
                            const std::string key =
                                prefix + "_semantic_word_"
                                + std::to_string(offset);
                            fields.hex(key.c_str(),
                                wind_detail->node_words[index][
                                    offset / sizeof(uint32_t)]);
                        }
                    }
                }
            }
            add_replay_trace_fighter_fields(fields, "p1", frame.fighter[0]);
            add_replay_trace_fighter_fields(fields, "p2", frame.fighter[1]);
            ReplayDebugTrace::instance().event(
                "rollback_replay_trace_frame", fields);
        }

        void trace_replay_comparison_frame(
            uint32_t logical_frame,
            bool rolling_back,
            bool running_ahead,
            const RollbackProductionFrameSummary& summary,
            const std::array<uint32_t, 2>& previous_input) noexcept
        {
            if (!m_config.replay_input.enabled
                || !ReplayDebugTrace::instance().enabled())
                return;
            uint32_t source_index = 0;
            if (!m_active_replay_input_config.consumed_index(
                    logical_frame, m_config.input_delay, source_index))
                return;
            const size_t trace_slot =
                logical_frame & kRollbackProductionFrameHistoryMask;
            RollbackReplayTraceFrame& frame =
                m_replay_trace_frames[trace_slot];
            frame = {};
            frame.valid = true;
            RollbackReplayStageWindTraceDetail* wind_detail = nullptr;
            if (m_config.replay_trace_compare)
            {
                if (!m_replay_stage_wind_trace_details)
                {
                    frame.valid = false;
                    return;
                }
                wind_detail =
                    &m_replay_stage_wind_trace_details[trace_slot];
                std::memset(
                    wind_detail, 0,
                    sizeof(RollbackReplayStageWindTraceDetail));
                wind_detail->valid = true;
                wind_detail->round_epoch = m_pair_epoch;
                wind_detail->logical_frame = logical_frame;
            }
            frame.lifecycle_epoch = m_manifest.epoch.generation;
            frame.round_epoch = m_pair_epoch;
            frame.round_generation = m_round_generation;
            frame.replay_round =
                m_active_replay_input_config.round_index;
            frame.logical_frame = logical_frame;
            frame.source_index = source_index;
            frame.input[0] = summary.input[0];
            frame.input[1] = summary.input[1];
            frame.native_input[0] = m_owned_native_input[0];
            frame.native_input[1] = m_owned_native_input[1];
            frame.consumed_input[0] = m_owned_consumed_input[0];
            frame.consumed_input[1] = m_owned_consumed_input[1];
            frame.consumed_secondary_input[0] =
                m_owned_consumed_secondary_input[0];
            frame.consumed_secondary_input[1] =
                m_owned_consumed_secondary_input[1];
            if (!CaptureRollbackAiPaletteDiagnostics(
                    m_image_base, frame.ai_palette))
            {
                frame.valid = false;
                return;
            }
            frame.canonical_hash = m_post_advance_state.canonical_hash;
            frame.component_hash[0] = m_post_advance_state.hgcpu.canonical_hash;
            frame.component_hash[1] =
                m_post_advance_state.explicit_snapshot.canonical_hash;
            frame.component_hash[2] =
                m_post_advance_state.breakable_stage.canonical_hash;
            frame.component_hash[3] =
                m_post_advance_state.stage_wind.canonical_hash;
            frame.hgcpu_peer_hash =
                RollbackProductionSummaryHgCpuPeerHash(summary);
            frame.explicit_range_digest =
                RollbackProductionSummaryExplicitRangeDigest(summary);
            frame.ccpu_canonical_hash = summary.ccpu_canonical_hash;
            frame.native_round_state_hash = summary.native_round_state_hash;
            frame.native_simulation_state_hash =
                summary.native_simulation_state_hash;
            frame.palette_variant_canonical_hash =
                summary.palette_variant_canonical_hash;
            frame.palette_variant_local_integrity_hash =
                m_post_advance_state.palette_variants.integrity_hash;
            frame.palette_variant_active_mask =
                summary.palette_variant_active_mask;
            frame.input_history_hash = RollbackProductionInputHistoryHash(
                logical_frame, previous_input, summary.input);
            frame.breakable_gameplay_digest =
                m_post_advance_state.breakable_stage.canonical_hash;
            frame.breakable_presentation_digest =
                HashRollbackBreakablePresentationDigest(
                    m_post_advance_state.breakable_stage);
            frame.chara_animation_gameplay_digest =
                RollbackHashCharaAnimationCanonical(
                    m_post_advance_state.hgcpu.chara_animation);
            const RollbackStageWindCanonicalBreakdown wind_breakdown =
                BuildRollbackStageWindCanonicalBreakdown(
                    m_post_advance_state.stage_wind);
            if (wind_breakdown.combined == 0
                || wind_breakdown.combined
                    != frame.component_hash[3])
            {
                frame.valid = false;
                return;
            }
            frame.stage_wind_combined_rng_hash =
                wind_breakdown.combined_rng;
            frame.stage_wind_gameplay_hash =
                HashRollbackStageWindGameplay(
                    m_post_advance_state.stage_wind);
            frame.stage_wind_emitter_hash = wind_breakdown.emitters;
            frame.stage_wind_root_scheduler_hash =
                wind_breakdown.root_scheduler;
            frame.stage_wind_root_outputs_hash =
                wind_breakdown.root_derived_outputs;
            frame.stage_wind_presentation_hash =
                HashRollbackStageWindPresentation(
                    m_post_advance_state.stage_wind);
            if (frame.stage_wind_gameplay_hash == 0
                || frame.stage_wind_presentation_hash == 0)
            {
                frame.valid = false;
                return;
            }
            frame.stage_wind_graph_nodes_hash =
                wind_breakdown.graph_nodes;
            frame.stage_wind_graph_hash = wind_breakdown.graph;
            frame.stage_wind_emitter_count =
                m_post_advance_state.stage_wind.count;
            frame.stage_wind_graph_count =
                m_post_advance_state.stage_wind.graph.count;
            frame.stage_wind_output_active =
                m_post_advance_state.stage_wind.output_active;
            const auto& wind_root =
                m_post_advance_state.stage_wind.graph.root_state;
            frame.stage_wind_active_bank = wind_root.active_bank;
            frame.stage_wind_pending_count = wind_root.pending_count;
            frame.stage_wind_schedule_state = wind_root.schedule_state;
            frame.stage_wind_effect_pair_scheduled =
                wind_root.effect_pair_scheduled;
            frame.stage_wind_output_forces = wind_root.output_forces;
            for (uint32_t index = 0;
                 index < frame.stage_wind_graph_count
                    && index < frame.stage_wind_node_vtable_rva.size();
                 ++index)
            {
                const RollbackStageWindNodeCanonicalBreakdown node =
                    BuildRollbackStageWindNodeCanonicalBreakdown(
                        m_post_advance_state.stage_wind.graph.nodes[index]);
                if (!node.valid)
                {
                    frame.valid = false;
                    return;
                }
                frame.stage_wind_node_vtable_rva[index] =
                    node.vtable_rva;
                frame.stage_wind_node_bytes[index] = node.bytes;
                frame.stage_wind_node_hash[index] = node.combined;
                frame.stage_wind_node_common_hash[index] = node.common;
                frame.stage_wind_node_body_hash[index] = node.body;
                frame.stage_wind_node_tail_hash[index] = node.tail;
                std::memcpy(
                    frame.stage_wind_node_common_words[index].data(),
                    m_post_advance_state.stage_wind.graph.nodes[index]
                        .data.data()
                        + 0x30,
                    sizeof(frame.stage_wind_node_common_words[index]));
                if (wind_detail)
                {
                    std::memcpy(
                        wind_detail->node_words[index].data(),
                        m_post_advance_state.stage_wind.graph.nodes[index]
                            .data.data(),
                        node.bytes);
                }
            }
            frame.fighter[0] = ReplayScrubDiag::read_chara_movevm(0);
            frame.fighter[1] = ReplayScrubDiag::read_chara_movevm(1);
            RollbackRngTuple captured_rng {};
            if (!capture_snapshot_rng_tuple(
                    m_post_advance_state, captured_rng)
                || !read_snapshot_range(
                    m_post_advance_state.explicit_snapshot,
                    "g_LuxBattleRoundControlScalars",
                    frame.round_control, sizeof(frame.round_control)))
            {
                frame.valid = false;
                return;
            }
            // The post-Advance state is the Gekko-owned frame boundary.
            // Re-reading live RNG or round-control state here can race the
            // next stock/native iteration and assemble two different frames.
            frame.rng_lcg_state = captured_rng.lcg_state;
            frame.rng_lfsr_hash = captured_rng.lfsr_hash;
            frame.rng_lfsr_index = captured_rng.lfsr_index;
            frame.rng_gameplay_crt_present =
                captured_rng.gameplay_crt_present;
            frame.rng_gameplay_crt_state =
                captured_rng.gameplay_crt.internal_state;
            frame.rng_gameplay_crt_seed =
                captured_rng.gameplay_crt.full_round_seed;
            frame.rng_gameplay_crt_draw_ordinal =
                captured_rng.gameplay_crt.gameplay_draw_ordinal;
            const auto& secondary =
                m_post_advance_state.hgcpu.secondary_event_stack;
            frame.secondary_event_previous_variant_readable = secondary.ok;
            if (secondary.ok)
            {
                for (size_t player = 0; player < 2; ++player)
                {
                    std::memcpy(
                        &frame.secondary_event_previous_variant[player],
                        secondary.bytes[player].data()
                            + kRollbackSecondaryEventScalarOffset + 4,
                        sizeof(
                            frame.secondary_event_previous_variant[player]));
                }
            }
            RollbackReplayOracleState oracle {};
            oracle.input[0] = frame.input[0];
            oracle.input[1] = frame.input[1];
            oracle.rng_lcg_state = frame.rng_lcg_state;
            oracle.rng_lfsr_hash = frame.rng_lfsr_hash;
            oracle.rng_lfsr_index = frame.rng_lfsr_index;
            oracle.rng_gameplay_crt_present =
                frame.rng_gameplay_crt_present;
            oracle.rng_gameplay_crt_state =
                frame.rng_gameplay_crt_state;
            oracle.rng_gameplay_crt_seed =
                frame.rng_gameplay_crt_seed;
            oracle.rng_gameplay_crt_draw_ordinal =
                frame.rng_gameplay_crt_draw_ordinal;
            std::memcpy(oracle.round_control, frame.round_control,
                sizeof(oracle.round_control));
            oracle.breakable_gameplay_digest =
                frame.breakable_gameplay_digest;
            oracle.stage_wind_gameplay_digest =
                frame.stage_wind_gameplay_hash;
            oracle.chara_animation_gameplay_digest =
                frame.chara_animation_gameplay_digest;
            oracle.breakable_presentation_digest =
                frame.breakable_presentation_digest;
            oracle.stage_wind_presentation_digest =
                frame.stage_wind_presentation_hash;
            oracle.fighter[0] =
                BuildRollbackReplayOracleFighterState(frame.fighter[0]);
            oracle.fighter[1] =
                BuildRollbackReplayOracleFighterState(frame.fighter[1]);
            frame.oracle_gameplay_hash_v1 =
                HashRollbackReplayOracleStateLegacyV1(oracle);
            frame.oracle_gameplay_hash_v9 =
                HashRollbackReplayOracleGameplayV9(oracle);
            frame.oracle_gameplay_hash_v10 =
                HashRollbackReplayOracleGameplayV10(oracle);
            frame.oracle_gameplay_hash_v11 =
                HashRollbackReplayOracleGameplayV11(oracle);
            frame.oracle_gameplay_hash_v12 =
                HashRollbackReplayOracleGameplayV12(oracle);
            frame.oracle_presentation_hash =
                HashRollbackReplayOraclePresentationV12(oracle);
            // Keep the bounded prefix independently diagnosable at the same
            // semantic granularity as the normal oracle. A frame may be
            // simulated more than once; the analyzer only attaches a
            // checkpoint whose complete node hash matches the eventual
            // pair-confirmed frame.
            if (logical_frame < kRollbackReplayStageWindTracePrefixFrames)
            {
                emit_stage_wind_phase_diagnostic(
                    "logical-frame-post-advance",
                    m_post_advance_state.stage_wind,
                    static_cast<int32_t>(logical_frame));
            }
            emit_replay_trace_frame(
                frame, false, true, rolling_back, running_ahead);
            if (logical_frame == 0
                && !rolling_back
                && RngTraceHook::instance().active())
            {
                RngTraceHook::instance().end_window(
                    m_config.replay_deep_trace_diagnostics,
                    "rollback-frame-zero",
                    "post-native-through-trace-frame-0",
                    0, 0, 0, -1, -1,
                    static_cast<int32_t>(
                        m_active_replay_input_config.round_index),
                    0, static_cast<int32_t>(frame.source_index),
                    m_pair_epoch, m_round_generation);
            }
        }
#else
        bool revoke_terminal_candidate_authority(uint32_t) noexcept
        {
            fail_closed("gekkonet-disabled");
            return false;
        }

        void emit_replay_trace_frame(
            const RollbackReplayTraceFrame&,
            bool, bool, bool, bool, bool = false) noexcept
        {
            fail_closed("gekkonet-disabled");
        }
#endif

        bool terminal_candidate_frame_retained(uint32_t frame) const noexcept
        {
            return m_round_terminal_local_edge_frame.valid
                && m_round_terminal_capture_end.valid
                && !RollbackFrameIsAfter(
                    m_round_terminal_local_edge_frame.value, frame)
                && !RollbackFrameIsAfter(
                    frame, m_round_terminal_capture_end.value);
        }

        bool inspect_terminal_pair_proof_tail(bool& ready) noexcept
        {
            ready = false;
            if (!m_round_terminal_pending || m_round_terminal_quiesced)
                return true;
            if (!m_local_round_transition_barrier_valid
                || !m_remote_round_transition_barrier_valid
                || !RollbackRoundTransitionBarriersMatch(
                    m_local_round_transition_barrier,
                    m_remote_round_transition_barrier))
            {
                fail_closed("terminal-pair-proof-barrier-invalid");
                return false;
            }
            const RollbackFrameStamp& next_expected =
                m_summary_consensus.expected();
            if (!next_expected.valid)
                return true;
            const uint32_t terminal_frame =
                m_local_round_transition_barrier.confirmed_frame;
            m_status.terminal_pair_proof_scan_start = next_expected.value;
            m_status.terminal_pair_proof_scan_terminal = terminal_frame;
            m_status.terminal_pair_proof_first_missing_frame = 0;
            m_status.terminal_pair_proof_first_missing_mask = 0;
            m_status.terminal_pair_proof_missing_local_frame = 0;
            m_status.terminal_pair_proof_missing_remote_frame = 0;
            m_status.terminal_pair_proof_missing_pair_frame = 0;
            m_status.terminal_pair_proof_missing_remote_flags = 0;
            m_status.terminal_pair_proof_missing_local_result = 0;
            m_status.terminal_pair_proof_missing_remote_result = 0;
            if (terminal_frame
                    != m_status.stock_round_terminal_confirmed_frame
                || m_local_round_transition_barrier.canonical_hash
                    != m_status.stock_round_terminal_canonical_hash
                || terminal_frame
                    != m_status.stock_round_terminal_last_agreed_frame
                || m_pair_epoch
                    != m_status.stock_round_terminal_last_agreed_pair_epoch)
            {
                fail_closed("terminal-pair-proof-agreement-identity-mismatch");
                return false;
            }
            if (RollbackFrameIsAfter(next_expected.value, terminal_frame))
            {
                ready = true;
                return true;
            }
            const uint32_t tail_count = RollbackFrameDistance(
                terminal_frame, next_expected.value) + 1u;
            if (tail_count > kRollbackProductionSummaryWindowCapacity)
            {
                fail_closed("terminal-pair-proof-tail-too-large");
                return false;
            }
            for (uint32_t offset = 0; offset < tail_count; ++offset)
            {
                const uint32_t frame = next_expected.value + offset;
                const size_t slot =
                    frame & kRollbackProductionFrameHistoryMask;
                const bool local_present = m_local_summary_valid[slot]
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].frame == frame;
                const bool remote_present =
                    m_remote_terminal_candidate_valid[slot]
                    && m_remote_terminal_candidates[slot].epoch
                        == m_pair_epoch
                    && m_remote_terminal_candidates[slot].frame == frame;
                const bool pair_present =
                    m_pair_terminal_candidate_valid[slot]
                    && m_pair_terminal_candidate_frame[slot] == frame;
                const uint8_t missing_mask =
                    RollbackProductionTerminalTailMissingMask(
                        local_present, remote_present, pair_present);
                if (missing_mask != 0)
                {
                    m_status.terminal_pair_proof_first_missing_frame = frame;
                    m_status.terminal_pair_proof_first_missing_mask =
                        missing_mask;
                    m_status.terminal_pair_proof_missing_local_frame =
                        m_local_summary_valid[slot]
                            ? m_local_summaries[slot].frame : 0;
                    m_status.terminal_pair_proof_missing_remote_frame =
                        m_remote_terminal_candidate_valid[slot]
                            ? m_remote_terminal_candidates[slot].frame : 0;
                    m_status.terminal_pair_proof_missing_pair_frame =
                        m_pair_terminal_candidate_valid[slot]
                            ? m_pair_terminal_candidate_frame[slot] : 0;
                    m_status.terminal_pair_proof_missing_remote_flags =
                        m_remote_terminal_candidate_valid[slot]
                            ? m_remote_terminal_candidates[slot].flags : 0;
                    m_status.terminal_pair_proof_missing_local_result =
                        m_local_summary_valid[slot]
                            ? m_local_summaries[slot]
                                .terminal_round_result : 0;
                    m_status.terminal_pair_proof_missing_remote_result =
                        m_remote_terminal_candidate_valid[slot]
                            ? m_remote_terminal_candidates[slot]
                                .terminal_round_result : 0;
                    return true;
                }
                const RollbackProductionFrameSummary& local =
                    m_local_summaries[slot];
                const RollbackProductionFrameSummary& remote =
                    m_remote_terminal_candidates[slot];
                if (local.epoch != m_pair_epoch || remote.epoch != m_pair_epoch
                    || local.frame != frame || remote.frame != frame
                    || m_pair_terminal_candidate_frame[slot] != frame)
                {
                    fail_closed("terminal-pair-proof-tail-storage-mismatch");
                    return false;
                }
                if (!RollbackProductionTerminalPairProofMatches(
                        true,
                        m_pair_terminal_candidate_frame[slot],
                        m_pair_terminal_candidate_hash[slot],
                        local, remote))
                {
                    fail_closed("terminal-pair-proof-tail-mismatch");
                    return false;
                }
                if (frame == terminal_frame
                    && local.canonical_hash
                        != m_status.stock_round_terminal_canonical_hash)
                {
                    fail_closed("terminal-pair-proof-selected-hash-mismatch");
                    return false;
                }
                if (m_config.replay_trace_compare)
                {
                    const RollbackReplayTraceFrame& trace =
                        m_replay_trace_frames[slot];
                    if (!trace.valid
                        || trace.lifecycle_epoch
                            != m_manifest.epoch.generation
                        || trace.round_epoch != m_pair_epoch
                        || trace.round_generation != m_round_generation
                        || trace.logical_frame != frame
                        || trace.canonical_hash != local.canonical_hash
                        || trace.input[0] != local.input[0]
                        || trace.input[1] != local.input[1])
                    {
                        fail_closed("terminal-pair-proof-trace-mismatch");
                        return false;
                    }
                }
            }
            ready = true;
            return true;
        }

        bool finalize_terminal_pair_proof_tail() noexcept
        {
            if (m_terminal_pair_proof_tail_finalized) return true;
            bool ready = false;
            if (!inspect_terminal_pair_proof_tail(ready) || !ready)
                return false;
            const uint32_t first_frame = m_summary_consensus.expected().value;
            const uint32_t terminal_frame =
                m_status.stock_round_terminal_confirmed_frame;
            if (RollbackFrameIsAfter(first_frame, terminal_frame))
            {
                m_terminal_pair_proof_tail_finalized = true;
                m_status.terminal_pair_proof_tail_finalized = true;
                return true;
            }
            const uint32_t tail_count =
                RollbackFrameDistance(terminal_frame, first_frame) + 1u;
            for (uint32_t offset = 0; offset < tail_count; ++offset)
            {
                const uint32_t frame = first_frame + offset;
                const size_t slot =
                    frame & kRollbackProductionFrameHistoryMask;
                const RollbackProductionFrameSummary& confirmed =
                    m_local_summaries[slot];
                if (m_config.replay_input.enabled)
                {
                    std::array<uint32_t, 2> replay_expected {};
                    bool neutral_tail = false;
                    for (uint8_t input_slot = 0; input_slot < 2; ++input_slot)
                    {
                        uint32_t replay_index = 0;
                        bool slot_neutral_tail = false;
                        if (!m_replay_input_source.consumed_input_or_neutral_tail(
                                m_active_replay_input_config, input_slot, frame,
                                m_config.input_delay,
                                replay_expected[input_slot], replay_index,
                                slot_neutral_tail))
                        {
                            fail_closed(
                                "terminal-pair-proof-replay-input-unavailable");
                            return false;
                        }
                        neutral_tail = neutral_tail || slot_neutral_tail;
                    }
                    if (neutral_tail)
                        ++m_status.replay_confirmed_neutral_tail_checks;
                    ++m_status.replay_consumed_checks;
                    if (confirmed.input[0] != replay_expected[0]
                        || confirmed.input[1] != replay_expected[1])
                    {
                        ++m_status.replay_consumed_mismatches;
                        fail_closed(
                            "terminal-pair-proof-replay-input-mismatch");
                        return false;
                    }
                }
                m_status.confirmed_frame = frame;
                m_status.confirmed_canonical_hash = confirmed.canonical_hash;
                if (m_config.replay_trace_compare
                    && ReplayDebugTrace::instance().enabled())
                {
                    emit_replay_trace_frame(
                        m_replay_trace_frames[slot],
                        true, false, false, false, true);
                }
                const uint8_t local_slot = m_config.local_player_slot;
                const uint8_t remote_slot =
                    static_cast<uint8_t>(1u - local_slot);
                m_local_confirmed_input_hash.add_scalar(frame);
                m_local_confirmed_input_hash.add_scalar(
                    confirmed.input[local_slot]);
                m_remote_confirmed_input_hash.add_scalar(frame);
                m_remote_confirmed_input_hash.add_scalar(
                    confirmed.input[remote_slot]);
                m_status.local_input_hash =
                    m_local_confirmed_input_hash.value;
                m_status.remote_input_hash =
                    m_remote_confirmed_input_hash.value;
                const uint32_t local_confirmed =
                    confirmed.input[local_slot];
                const uint32_t remote_confirmed =
                    confirmed.input[remote_slot];
                if (!m_config.deterministic_input.enabled
                    && !m_config.replay_input.enabled)
                {
                    if (local_confirmed != 0)
                        ++m_status.native_local_nonzero_inputs;
                    if (remote_confirmed != 0)
                        ++m_status.native_remote_nonzero_inputs;
                    if (m_status.local_input_count != 0
                        && local_confirmed
                            != m_status.native_last_local_input)
                    {
                        ++m_status.native_local_input_transitions;
                    }
                    if (m_status.remote_input_count != 0
                        && remote_confirmed
                            != m_status.native_last_remote_input)
                    {
                        ++m_status.native_remote_input_transitions;
                    }
                    m_status.native_last_local_input = local_confirmed;
                    m_status.native_last_remote_input = remote_confirmed;
                }
                ++m_status.local_input_count;
                ++m_status.remote_input_count;
                ++m_status.terminal_pair_proof_accepts;
            }
            m_pending_effect_confirmation = terminal_frame;
            m_terminal_pair_proof_tail_finalized = true;
            m_status.terminal_pair_proof_tail_finalized = true;
            return true;
        }

        bool try_match_terminal_candidate(uint32_t frame) noexcept
        {
            const size_t slot =
                frame & kRollbackProductionFrameHistoryMask;
            if (!m_local_summary_valid[slot]
                || !m_remote_terminal_candidate_valid[slot])
            {
                return true;
            }
            const RollbackProductionFrameSummary& local =
                m_local_summaries[slot];
            const RollbackProductionFrameSummary& remote =
                m_remote_terminal_candidates[slot];
            if (local.epoch != m_pair_epoch || remote.epoch != m_pair_epoch
                || local.frame != frame || remote.frame != frame)
            {
                return true;
            }
            if (!RollbackProductionTerminalEvidenceMatches(local, remote))
            {
                ++m_status.stock_round_terminal_candidate_mismatches;
                return true;
            }
            if (m_pair_terminal_candidate_valid[slot]
                && m_pair_terminal_candidate_frame[slot] == frame
                && m_pair_terminal_candidate_hash[slot]
                    == local.canonical_hash)
            {
                return true;
            }
            if (remote.flags == kRollbackProductionSummaryTerminalTail)
            {
                const RollbackFrameStamp& next_expected =
                    m_summary_consensus.expected();
                const uint32_t terminal_frame =
                    m_status.stock_round_terminal_confirmed_frame;
                const auto action =
                    ClassifyRollbackProductionTerminalTailEvidence(
                        m_round_terminal_pending,
                        next_expected.valid,
                        next_expected.valid ? next_expected.value : 0,
                        terminal_frame,
                        frame);
                if (action
                    == RollbackProductionTerminalTailEvidenceAction::
                        StageUntilAgreement)
                {
                    return true;
                }
                if (action
                    == RollbackProductionTerminalTailEvidenceAction::
                        DiscardRetired)
                {
                    m_remote_terminal_candidate_valid[slot] = false;
                    ++m_status.round_stale_packets_discarded;
                    return true;
                }
                if (action
                    != RollbackProductionTerminalTailEvidenceAction::Match)
                {
                    fail_closed("terminal-tail-evidence-outside-agreed-tail");
                    return false;
                }
                m_pair_terminal_candidate_valid[slot] = true;
                m_pair_terminal_candidate_frame[slot] = frame;
                m_pair_terminal_candidate_hash[slot] = local.canonical_hash;
                ++m_status.terminal_tail_evidence_matches;
                return true;
            }
            if (!terminal_candidate_frame_retained(frame))
            {
                fail_closed("terminal-candidate-outside-retained-window");
                return false;
            }
            if (!capture_pair_matched_round_terminal(
                    frame, local.canonical_hash))
            {
                return false;
            }
            if (!RollbackTerminalCandidateProposalEvidenceReady(
                    m_pair_terminal_candidate_valid[slot],
                    m_pair_terminal_candidate_frame[slot],
                    m_pair_terminal_candidate_hash[slot],
                    frame, local.canonical_hash,
                    m_round_terminal_candidate_pair_matched,
                    m_round_terminal_candidate_frame.valid,
                    m_round_terminal_candidate_frame.value,
                    m_round_terminal_candidate_handle.valid()))
            {
                fail_closed("terminal-candidate-authority-publication-invalid");
                return false;
            }
            ++m_status.stock_round_terminal_candidate_matches;
            if (!m_local_round_transition_barrier_valid
                && (!m_pending_terminal_candidate_proposal_frame.valid
                    || RollbackFrameIsAfter(
                        frame,
                        m_pending_terminal_candidate_proposal_frame.value)))
            {
                m_pending_terminal_candidate_proposal_frame =
                    RollbackFrameStamp::From(frame);
                m_pending_terminal_candidate_proposal_hash =
                    local.canonical_hash;
            }
            return true;
        }

        const RollbackProductionFrameSummary* terminal_local_summary(
            uint32_t frame) const noexcept
        {
            const size_t slot =
                frame & kRollbackProductionFrameHistoryMask;
            if (m_local_summary_valid[slot]
                && m_local_summaries[slot].epoch == m_pair_epoch
                && m_local_summaries[slot].frame == frame)
            {
                return &m_local_summaries[slot];
            }
            return m_terminal_summary_archive.find(m_pair_epoch, frame);
        }

        bool send_terminal_candidate(
            uint32_t frame, bool retryable_redundant = false) noexcept
        {
            const RollbackProductionFrameSummary* source =
                terminal_local_summary(frame);
            if (!source)
            {
                return true;
            }
            const size_t slot =
                frame & kRollbackProductionFrameHistoryMask;
            const bool terminal_tail = m_round_terminal_pending
                && m_status.stock_round_terminal_resend_start
                    <= m_status.stock_round_terminal_confirmed_frame
                && !RollbackFrameIsAfter(
                    m_status.stock_round_terminal_resend_start, frame)
                && RollbackFrameIsAfter(
                    m_status.stock_round_terminal_confirmed_frame, frame);
            if (!terminal_tail
                && (!terminal_candidate_frame_retained(frame)
                    || source->terminal_round_result == 0))
            {
                return true;
            }
            RollbackProductionFrameSummary candidate =
                *source;
            candidate.flags = terminal_tail
                ? kRollbackProductionSummaryTerminalTail
                : kRollbackProductionSummaryTerminalCandidate;
            if (!RollbackProductionTerminalEvidenceValid(candidate))
            {
                fail_closed("local-terminal-candidate-invalid");
                return false;
            }
            const bool tail_already_sent = terminal_tail
                && m_terminal_tail_evidence_sent[slot]
                && m_terminal_tail_evidence_sent_frame[slot] == frame;
            const bool use_redundant_queue = retryable_redundant
                && (!terminal_tail || tail_already_sent);
            const bool queued = use_redundant_queue
                ? m_network->enqueue_redundant(
                    RollbackProtocolV2PacketType::Input,
                    &candidate, sizeof(candidate), {},
                    m_session_handshake_generation)
                : m_network->enqueue(
                    RollbackProtocolV2PacketType::Input,
                    &candidate, sizeof(candidate), {},
                    m_session_handshake_generation);
            if (!queued)
            {
                if (!use_redundant_queue)
                    fail_closed("terminal-candidate-queue-failed");
                return false;
            }
            ++m_status.stock_round_terminal_candidates_sent;
            if (terminal_tail)
            {
                m_terminal_tail_evidence_sent[slot] = true;
                m_terminal_tail_evidence_sent_frame[slot] = frame;
                ++m_status.terminal_tail_evidence_sent;
            }
            return try_match_terminal_candidate(frame);
        }

        bool resend_terminal_candidate(
            bool retryable_redundant = false) noexcept
        {
            if (m_round_terminal_pending)
            {
                const uint32_t terminal_frame =
                    m_status.stock_round_terminal_confirmed_frame;
                const uint32_t resend_start =
                    m_status.stock_round_terminal_resend_start;
                if (RollbackFrameIsAfter(resend_start, terminal_frame))
                {
                    fail_closed("terminal-tail-resend-start-invalid");
                    return false;
                }
                const uint32_t count = RollbackFrameDistance(
                    terminal_frame, resend_start) + 1u;
                if (count > kRollbackProductionSummaryWindowCapacity)
                {
                    fail_closed("terminal-tail-resend-window-too-large");
                    return false;
                }
                uint32_t frame = m_terminal_candidate_resend_frame.valid
                    ? m_terminal_candidate_resend_frame.value
                    : resend_start;
                if (RollbackFrameIsAfter(resend_start, frame)
                    || RollbackFrameIsAfter(frame, terminal_frame))
                {
                    frame = resend_start;
                }
                const size_t resend_budget =
                    RollbackProductionTerminalTailResendBudget(count);
                size_t sent = 0;
                for (uint32_t offset = 0;
                     offset < count && sent < resend_budget;
                     ++offset)
                {
                    if (RollbackFrameIsAfter(frame, terminal_frame))
                        frame = resend_start;
                    m_terminal_candidate_resend_frame =
                        RollbackFrameStamp::From(frame + 1u);
                    const size_t slot =
                        frame & kRollbackProductionFrameHistoryMask;
                    if (terminal_local_summary(frame))
                    {
                        if (!send_terminal_candidate(
                                frame, retryable_redundant))
                        {
                            return false;
                        }
                        ++sent;
                    }
                    ++frame;
                }
                return true;
            }
            if (!m_round_terminal_local_edge_frame.valid
                || !m_round_terminal_capture_end.valid
                || m_round_terminal_quiesced)
            {
                return true;
            }
            uint32_t frame = m_terminal_candidate_resend_frame.valid
                ? m_terminal_candidate_resend_frame.value
                : m_round_terminal_local_edge_frame.value;
            for (uint32_t count = 0;
                 count <= m_config.rollback_window; ++count)
            {
                if (RollbackFrameIsAfter(
                        frame, m_round_terminal_capture_end.value))
                {
                    frame = m_round_terminal_local_edge_frame.value;
                }
                const uint32_t next = frame + 1u;
                m_terminal_candidate_resend_frame =
                    RollbackFrameStamp::From(next);
                const size_t slot =
                    frame & kRollbackProductionFrameHistoryMask;
                if (m_local_summary_valid[slot]
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].frame == frame
                    && m_local_summaries[slot].terminal_round_result != 0)
                {
                    return send_terminal_candidate(
                        frame, retryable_redundant);
                }
                frame = next;
            }
            return true;
        }

        void accept_peer_terminal_candidate(
            const RollbackUdpMessage& message,
            const RollbackProductionFrameSummary& candidate) noexcept
        {
            const bool candidate_valid =
                RollbackProductionTerminalEvidenceValid(candidate);
            if (!candidate_valid)
            {
                trace_terminal_candidate_receipt(
                    message, candidate, candidate_valid,
                    RollbackTerminalCandidateReceiptAction::Reject,
                    false, false, false, false);
                fail_closed("peer-terminal-candidate-invalid");
                return;
            }
            const size_t slot =
                candidate.frame & kRollbackProductionFrameHistoryMask;
            const bool exact_duplicate =
                m_remote_terminal_candidate_valid[slot]
                && m_remote_terminal_candidates[slot].epoch == candidate.epoch
                && m_remote_terminal_candidates[slot].frame == candidate.frame
                && RollbackProductionTerminalEvidenceMatches(
                    m_remote_terminal_candidates[slot], candidate);
            const bool pair_proof_still_valid =
                m_local_summary_valid[slot]
                && RollbackProductionTerminalPairProofMatches(
                    m_pair_terminal_candidate_valid[slot],
                    m_pair_terminal_candidate_frame[slot],
                    m_pair_terminal_candidate_hash[slot],
                    m_local_summaries[slot], candidate);
            const bool active_phase =
                m_round_phase == RollbackRoundPhase::Active
                || m_round_phase == RollbackRoundPhase::ConfirmingRoundEnd;
            const bool immutable_phase =
                m_round_terminal_pending || m_round_terminal_quiesced
                || m_round_phase == RollbackRoundPhase::TerminalAccepted
                || m_round_phase == RollbackRoundPhase::StockInterRound;
            const bool accepted_terminal =
                m_local_round_transition_barrier_valid
                && m_remote_round_transition_barrier_valid
                && RollbackRoundTransitionBarrierComplete(
                    m_local_round_transition_barrier,
                    m_remote_round_transition_barrier);
            const bool superseded_by_accepted_terminal =
                RollbackTerminalCandidateSupersededByAcceptedTerminal(
                    accepted_terminal,
                    m_local_round_transition_barrier.pair_epoch,
                    m_local_round_transition_barrier.confirmed_frame,
                    candidate.epoch, candidate.frame);
            const auto receipt = ClassifyRollbackTerminalCandidateReceipt(
                m_pair_epoch, m_previous_pair_epoch, candidate.epoch,
                active_phase, immutable_phase, exact_duplicate,
                superseded_by_accepted_terminal);
            if (receipt == RollbackTerminalCandidateReceiptAction::Reject)
            {
                trace_terminal_candidate_receipt(
                    message, candidate, candidate_valid, receipt,
                    active_phase, immutable_phase, exact_duplicate,
                    superseded_by_accepted_terminal);
            }
            if (receipt
                == RollbackTerminalCandidateReceiptAction::
                    DiscardCompletedRound)
            {
                ++m_status.round_stale_packets_discarded;
                return;
            }
            if (m_remote_terminal_candidate_sequence[slot] != 0
                && message.sequence
                    <= m_remote_terminal_candidate_sequence[slot])
            {
                return;
            }
            if (receipt
                == RollbackTerminalCandidateReceiptAction::
                    DiscardExactDuplicate)
            {
                m_remote_terminal_candidate_sequence[slot] =
                    message.sequence;
                ++m_status.round_stale_packets_discarded;
                // Tail evidence can arrive before this peer observes the
                // matching terminal proposal. Once agreement is immutable,
                // an exact retransmission must retry the staged pair match;
                // merely discarding it can strand the peer forever.
                if (m_round_terminal_pending
                    && !try_match_terminal_candidate(candidate.frame))
                {
                    return;
                }
                return;
            }
            if (receipt
                == RollbackTerminalCandidateReceiptAction::
                    DiscardSupersededCandidate)
            {
                ++m_status.round_stale_packets_discarded;
                return;
            }
            if (receipt != RollbackTerminalCandidateReceiptAction::Accept)
            {
                fail_closed("peer-terminal-candidate-invalid");
                return;
            }
            if (m_remote_terminal_candidate_valid[slot])
            {
                const auto& previous = m_remote_terminal_candidates[slot];
                if (previous.epoch != candidate.epoch
                    || previous.frame != candidate.frame)
                {
                    fail_closed("peer-terminal-candidate-ring-collision");
                    return;
                }
                ++m_status.stock_round_terminal_candidate_replacements;
            }
            m_remote_terminal_candidates[slot] = candidate;
            m_remote_terminal_candidate_valid[slot] = true;
            m_remote_terminal_candidate_sequence[slot] = message.sequence;
            ++m_status.stock_round_terminal_candidates_received;
            if (candidate.flags == kRollbackProductionSummaryTerminalTail)
                ++m_status.terminal_tail_evidence_received;
            const bool current_pair_proof =
                m_pair_terminal_candidate_valid[slot]
                && m_pair_terminal_candidate_frame[slot] == candidate.frame;
            const bool selected_for_proposal =
                (m_local_round_transition_barrier_valid
                    && m_local_round_transition_barrier.confirmed_frame
                        == candidate.frame)
                || (m_remote_round_transition_barrier_valid
                    && m_remote_round_transition_barrier.confirmed_frame
                        == candidate.frame);
            const auto replacement_action =
                DecideRollbackTerminalCandidateReplacement(
                    current_pair_proof,
                    pair_proof_still_valid,
                    selected_for_proposal,
                    m_round_terminal_pending || m_round_terminal_quiesced);
            if (replacement_action
                == RollbackTerminalCandidateReplacementAction::RejectImmutable)
            {
                fail_closed("terminal-candidate-replaced-after-agreement");
                return;
            }
            if (replacement_action
                    == RollbackTerminalCandidateReplacementAction::Revoke
                && !revoke_terminal_candidate_authority(candidate.frame))
            {
                return;
            }
            (void)try_match_terminal_candidate(candidate.frame);
        }

        void accept_peer_summary(const RollbackUdpMessage& message) noexcept
        {
            const bool post_round_without_current_epoch = m_pair_epoch == 0
                && (m_round_phase == RollbackRoundPhase::StockInterRound
                    || m_round_phase == RollbackRoundPhase::MatchComplete);
            if (message.payload_bytes
                == sizeof(RollbackProductionSummaryAckWindow))
            {
                RollbackProductionSummaryAckWindow ack {};
                std::memcpy(&ack, message.payload.data(), sizeof(ack));
                if (m_pair_epoch == 0)
                {
                    if (RollbackProductionCompletedEpochTrafficDiscardable(
                            post_round_without_current_epoch,
                            m_previous_pair_epoch, ack.epoch,
                            RollbackProductionSummaryAckWindowStructurallyValid(
                                ack)))
                    {
                        ++m_status.round_stale_packets_discarded;
                        return;
                    }
                    fail_closed("peer-summary-before-pair-epoch");
                    return;
                }
                accept_peer_summary_ack_window(ack);
                return;
            }
            if (message.payload_bytes != sizeof(RollbackProductionFrameSummary))
            {
                fail_closed("peer-summary-size-mismatch");
                return;
            }
            RollbackProductionFrameSummary summary {};
            std::memcpy(&summary, message.payload.data(), sizeof(summary));
            if (m_pair_epoch == 0)
            {
                const RollbackProductionSummaryChannel channel =
                    ClassifyRollbackProductionSummaryChannel(summary.flags);
                const bool structurally_valid = channel
                        == RollbackProductionSummaryChannel::TerminalCandidate
                    ? RollbackProductionTerminalEvidenceValid(summary)
                    : channel == RollbackProductionSummaryChannel::Consensus
                        && summary.epoch != 0
                        && summary.canonical_hash != 0;
                if (RollbackProductionCompletedEpochTrafficDiscardable(
                        post_round_without_current_epoch,
                        m_previous_pair_epoch, summary.epoch,
                        structurally_valid))
                {
                    ++m_status.round_stale_packets_discarded;
                    return;
                }
                fail_closed("peer-summary-before-pair-epoch");
                return;
            }
            if (summary.flags == kRollbackProductionSummaryConfirmed
                && !accept_peer_embedded_summary_ack(summary))
            {
                if (m_status.state != RollbackProductionState::Fatal)
                    fail_closed("embedded-summary-ack-invalid");
                return;
            }
            const RollbackProductionSummaryChannel channel =
                ClassifyRollbackProductionSummaryChannel(summary.flags);
            if (channel
                == RollbackProductionSummaryChannel::TerminalCandidate)
            {
                accept_peer_terminal_candidate(message, summary);
                return;
            }
            if (channel != RollbackProductionSummaryChannel::Consensus
                || summary.epoch != m_pair_epoch
                || summary.canonical_hash == 0)
            {
                fail_closed("peer-summary-epoch-mismatch");
                return;
            }
            const RollbackSummaryFrameClass frame_class =
                m_summary_consensus.classify(summary.frame);
            if (frame_class == RollbackSummaryFrameClass::Stale)
            {
                // A newly sequenced retransmission can outlive the 128-slot
                // application ring. It is already below the contiguous pair
                // frontier: re-ACK Confirmed so the peer can retire it, and
                // ignore stale ACKs without touching the reused slot.
                if (summary.flags
                    == kRollbackProductionSummaryConfirmed)
                {
                    if (!send_summary_ack(summary))
                        fail_closed("stale-summary-ack-queue-failed");
                }
                return;
            }
            if (frame_class == RollbackSummaryFrameClass::TooFarAhead)
            {
                fail_closed("peer-summary-outside-acceptance-window");
                return;
            }
            if (summary.flags == kRollbackProductionSummaryConfirmed)
            {
                if (!m_summary_receive_ack.valid()
                    && m_first_advance_frame.valid)
                {
                    m_summary_receive_ack.start(
                        m_first_advance_frame.value);
                }
                if (!m_summary_receive_ack.observe(summary.frame))
                {
                    fail_closed("summary-receipt-window-collision");
                    return;
                }
            }
            const size_t slot =
                summary.frame & kRollbackProductionFrameHistoryMask;
            if (summary.flags == kRollbackProductionSummaryAck)
            {
                const RollbackProductionFrameSummary& local =
                    m_local_summaries[slot];
                if (local.frame != summary.frame
                    || local.epoch != summary.epoch
                    || local.flags != kRollbackProductionSummaryConfirmed
                    || !RollbackProductionSummaryStateMatches(
                        local, summary))
                {
                    fail_closed("invalid-confirmed-summary-ack");
                    return;
                }
                if (!m_summary_consensus.observe_peer_ack(summary.frame))
                {
                    fail_closed("summary-ack-window-collision");
                    return;
                }
                advance_pair_frontier();
                return;
            }

            if (m_remote_summary_valid[slot]
                && m_remote_summaries[slot].frame != summary.frame)
            {
                fail_closed("remote-summary-ring-overwrite");
                return;
            }
            m_remote_summaries[slot] = summary;
            m_remote_summary_valid[slot] = true;
            match_summary(summary.frame);
            if (m_status.state != RollbackProductionState::Fatal
                && !send_summary_ack_window())
            {
                fail_closed("summary-receipt-ack-window-queue-failed");
            }
        }

        bool publish_confirmed_summary(uint32_t current_frame) noexcept
        {
            if (!m_first_advance_frame.valid) return true;
            uint32_t confirmed_frame = 0;
            if (!RollbackTryGetConfirmedFrame(
                    current_frame,
                    m_first_advance_frame.value,
                    m_config.rollback_window,
                    confirmed_frame))
                return true;

            // Gekko's health-check horizon is
            // (current - input_prediction_window) - 1. Frames newer than this
            // may still contain a predicted remote input and must not be
            // compared or used to commit presentation effects.
            uint32_t frame_to_publish = 0;
            bool publish_new = false;
            if (!m_last_summary_published.valid)
            {
                frame_to_publish = m_first_advance_frame.value;
                publish_new = !RollbackFrameIsAfter(
                    frame_to_publish, confirmed_frame);
            }
            else if (RollbackFrameIsAfter(
                         confirmed_frame,
                         m_last_summary_published.value))
            {
                frame_to_publish = m_last_summary_published.value + 1u;
                publish_new = true;
            }

            if (publish_new)
            {
                const size_t slot =
                    frame_to_publish & kRollbackProductionFrameHistoryMask;
                if (!m_local_summary_valid[slot]
                    || m_local_summaries[slot].frame != frame_to_publish
                    || m_local_summaries[slot].epoch != m_pair_epoch)
                {
                    fail_closed("confirmed-frame-summary-unavailable");
                    return false;
                }
                m_local_summaries[slot].flags =
                    kRollbackProductionSummaryConfirmed;
                stamp_summary_ack_window(m_local_summaries[slot]);
                m_last_summary_published = frame_to_publish;
                m_summary_consensus.start(frame_to_publish);
                m_summary_match_ack.start(frame_to_publish);
                m_summary_receive_ack.start(frame_to_publish);
                m_peer_summary_receipt.start(frame_to_publish);
                if (!m_network->enqueue(
                        RollbackProtocolV2PacketType::Input,
                        &m_local_summaries[slot],
                        sizeof(m_local_summaries[slot]),
                        {},
                        m_session_handshake_generation))
                {
                    fail_closed("confirmed-summary-queue-failed");
                    return false;
                }
                match_summary(frame_to_publish);
                if (m_status.state == RollbackProductionState::Fatal)
                    return false;
            }

            if (!send_oldest_unacknowledged_summary())
            {
                fail_closed("confirmed-summary-queue-failed");
                return false;
            }
            if (!send_summary_ack_window())
            {
                fail_closed("confirmed-summary-ack-window-queue-failed");
                return false;
            }
            return m_status.state != RollbackProductionState::Fatal;
        }

        bool send_oldest_unacknowledged_summary(
            bool retryable_redundant = false) noexcept
        {
            // The cumulative ACK heartbeat repairs lost ACKs, while full
            // summaries repair actual data gaps. Use bounded extra capacity
            // only while the contiguous frontier is behind; otherwise keep
            // the ordinary two-summary recovery budget.
            static constexpr size_t kMaximumSummaryResendBudget = 4;
            uint32_t backlog = 0;
            const RollbackFrameStamp& expected =
                m_summary_consensus.expected();
            if (expected.valid && m_last_summary_published.valid
                && !RollbackFrameIsAfter(
                    expected.value, m_last_summary_published.value))
            {
                backlog = RollbackFrameDistance(
                    m_last_summary_published.value, expected.value) + 1u;
            }
            const size_t resend_budget =
                RollbackProductionSummaryResendBudget(backlog);
            std::array<
                const RollbackProductionFrameSummary*,
                kMaximumSummaryResendBudget> selected {};
            for (size_t resend = 0;
                 resend < resend_budget; ++resend)
            {
                const RollbackProductionFrameSummary* oldest = nullptr;
                for (size_t slot = 0;
                     slot < m_local_summaries.size(); ++slot)
                {
                    const RollbackProductionFrameSummary& candidate =
                        m_local_summaries[slot];
                    if (!m_local_summary_valid[slot]
                        || m_peer_summary_receipt.observed(candidate.frame)
                        || candidate.flags
                            != kRollbackProductionSummaryConfirmed)
                    {
                        continue;
                    }
                    bool already_selected = false;
                    for (size_t prior = 0; prior < resend; ++prior)
                    {
                        if (selected[prior] == &candidate)
                        {
                            already_selected = true;
                            break;
                        }
                    }
                    if (already_selected) continue;
                    if (!oldest
                        || RollbackFrameIsAfter(
                            oldest->frame, candidate.frame))
                    {
                        oldest = &candidate;
                    }
                }
                if (!oldest) break;
                selected[resend] = oldest;
                RollbackProductionFrameSummary retransmission = *oldest;
                stamp_summary_ack_window(retransmission);
                const bool queued = retryable_redundant
                    ? m_network->enqueue_redundant(
                        RollbackProtocolV2PacketType::Input,
                        &retransmission,
                        sizeof(retransmission),
                        {},
                        m_session_handshake_generation)
                    : m_network->enqueue(
                        RollbackProtocolV2PacketType::Input,
                        &retransmission,
                        sizeof(retransmission),
                        {},
                        m_session_handshake_generation);
                if (!queued)
                {
                    return false;
                }
            }
            return true;
        }

        bool send_summary_ack(
            const RollbackProductionFrameSummary& received) noexcept
        {
            RollbackProductionFrameSummary ack = received;
            ack.flags = kRollbackProductionSummaryAck;
            return m_network->enqueue(
                RollbackProtocolV2PacketType::Input,
                &ack,
                sizeof(ack),
                {},
                m_session_handshake_generation);
        }

        bool send_summary_ack_window(
            bool retryable_redundant = false) noexcept
        {
            if (!m_summary_match_ack.valid()) return true;
            RollbackProductionSummaryAckWindow ack {};
            ack.epoch = m_pair_epoch;
            ack.next_unmatched_frame =
                m_summary_match_ack.next_unmatched_frame();
            m_summary_match_ack.selective(ack.selective);
            ack.next_missing_frame =
                m_summary_receive_ack.next_unmatched_frame();
            m_summary_receive_ack.selective(ack.received_selective);
            return retryable_redundant
                ? m_network->enqueue_redundant(
                    RollbackProtocolV2PacketType::Input,
                    &ack,
                    sizeof(ack),
                    {},
                    m_session_handshake_generation)
                : m_network->enqueue(
                    RollbackProtocolV2PacketType::Input,
                    &ack,
                    sizeof(ack),
                    {},
                    m_session_handshake_generation);
        }

        void stamp_summary_ack_window(
            RollbackProductionFrameSummary& summary) const noexcept
        {
            summary.ack_valid = m_summary_match_ack.valid() ? 1u : 0u;
            std::memset(
                summary.ack_reserved, 0, sizeof(summary.ack_reserved));
            summary.ack_next_unmatched_frame =
                m_summary_match_ack.next_unmatched_frame();
            m_summary_match_ack.selective(summary.ack_selective);
            summary.receipt_next_missing_frame =
                m_summary_receive_ack.next_unmatched_frame();
            m_summary_receive_ack.selective(
                summary.receipt_selective);
        }

        bool accept_peer_embedded_summary_ack(
            const RollbackProductionFrameSummary& summary) noexcept
        {
            if (summary.ack_valid == 0)
                return summary.ack_reserved[0] == 0
                    && summary.ack_reserved[1] == 0
                    && summary.ack_reserved[2] == 0;
            if (summary.ack_valid != 1
                || summary.ack_reserved[0] != 0
                || summary.ack_reserved[1] != 0
                || summary.ack_reserved[2] != 0)
            {
                return false;
            }
            RollbackProductionSummaryAckWindow ack {};
            ack.epoch = summary.epoch;
            ack.next_unmatched_frame =
                summary.ack_next_unmatched_frame;
            ack.selective[0] = summary.ack_selective[0];
            ack.selective[1] = summary.ack_selective[1];
            ack.next_missing_frame =
                summary.receipt_next_missing_frame;
            ack.received_selective[0] =
                summary.receipt_selective[0];
            ack.received_selective[1] =
                summary.receipt_selective[1];
            ++m_status.summary_embedded_ack_windows_received;
            accept_peer_summary_ack_window(ack);
            return m_status.state != RollbackProductionState::Fatal;
        }

        void accept_peer_summary_ack_window(
            const RollbackProductionSummaryAckWindow& ack) noexcept
        {
            if (!RollbackProductionSummaryAckWindowValid(
                    ack, m_pair_epoch))
            {
                fail_closed("summary-ack-window-invalid");
                return;
            }
            ++m_status.summary_ack_windows_received;
            m_status.summary_ack_window_last_next_unmatched =
                ack.next_unmatched_frame;
            if (!m_peer_summary_receipt.valid()
                && m_first_advance_frame.valid)
            {
                m_peer_summary_receipt.start(
                    m_first_advance_frame.value);
            }
            if (m_peer_summary_receipt.valid())
            {
                const uint32_t receipt_next =
                    m_peer_summary_receipt.next_unmatched_frame();
                const uint32_t receipt_distance =
                    RollbackFrameIsAfter(
                        ack.next_missing_frame, receipt_next)
                    ? RollbackFrameDistance(
                        ack.next_missing_frame, receipt_next)
                    : 0u;
                if (receipt_distance
                    > kRollbackProductionSummaryWindowCapacity)
                {
                    fail_closed("summary-receipt-ack-too-far-ahead");
                    return;
                }
                for (uint32_t offset = 0;
                     offset < receipt_distance; ++offset)
                {
                    if (!m_peer_summary_receipt.observe(
                            receipt_next + offset))
                    {
                        fail_closed("summary-receipt-ack-collision");
                        return;
                    }
                }
                for (size_t bit = 0;
                     bit < kRollbackProductionSummaryWindowCapacity; ++bit)
                {
                    if ((ack.received_selective[bit / 64u]
                            & (uint64_t {1} << (bit % 64u))) != 0
                        && !m_peer_summary_receipt.observe(
                            ack.next_missing_frame
                                + static_cast<uint32_t>(bit)))
                    {
                        fail_closed(
                            "summary-selective-receipt-ack-collision");
                        return;
                    }
                }
            }
            const RollbackFrameStamp& expected =
                m_summary_consensus.expected();
            if (!expected.valid) return;

            const uint32_t cumulative_distance =
                RollbackFrameIsAfter(
                    ack.next_unmatched_frame, expected.value)
                ? RollbackFrameDistance(
                    ack.next_unmatched_frame, expected.value)
                : 0u;
            if (cumulative_distance
                > kRollbackProductionSummaryWindowCapacity)
            {
                fail_closed("summary-ack-window-too-far-ahead");
                return;
            }
            for (uint32_t offset = 0;
                 offset < cumulative_distance; ++offset)
            {
                const uint32_t frame = expected.value + offset;
                const size_t slot =
                    frame & kRollbackProductionFrameHistoryMask;
                if (m_local_summary_valid[slot]
                    && m_local_summaries[slot].frame == frame
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].flags
                        == kRollbackProductionSummaryConfirmed
                    && !m_summary_consensus.observe_peer_ack(frame))
                {
                    fail_closed("summary-ack-window-collision");
                    return;
                }
                if (m_local_summary_valid[slot]
                    && m_local_summaries[slot].frame == frame
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].flags
                        == kRollbackProductionSummaryConfirmed)
                {
                    ++m_status.summary_ack_window_cumulative_frames_observed;
                }
                else
                {
                    ++m_status.summary_ack_window_frames_missing_locally;
                }
            }
            for (size_t bit = 0;
                 bit < kRollbackProductionSummaryWindowCapacity; ++bit)
            {
                if ((ack.selective[bit / 64u]
                        & (uint64_t {1} << (bit % 64u))) == 0)
                {
                    continue;
                }
                const uint32_t frame =
                    ack.next_unmatched_frame
                    + static_cast<uint32_t>(bit);
                if (m_summary_consensus.classify(frame)
                    != RollbackSummaryFrameClass::InWindow)
                {
                    continue;
                }
                const size_t slot =
                    frame & kRollbackProductionFrameHistoryMask;
                if (m_local_summary_valid[slot]
                    && m_local_summaries[slot].frame == frame
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].flags
                        == kRollbackProductionSummaryConfirmed
                    && !m_summary_consensus.observe_peer_ack(frame))
                {
                    fail_closed("summary-selective-ack-window-collision");
                    return;
                }
                if (m_local_summary_valid[slot]
                    && m_local_summaries[slot].frame == frame
                    && m_local_summaries[slot].epoch == m_pair_epoch
                    && m_local_summaries[slot].flags
                        == kRollbackProductionSummaryConfirmed)
                {
                    ++m_status.summary_ack_window_selective_frames_observed;
                }
                else
                {
                    ++m_status.summary_ack_window_frames_missing_locally;
                }
            }
            advance_pair_frontier();
        }

        void match_summary(uint32_t frame) noexcept
        {
            const size_t slot =
                frame & kRollbackProductionFrameHistoryMask;
            if (!m_local_summary_valid[slot] || !m_remote_summary_valid[slot])
                return;
            const auto& local = m_local_summaries[slot];
            const auto& remote = m_remote_summaries[slot];
            if (local.frame != frame || remote.frame != frame)
                return;
            // A peer can be one or more frames ahead. Its confirmed summary
            // may arrive while our same frame is still speculative; wait until
            // both sides have crossed the Gekko confirmation horizon.
            if (local.flags != kRollbackProductionSummaryConfirmed
                || remote.flags != kRollbackProductionSummaryConfirmed)
                return;
            if (local.epoch != remote.epoch)
            {
                fail_closed("confirmed-summary-epoch-mismatch");
                return;
            }
            const bool terminal_control =
                local.terminal_round_result != 0
                || remote.terminal_round_result != 0;
            if (terminal_control
                && !IsRollbackTerminalControlPairCompatible(
                    local.terminal_round_result,
                    local.round_result_type,
                    remote.terminal_round_result,
                    remote.round_result_type))
            {
                fail_closed("round-result-control-mismatch");
                return;
            }
            if (!RollbackProductionSummaryStateMatches(local, remote))
            {
                m_status.mismatch_frame = frame;
                m_status.mismatch_local_canonical_hash =
                    local.canonical_hash;
                m_status.mismatch_peer_canonical_hash =
                    remote.canonical_hash;
                m_status.mismatch_local_ccpu_hash =
                    local.ccpu_canonical_hash;
                m_status.mismatch_peer_ccpu_hash =
                    remote.ccpu_canonical_hash;
                m_status.mismatch_local_native_round_state_hash =
                    local.native_round_state_hash;
                m_status.mismatch_peer_native_round_state_hash =
                    remote.native_round_state_hash;
                m_status.mismatch_local_native_simulation_state_hash =
                    local.native_simulation_state_hash;
                m_status.mismatch_peer_native_simulation_state_hash =
                    remote.native_simulation_state_hash;
                m_status.mismatch_local_palette_variant_canonical_hash =
                    local.palette_variant_canonical_hash;
                m_status.mismatch_peer_palette_variant_canonical_hash =
                    remote.palette_variant_canonical_hash;
                m_status.mismatch_local_palette_variant_active_mask =
                    local.palette_variant_active_mask;
                m_status.mismatch_peer_palette_variant_active_mask =
                    remote.palette_variant_active_mask;
                std::memcpy(
                    m_status.mismatch_local_component_hash,
                    local.component_hash,
                    sizeof(local.component_hash));
                std::memcpy(
                    m_status.mismatch_peer_component_hash,
                    remote.component_hash,
                    sizeof(remote.component_hash));
                m_status.mismatch_local_hgcpu_peer = local.hgcpu_peer;
                m_status.mismatch_peer_hgcpu_peer = remote.hgcpu_peer;
                m_status.mismatch_hgcpu_peer_mask =
                    RollbackHgCpuPeerBreakdownMismatchMask(
                        local.hgcpu_peer, remote.hgcpu_peer);
                m_status.mismatch_hgcpu_chara_chunk_mask =
                    RollbackHgCpuPeerCharaChunkMismatchMask(
                        local.hgcpu_peer, remote.hgcpu_peer);
                m_status.mismatch_hgcpu_motion_contribution_mask =
                    RollbackHgCpuPeerMotionContributionMismatchMask(
                        local.hgcpu_peer, remote.hgcpu_peer);
                const size_t range_count = (std::min)(
                    static_cast<size_t>(local.explicit_range_count),
                    static_cast<size_t>(remote.explicit_range_count));
                for (size_t i = 0; i < range_count && i < 32; ++i)
                {
                    if (local.explicit_range_hash[i]
                        != remote.explicit_range_hash[i])
                    {
                        m_status.mismatch_explicit_range_mask |=
                            1u << static_cast<uint32_t>(i);
                    }
                }
                m_status.mismatch_local_input[0] = local.input[0];
                m_status.mismatch_local_input[1] = local.input[1];
                m_status.mismatch_peer_input[0] = remote.input[0];
                m_status.mismatch_peer_input[1] = remote.input[1];
                fail_closed("corrected-frame-pair-mismatch");
                return;
            }
            if (terminal_control
                && !capture_pair_matched_round_terminal(
                    frame, local.canonical_hash))
            {
                return;
            }
            if (!m_summary_match_ack.observe(frame))
            {
                fail_closed("summary-match-ack-window-collision");
                return;
            }
            if (!m_summary_consensus.observe_local_match(frame))
            {
                fail_closed("summary-match-window-collision");
                return;
            }
            if (!send_summary_ack_window())
            {
                fail_closed("confirmed-summary-ack-window-queue-failed");
                return;
            }
            advance_pair_frontier();
        }

        void advance_pair_frontier() noexcept
        {
            // Pair acceptance is strictly contiguous. A later matching frame
            // can never skip a dropped or divergent predecessor. Requiring
            // both the local match and the echoed ACK proves both clients
            // compared the frame before either commits presentation effects.
            for (size_t count = 0;
                 count < kRollbackProductionSummaryWindowCapacity; ++count)
            {
                // An ACK can schedule the exact fixture checkpoint outside
                // the owned Gekko batch. Hold the contiguous frontier until
                // finish_gekko_batch confirms and captures that frame.
                if (m_fixture_checkpoint_gate.awaiting_confirmation()) break;
                const RollbackFrameStamp& commit_candidate =
                    m_summary_consensus.expected();
                if (commit_candidate.valid
                    && !RollbackProductionOrdinarySummaryCommitAllowed(
                        m_round_terminal_pending,
                        m_terminal_pair_proof_tail_finalized,
                        commit_candidate.value,
                        m_status.stock_round_terminal_confirmed_frame))
                {
                    break;
                }
                uint32_t expected = 0;
                if (!m_summary_consensus.pop_contiguous(expected)) break;
                const size_t expected_slot =
                    expected & kRollbackProductionFrameHistoryMask;
                if (m_local_summaries[expected_slot].frame != expected
                    || m_remote_summaries[expected_slot].frame != expected)
                {
                    fail_closed("summary-frontier-storage-mismatch");
                    break;
                }
                ++m_status.pair_accepts;
                m_status.confirmed_frame = expected;
                const RollbackFrameStamp& next_expected =
                    m_summary_consensus.expected();
                m_status.summary_consensus_expected_valid =
                    next_expected.valid;
                m_status.summary_consensus_expected =
                    next_expected.valid ? next_expected.value : 0;
                const auto& confirmed =
                    m_local_summaries[expected_slot];
                if (m_config.replay_input.enabled)
                {
                    std::array<uint32_t, 2> replay_expected {};
                    bool neutral_tail = false;
                    for (uint8_t slot = 0; slot < 2; ++slot)
                    {
                        uint32_t replay_index = 0;
                        bool slot_neutral_tail = false;
                        if (!m_replay_input_source.
                                consumed_input_or_neutral_tail(
                                m_active_replay_input_config, slot, expected,
                                m_config.input_delay,
                                replay_expected[slot], replay_index,
                                slot_neutral_tail))
                        {
                            fail_closed(
                                "replay-confirmed-input-unavailable");
                            return;
                        }
                        neutral_tail = neutral_tail || slot_neutral_tail;
                    }
                    if (neutral_tail)
                        ++m_status.replay_confirmed_neutral_tail_checks;
                    ++m_status.replay_consumed_checks;
                    if (confirmed.input[0] != replay_expected[0]
                        || confirmed.input[1] != replay_expected[1])
                    {
                        ++m_status.replay_consumed_mismatches;
                        fail_closed("replay-confirmed-input-mismatch");
                        return;
                    }
                }
                m_status.confirmed_canonical_hash =
                    confirmed.canonical_hash;
                if (m_config.replay_trace_compare
                    && ReplayDebugTrace::instance().enabled())
                {
                    const RollbackReplayTraceFrame& trace =
                        m_replay_trace_frames[expected_slot];
                    if (!trace.valid
                        || trace.lifecycle_epoch != m_manifest.epoch.generation
                        || trace.round_epoch != m_pair_epoch
                        || trace.round_generation != m_round_generation
                        || trace.logical_frame != expected
                        || trace.canonical_hash != confirmed.canonical_hash
                        || trace.input[0] != confirmed.input[0]
                        || trace.input[1] != confirmed.input[1])
                    {
                        fail_closed("confirmed-replay-trace-frame-mismatch");
                        return;
                    }
                    emit_replay_trace_frame(
                        trace, true, false, false, false);
                }
                const uint8_t local_slot = m_config.local_player_slot;
                const uint8_t remote_slot = static_cast<uint8_t>(1u -
                    local_slot);
                m_local_confirmed_input_hash.add_scalar(expected);
                m_local_confirmed_input_hash.add_scalar(
                    confirmed.input[local_slot]);
                m_remote_confirmed_input_hash.add_scalar(expected);
                m_remote_confirmed_input_hash.add_scalar(
                    confirmed.input[remote_slot]);
                m_status.local_input_hash =
                    m_local_confirmed_input_hash.value;
                m_status.remote_input_hash =
                    m_remote_confirmed_input_hash.value;
                const uint32_t local_confirmed =
                    confirmed.input[local_slot];
                const uint32_t remote_confirmed =
                    confirmed.input[remote_slot];
                if (!m_config.deterministic_input.enabled
                    && !m_config.replay_input.enabled)
                {
                    if (local_confirmed != 0)
                        ++m_status.native_local_nonzero_inputs;
                    if (remote_confirmed != 0)
                        ++m_status.native_remote_nonzero_inputs;
                    if (m_status.local_input_count != 0
                        && local_confirmed
                            != m_status.native_last_local_input)
                    {
                        ++m_status.native_local_input_transitions;
                    }
                    if (m_status.remote_input_count != 0
                        && remote_confirmed
                            != m_status.native_last_remote_input)
                    {
                        ++m_status.native_remote_input_transitions;
                    }
                    m_status.native_last_local_input = local_confirmed;
                    m_status.native_last_remote_input = remote_confirmed;
                }
                ++m_status.local_input_count;
                ++m_status.remote_input_count;
                const uint32_t correction_end =
                    m_config.deterministic_input.correction_start
                    + m_config.deterministic_input.hold_updates;
                if (m_config.deterministic_input.enabled
                    && !m_status.fixture_converged
                    && expected >= correction_end)
                {
                    m_status.fixture_converged = true;
                    m_status.fixture_converged_frame = expected;
                    m_status.fixture_converged_canonical_hash =
                        confirmed.canonical_hash;
                    m_status.fixture_converged_local_input_hash =
                        m_status.local_input_hash;
                    m_status.fixture_converged_remote_input_hash =
                        m_status.remote_input_hash;
                }
                const uint32_t fixture_checkpoint_frame =
                    RollbackFixtureCheckpointFrame(
                        m_config.deterministic_input);
                RollbackFixtureCheckpointAction fixture_checkpoint_action =
                    RollbackFixtureCheckpointAction::PassThrough;
                if (RollbackFixturePresentationCheckpointRequired(
                        m_config.deterministic_input.enabled,
                        m_fixture_correction_pending,
                        m_config.native_correction_only))
                {
                    if (!m_fixture_checkpoint_gate.configured_for(
                            m_manifest.epoch.generation,
                            fixture_checkpoint_frame)
                        && !m_fixture_checkpoint_gate.configure(
                            m_manifest.epoch.generation,
                            fixture_checkpoint_frame))
                    {
                        fail_closed("fixture-checkpoint-gate-config-invalid");
                        return;
                    }
                    fixture_checkpoint_action =
                        m_fixture_checkpoint_gate.observe_frontier(
                            m_manifest.epoch.generation, expected);
                    if (fixture_checkpoint_action
                        == RollbackFixtureCheckpointAction::Reject)
                    {
                        fail_closed("fixture-checkpoint-frame-skipped");
                        return;
                    }
                }
                const bool fixture_checkpoint_target =
                    fixture_checkpoint_action
                        == RollbackFixtureCheckpointAction::StopAtTarget;
                if (fixture_checkpoint_target)
                    m_fixture_presentation_checkpoint_ready = true;
                m_remote_summary_valid[expected_slot] = false;
                m_terminal_summary_archive.retain(confirmed);
                m_local_summary_valid[expected_slot] = false;
                if (!m_pending_effect_confirmation.valid
                    || RollbackFrameIsAfter(
                        expected,
                        m_pending_effect_confirmation.value))
                {
                    m_pending_effect_confirmation = expected;
                }
                const auto& peer_confirmed =
                    m_remote_summaries[expected_slot];
                if (m_config.lifecycle_mode
                        == RollbackLifecycleMode::StockOnlinePvp
                    && ShouldQuiesceRollbackRoundTerminal(
                        confirmed.terminal_round_result,
                        peer_confirmed.terminal_round_result)
                    && m_status.transition_round_committed
                        > m_round_transition_commits_at_session_start)
                {
                    // Advertise the first locally safe terminal frame, but do
                    // not quiesce yet. The peers may observe the native edge
                    // on different logical frames; the earlier peer keeps
                    // simulating until both select the later retained frame.
                    if (!propose_confirmed_round_terminal(
                            expected, confirmed.canonical_hash))
                    {
                        return;
                    }
                    return;
                }
                // Commit and capture the exact authenticated fixture target
                // before advancing the contiguous pair frontier again.
                if (fixture_checkpoint_target) return;
            }
        }

        bool observe_fixture_move_state(
            uint32_t frame,
            const uintptr_t fighters[2]) noexcept
        {
            if (!m_config.deterministic_input.enabled)
                return true;
            const uint32_t correction =
                m_config.deterministic_input.correction_start;
            if (frame + 1u < correction || frame > correction + 40u)
                return true;

            ++m_status.fixture_move_samples;
            for (size_t slot = 0; slot < 2; ++slot)
            {
                uint8_t native_slot = 0;
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        fighters[slot] + 0x23C), &native_slot,
                        sizeof(native_slot)) || native_slot >= 8)
                    return false;

                uint32_t move_index = 0;
                if (!SafeReadUInt32(reinterpret_cast<const void*>(
                        m_image_base + 0x4711A18
                            + static_cast<uintptr_t>(native_slot) * 0x3038),
                        &move_index))
                    return false;

                if (frame + 1u == correction)
                    m_status.fixture_pre_action_move_index[slot] = move_index;
                if (frame == correction)
                    m_status.fixture_action_move_index[slot] = move_index;
                if (frame >= correction
                    && move_index
                        != m_status.fixture_pre_action_move_index[slot])
                {
                    ++m_status.fixture_action_move_changes[slot];
                }

                void* active_cell = nullptr;
                if (!SafeReadPtr(reinterpret_cast<const void*>(
                        fighters[slot] + 0x44058), &active_cell))
                    return false;
                if (frame >= correction && active_cell)
                {
                    if (m_status
                            .fixture_active_attack_cell_observations[slot]++
                        == 0)
                    {
                        m_status.fixture_first_active_attack_frame[slot] =
                            frame;
                    }
                }

                void* lane = nullptr;
                if (!SafeReadPtr(reinterpret_cast<const void*>(
                        fighters[slot] + 0x44068), &lane))
                    return false;
                if (lane)
                {
                    if (!SafeReadInt16(static_cast<const uint8_t*>(lane) + 2,
                            &m_status.fixture_last_packed_move[slot])
                        || !SafeReadFloat(
                            static_cast<const uint8_t*>(lane) + 8,
                            &m_status.fixture_last_move_anim_frame[slot]))
                        return false;
                }
            }
            return true;
        }

        static bool read_audio_owner_from_shared_player(
            uintptr_t shared_player, uintptr_t& owner) noexcept
        {
            owner = 0;
            uint64_t runtime_handle = 0;
            uintptr_t active_map_state = 0;
            return shared_player != 0
                && SafeReadBytes(reinterpret_cast<const void*>(shared_player),
                    &owner, sizeof(owner))
                && owner != 0
                && SafeReadUInt64(reinterpret_cast<const void*>(owner),
                    &runtime_handle)
                && runtime_handle != 0
                && SafeReadBytes(reinterpret_cast<const void*>(owner + 0x38),
                    &active_map_state, sizeof(active_map_state))
                && active_map_state != 0;
        }

        static bool read_battle_audio_player_identity(
            uintptr_t pair_address,
            RollbackProductionAudioOwnerGraph::BattlePlayerIdentity& identity)
            noexcept
        {
            identity = {};
            if (!pair_address
                || !SafeReadBytes(reinterpret_cast<const void*>(pair_address),
                    &identity.shared_player, sizeof(identity.shared_player))
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        pair_address + 8),
                    &identity.reference_controller,
                    sizeof(identity.reference_controller)))
                return false;
            if (identity.shared_player == 0)
                return identity.reference_controller == 0;
            return read_audio_owner_from_shared_player(
                identity.shared_player, identity.owner);
        }

        bool capture_audio_manager_owner_graph(
            uint64_t epoch,
            uintptr_t battle_manager,
            RollbackProductionAudioOwnerGraph& graph) const noexcept
        {
            graph = {};
            if (epoch == 0 || m_image_base == 0) return false;
            uintptr_t manager = 0;
            uintptr_t bgm_state = 0;
            uintptr_t active_context = 0;
            if (!SafeReadBytes(reinterpret_cast<const void*>(m_image_base
                        + kRollbackProductionRvaCriAtomManagerSingletonSlot),
                    &manager, sizeof(manager))
                || manager == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(manager + 0x90),
                    &bgm_state, sizeof(bgm_state))
                || !SafeReadBytes(reinterpret_cast<const void*>(manager + 0xA0),
                    &active_context, sizeof(active_context))
                || bgm_state == 0 || active_context == 0)
                return false;

            uintptr_t bgm_pairs = 0;
            int32_t bgm_pair_count = 0;
            if (!SafeReadBytes(reinterpret_cast<const void*>(bgm_state),
                    &bgm_pairs, sizeof(bgm_pairs))
                || !SafeReadInt32(reinterpret_cast<const void*>(bgm_state + 8),
                    &bgm_pair_count)
                || bgm_pairs == 0 || bgm_pair_count < 2
                || bgm_pair_count > 16)
                return false;

            std::array<uintptr_t, 6> owners {};
            for (size_t lane = 0; lane < 2; ++lane)
            {
                uintptr_t shared_player = 0;
                if (!SafeReadBytes(reinterpret_cast<const void*>(bgm_pairs
                            + lane * 0x10),
                        &shared_player, sizeof(shared_player))
                    || !read_audio_owner_from_shared_player(
                        shared_player, owners[lane]))
                    return false;
            }
            uintptr_t jingle_player = 0;
            uintptr_t active_se_player = 0;
            uintptr_t active_voice_player = 0;
            RollbackProductionAudioOwnerGraph::BattlePlayerIdentity
                bgm_direct {};
            if (!SafeReadBytes(reinterpret_cast<const void*>(bgm_state + 0x10),
                    &jingle_player, sizeof(jingle_player))
                || !read_battle_audio_player_identity(
                    bgm_state + 0x60, bgm_direct)
                || bgm_direct.owner == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(active_context),
                    &active_se_player, sizeof(active_se_player))
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        active_context + 0x10),
                    &active_voice_player, sizeof(active_voice_player))
                || !read_audio_owner_from_shared_player(
                    jingle_player, owners[2])
                || !read_audio_owner_from_shared_player(
                    active_se_player, owners[3])
                || !read_audio_owner_from_shared_player(
                    active_voice_player, owners[4]))
                return false;
            owners[5] = bgm_direct.owner;
            for (size_t i = 0; i < owners.size(); ++i)
                for (size_t j = i + 1; j < owners.size(); ++j)
                    if (owners[i] == owners[j]) return false;

            // GetBattleManagerFromWorldContext consumers dereference the
            // current simulation battle manager's +0x520 audio-manager
            // pointer. ALuxBattleManagerAudioState_Partial then owns the
            // dynamic ref-pair array/count at +0x400/+0x408 and the distinct
            // direct shared player at +0x420 (Ghidra 0x140519480).
            uintptr_t battle_audio_manager = 0;
            uintptr_t battle_entries = 0;
            int32_t battle_count = 0;
            if (battle_manager == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        battle_manager + 0x520),
                    &battle_audio_manager, sizeof(battle_audio_manager))
                || battle_audio_manager == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        battle_audio_manager + 0x400),
                    &battle_entries, sizeof(battle_entries))
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        battle_audio_manager + 0x408), &battle_count)
                || battle_count < 0
                || battle_count > kRollbackAudioBattlePlayerMaximum
                || (battle_count != 0 && battle_entries == 0))
                return false;

            std::array<RollbackProductionAudioOwnerGraph::
                BattlePlayerIdentity,
                kRollbackAudioBattlePlayerMaximum> battle_players {};
            for (int32_t index = 0; index < battle_count; ++index)
            {
                if (!read_battle_audio_player_identity(
                        battle_entries + static_cast<uintptr_t>(index) * 0x10,
                        battle_players[static_cast<size_t>(index)]))
                    return false;
            }
            RollbackProductionAudioOwnerGraph::BattlePlayerIdentity
                battle_shared {};
            // The +0x420 direct path stores only a shared-player pointer, not
            // a ref-pair. Capture its owner and leave the controller identity
            // zero by construction.
            if (!SafeReadBytes(reinterpret_cast<const void*>(
                    battle_audio_manager + 0x420),
                    &battle_shared.shared_player,
                    sizeof(battle_shared.shared_player))
                || battle_shared.shared_player == 0
                || !read_audio_owner_from_shared_player(
                    battle_shared.shared_player, battle_shared.owner))
                return false;

            graph.epoch = epoch;
            graph.manager = manager;
            graph.bgm_state = bgm_state;
            graph.active_context = active_context;
            graph.bgm_lane_owner = {owners[0], owners[1]};
            graph.bgm_direct_player = bgm_direct;
            graph.jingle_owner = owners[2];
            graph.active_se_owner = owners[3];
            graph.active_voice_owner = owners[4];
            graph.battle_manager = battle_manager;
            graph.battle_audio_manager = battle_audio_manager;
            graph.battle_player_entries = battle_entries;
            graph.battle_player_count = static_cast<uint32_t>(battle_count);
            graph.battle_players = battle_players;
            graph.battle_shared_player = battle_shared;
            graph.valid = true;
            return true;
        }

        bool prepare_audio_manager_owner_graph(
            uint64_t epoch, uintptr_t battle_manager) noexcept
        {
            RollbackProductionAudioOwnerGraph graph {};
            bool ready = capture_audio_manager_owner_graph(
                    epoch, battle_manager, graph)
                && m_audio_owner_resolver.begin_epoch(epoch);
            std::array<uintptr_t,
                kRollbackAudioBattlePlayerMaximum + 7> bound_owners {};
            size_t bound_count = 0;
            const auto bind_unique = [&](uintptr_t owner,
                const RollbackAudioOwnerSelector& selector) noexcept -> bool {
                if (!owner) return false;
                for (size_t i = 0; i < bound_count; ++i)
                    if (bound_owners[i] == owner) return true;
                if (bound_count >= bound_owners.size()
                    || !m_audio_owner_resolver.bind(epoch, owner, selector))
                    return false;
                bound_owners[bound_count++] = owner;
                return true;
            };
            ready = ready
                && bind_unique(graph.bgm_lane_owner[0], {
                    RollbackAudioOwnerDomain::BgmLane, 0, 0})
                && bind_unique(graph.bgm_lane_owner[1], {
                    RollbackAudioOwnerDomain::BgmLane, 1, 0})
                && bind_unique(graph.bgm_direct_player.owner, {
                    RollbackAudioOwnerDomain::BgmDirect, 0, 0})
                && bind_unique(graph.jingle_owner, {
                    RollbackAudioOwnerDomain::Jingle, 0, 0})
                && bind_unique(graph.active_se_owner, {
                    RollbackAudioOwnerDomain::ActiveContextSe, 0, 0})
                && bind_unique(graph.active_voice_owner, {
                    RollbackAudioOwnerDomain::ActiveContextVoice, 0, 0});
            if (ready)
            {
                for (uint32_t index = 0;
                     index < graph.battle_player_count; ++index)
                {
                    const uintptr_t owner =
                        graph.battle_players[index].owner;
                    if (owner != 0
                        && !bind_unique(owner, {
                            RollbackAudioOwnerDomain::BattleClassPlayer,
                            static_cast<uint8_t>(index), 0}))
                    {
                        ready = false;
                        break;
                    }
                }
            }
            ready = ready
                && bind_unique(graph.battle_shared_player.owner, {
                    RollbackAudioOwnerDomain::BattleSharedPlayer, 0, 0})
                && m_audio_owner_resolver.seal(epoch)
                && m_audio_playback_map.begin_epoch(epoch);
            if (!ready)
            {
                m_audio_owner_resolver.revoke();
                m_audio_playback_map.revoke();
                m_audio_owner_graph = {};
                return false;
            }
            m_audio_owner_graph = graph;
            return true;
        }

        bool validate_audio_manager_owner_graph(uint64_t epoch) const noexcept
        {
            RollbackProductionAudioOwnerGraph live {};
            return m_audio_owner_graph.valid
                && m_audio_owner_graph.epoch == epoch
                && capture_audio_manager_owner_graph(epoch,
                    m_audio_owner_graph.battle_manager, live)
                && m_audio_owner_graph.same_identity(live);
        }

        void revoke_audio_terminal_epoch() noexcept
        {
            m_audio_owner_resolver.revoke();
            m_audio_playback_map.revoke();
            m_audio_owner_graph = {};
            m_audio_create_ordinal = 0;
            revoke_vfx_terminal_epoch();
        }

        bool capture_vfx_subsystem_identity(
            uint64_t epoch,
            uintptr_t battle_manager,
            const std::array<uintptr_t, 2>& fighter,
            RollbackProductionVfxSubsystemIdentity& identity) const
            noexcept
        {
            identity = {};
            uintptr_t subsystem = 0;
            uintptr_t vtable = 0;
            uintptr_t normalizer_external = 0;
            int32_t normalizer_count = 0;
            uint64_t normalizer_digest = 0;
            int32_t next_slot_id = -1;
            uintptr_t primary_slots = 0;
            int32_t primary_count = 0;
            int32_t primary_capacity = 0;
            uintptr_t debris_slots = 0;
            int32_t debris_count = 0;
            int32_t debris_capacity = 0;
            std::array<uintptr_t, 2> weapon_mesh {};
            std::array<uintptr_t, 2> weapon_mesh_vtable {};
            if (epoch == 0 || battle_manager == 0
                || fighter[0] == 0 || fighter[1] == 0
                || fighter[0] == fighter[1]
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        battle_manager + 0x508),
                    &subsystem, sizeof(subsystem))
                || subsystem == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(subsystem),
                    &vtable, sizeof(vtable))
                || vtable == 0
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        subsystem + 0x3C0),
                    &normalizer_external, sizeof(normalizer_external))
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x3D0), &normalizer_count)
                || normalizer_count < 0 || normalizer_count > 4
                || (normalizer_count > 2 && normalizer_external == 0)
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x3E0), &next_slot_id)
                || next_slot_id < 0 || next_slot_id >= 0x40000000
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        subsystem + 0x3E8),
                    &primary_slots, sizeof(primary_slots))
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x3F0), &primary_count)
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x3F4), &primary_capacity)
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        subsystem + 0x3F8),
                    &debris_slots, sizeof(debris_slots))
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x400), &debris_count)
                || !SafeReadInt32(reinterpret_cast<const void*>(
                        subsystem + 0x404), &debris_capacity)
                || primary_count < 0 || primary_capacity < primary_count
                || primary_capacity > 0x10000
                || debris_count < 0 || debris_capacity < debris_count
                || debris_capacity > 0x10000
                || (primary_count > 0 && primary_slots == 0)
                || (debris_count > 0 && debris_slots == 0))
                return false;
            if (normalizer_count > 0)
            {
                std::array<uint8_t, 64> normalizer {};
                const uintptr_t normalizer_data = normalizer_external != 0
                    ? normalizer_external : subsystem + 0x3A0;
                const size_t normalizer_bytes =
                    static_cast<size_t>(normalizer_count) * 0x10;
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        normalizer_data), normalizer.data(),
                    normalizer_bytes))
                    return false;
                RollbackHash hash {};
                hash.add_bytes(normalizer.data(), normalizer_bytes);
                normalizer_digest = hash.value ? hash.value : 1;
            }
            for (size_t role = 0; role < fighter.size(); ++role)
            {
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        fighter[role] + 0x390),
                    &weapon_mesh[role], sizeof(weapon_mesh[role]))
                    || weapon_mesh[role] == 0
                    || !SafeReadBytes(reinterpret_cast<const void*>(
                        weapon_mesh[role]), &weapon_mesh_vtable[role],
                        sizeof(weapon_mesh_vtable[role]))
                    || weapon_mesh_vtable[role] == 0)
                    return false;
            }
            if (weapon_mesh[0] == weapon_mesh[1]) return false;

            identity.epoch = epoch;
            identity.battle_manager = battle_manager;
            identity.subsystem = subsystem;
            identity.vtable = vtable;
            identity.normalizer_external = normalizer_external;
            identity.normalizer_count = normalizer_count;
            identity.normalizer_digest = normalizer_digest;
            identity.fighter = fighter;
            identity.weapon_mesh = weapon_mesh;
            identity.weapon_mesh_vtable = weapon_mesh_vtable;
            identity.valid = true;
            return true;
        }

        bool prepare_vfx_subsystem_identity(
            uint64_t epoch, uintptr_t battle_manager,
            const std::array<uintptr_t, 2>& fighter) noexcept
        {
            RollbackProductionVfxSubsystemIdentity identity {};
            if (!capture_vfx_subsystem_identity(
                    epoch, battle_manager, fighter, identity)
                || !m_vfx_slot_shadow.begin_epoch(epoch))
            {
                m_vfx_slot_shadow.revoke();
                m_vfx_subsystem_identity = {};
                m_vfx_create_ordinal = 0;
                return false;
            }
            m_vfx_subsystem_identity = identity;
            if (!seed_vfx_slot_shadow(epoch))
            {
                m_vfx_slot_shadow.revoke();
                m_vfx_subsystem_identity = {};
                m_vfx_create_ordinal = 0;
                return false;
            }
            m_vfx_create_ordinal = 0;
            return true;
        }

        bool validate_vfx_subsystem_identity(uint64_t epoch) const noexcept
        {
            RollbackProductionVfxSubsystemIdentity live {};
            return m_vfx_subsystem_identity.valid
                && m_vfx_subsystem_identity.epoch == epoch
                && capture_vfx_subsystem_identity(epoch,
                    m_vfx_subsystem_identity.battle_manager,
                    m_vfx_subsystem_identity.fighter, live)
                && m_vfx_subsystem_identity.same_identity(live);
        }

        bool capture_vfx_world_spawn_invocation(
            const std::array<uint8_t, 0xB0>& request,
            uint32_t logical_id,
            RollbackVfxWorldSpawnInvocation& invocation) const noexcept
        {
            std::array<uint8_t, 0xB0> sanitized = request;
            RollbackVfxAttachmentSelector attachment {};
            uintptr_t attachment_component = 0;
            uint64_t attachment_name = 0;
            uintptr_t provider_heap = 0;
            int32_t provider_count = 0;
            std::memcpy(&attachment_component, request.data() + 0x58, 8);
            std::memcpy(&attachment_name, request.data() + 0x60, 8);
            std::memcpy(&provider_heap, request.data() + 0x90, 8);
            std::memcpy(&provider_count, request.data() + 0xA0, 4);

            if (attachment_component != 0)
            {
                if (provider_count != 0 || provider_heap != 0)
                    return false;
                uint8_t role = kRollbackVfxNoCharacterRole;
                for (uint8_t candidate = 0; candidate < 2; ++candidate)
                {
                    if (m_vfx_subsystem_identity.weapon_mesh[candidate]
                            != attachment_component)
                        continue;
                    if (role != kRollbackVfxNoCharacterRole) return false;
                    role = candidate;
                }
                int32_t attachment_index = -1;
                std::memcpy(&attachment_index, request.data() + 0x50, 4);
                if (role >= 2
                    || attachment_index != role || attachment_name == 0)
                    return false;
                uint32_t socket_selector = 0;
                for (uint32_t low = 0x17; low <= 0x1F; ++low)
                {
                    uint64_t candidate_name = 0;
                    const uint32_t candidate_selector = 0x8000u | low;
                    if (!reinterpret_cast<GetFrontEdgeSocketNameFn>(
                            m_image_base
                                + kRollbackProductionRvaGetFrontEdgeSocketName)(
                            0, &candidate_name, candidate_selector))
                        return false;
                    if (candidate_name != attachment_name) continue;
                    if (socket_selector != 0) return false;
                    socket_selector = candidate_selector;
                }
                if (socket_selector == 0) return false;
                attachment.kind =
                    RollbackVfxAttachmentKind::WeaponFrontEdge;
                attachment.character_role = role;
                attachment.selector = socket_selector;
            }
            else if (provider_count != 0 || provider_heap != 0)
            {
                if (provider_count != 3 || provider_heap == 0)
                    return false;
                std::array<uint8_t, 0x30> payload {};
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        provider_heap), payload.data(), payload.size()))
                    return false;
                uintptr_t provider_vtable = 0;
                uintptr_t callback = 0;
                uint64_t sequence = 0;
                std::memcpy(&provider_vtable, payload.data(), 8);
                std::memcpy(&callback, payload.data() + 0x10, 8);
                std::memcpy(&sequence, payload.data() + 0x20, 8);
                if (sequence == 0) return false;
                RC::Unreal::FWeakObjectPtr weak {};
                std::memcpy(&weak, payload.data() + 8, sizeof(weak));
                const uintptr_t weak_object =
                    reinterpret_cast<uintptr_t>(weak.Get());
                uint8_t role = kRollbackVfxNoCharacterRole;
                for (uint8_t candidate = 0; candidate < 2; ++candidate)
                {
                    if (m_vfx_subsystem_identity.fighter[candidate]
                            != weak_object)
                        continue;
                    if (role != kRollbackVfxNoCharacterRole) return false;
                    role = candidate;
                }
                if (role >= 2) return false;
                if (provider_vtable == m_image_base
                        + kRollbackProductionRvaBoneProviderCompletedVtable
                    && callback == m_image_base
                        + kRollbackProductionRvaBonePoseTransformCallback)
                {
                    uint32_t pose_selector = 0;
                    uint32_t bone_index = 0;
                    std::memcpy(&pose_selector, payload.data() + 0x18, 4);
                    std::memcpy(&bone_index, payload.data() + 0x1C, 4);
                    if (bone_index >= kRollbackVfxSkeletonBoneCount)
                        return false;
                    uint64_t expected_name = 0;
                    if (reinterpret_cast<GetSkeletonBoneNameFn>(
                            m_image_base
                                + kRollbackProductionRvaGetSkeletonBoneName)(
                            &expected_name, bone_index) == nullptr
                        || expected_name != attachment_name)
                        return false;
                    attachment.kind =
                        RollbackVfxAttachmentKind::SkeletonBone;
                    attachment.character_role = role;
                    attachment.selector = bone_index;
                    attachment.pose_selector = pose_selector;
                }
                else if (provider_vtable == m_image_base
                            + kRollbackProductionRvaChestProviderCompletedVtable
                    && callback == m_image_base
                            + kRollbackProductionRvaChestMidpointTransformCallback
                    && attachment_name == 0)
                {
                    attachment.kind =
                        RollbackVfxAttachmentKind::PlayersChestMidpoint;
                    attachment.character_role = role;
                }
                else
                {
                    return false;
                }
            }
            else if (attachment_name != 0)
            {
                return false;
            }

            std::fill(sanitized.begin() + 0x58,
                sanitized.begin() + 0x68, 0);
            std::fill(sanitized.begin() + 0x70,
                sanitized.end(), 0);
            return CaptureRollbackVfxWorldSpawnInvocation(
                sanitized, logical_id, invocation, attachment);
        }

        bool rebuild_vfx_world_spawn_request(
            const RollbackVfxWorldSpawnInvocation& invocation,
            std::array<uint8_t, 0xB0>& request) const noexcept
        {
            if (!RebuildRollbackVfxWorldSpawnRequest(invocation, request))
                return false;
            const RollbackVfxAttachmentSelector& attachment =
                invocation.attachment;
            if (attachment.kind == RollbackVfxAttachmentKind::None)
                return true;
            if (attachment.character_role >= 2) return false;
            const uintptr_t fighter = m_vfx_subsystem_identity.fighter[
                attachment.character_role];
            if (fighter == 0) return false;
            if (attachment.kind
                    == RollbackVfxAttachmentKind::WeaponFrontEdge)
            {
                const uintptr_t weapon =
                    m_vfx_subsystem_identity.weapon_mesh[
                        attachment.character_role];
                if (weapon == 0
                    || !reinterpret_cast<GetFrontEdgeSocketNameFn>(
                        m_image_base
                            + kRollbackProductionRvaGetFrontEdgeSocketName)(
                        0, request.data() + 0x60,
                        attachment.selector))
                    return false;
                std::memcpy(request.data() + 0x58, &weapon, 8);
                return true;
            }
            if (attachment.kind
                    == RollbackVfxAttachmentKind::SkeletonBone)
            {
                if (reinterpret_cast<GetSkeletonBoneNameFn>(m_image_base
                        + kRollbackProductionRvaGetSkeletonBoneName)(
                        request.data() + 0x60,
                        attachment.selector) == nullptr)
                    return false;
                reinterpret_cast<AssignBonePoseTransformProviderFn>(
                    m_image_base
                        + kRollbackProductionRvaAssignBonePoseTransformProvider)(
                    request.data() + 0x70, fighter,
                    m_image_base
                        + kRollbackProductionRvaBonePoseTransformCallback,
                    attachment.pose_selector, attachment.selector);
                return true;
            }
            if (attachment.kind
                    == RollbackVfxAttachmentKind::PlayersChestMidpoint)
            {
                reinterpret_cast<AssignChestMidpointTransformProviderFn>(
                    m_image_base
                        + kRollbackProductionRvaAssignChestMidpointTransformProvider)(
                    request.data() + 0x70, fighter,
                    m_image_base
                        + kRollbackProductionRvaChestMidpointTransformCallback);
                return true;
            }
            return false;
        }

        bool destroy_rebuilt_vfx_provider(
            std::array<uint8_t, 0xB0>& request) const noexcept
        {
            uintptr_t heap = 0;
            int32_t count = 0;
            std::memcpy(&heap, request.data() + 0x90, 8);
            std::memcpy(&count, request.data() + 0xA0, 4);
            if (count == 0) return heap == 0;
            if (count != 3 || heap == 0
                || m_fmemory_free_trampoline == 0)
                return false;
            uintptr_t vtable = 0;
            uintptr_t destroy = 0;
            if (!SafeReadBytes(reinterpret_cast<const void*>(heap),
                    &vtable, sizeof(vtable))
                || (vtable != m_image_base
                        + kRollbackProductionRvaBoneProviderCompletedVtable
                    && vtable != m_image_base
                        + kRollbackProductionRvaChestProviderCompletedVtable)
                || !SafeReadBytes(reinterpret_cast<const void*>(
                        vtable + 0x48), &destroy, sizeof(destroy))
                || destroy == 0)
                return false;
            reinterpret_cast<void(__fastcall*)(void*, uint8_t)>(destroy)(
                reinterpret_cast<void*>(heap), 0);
            reinterpret_cast<void(__fastcall*)(void*)>(
                m_fmemory_free_trampoline)(reinterpret_cast<void*>(heap));
            std::fill(request.begin() + 0x70, request.end(), 0);
            return true;
        }

        bool find_live_vfx_slot(
            int32_t native_id,
            RollbackVfxSlotKind& kind,
            int32_t& index,
            uintptr_t& actor,
            uintptr_t& actor_vtable) const noexcept
        {
            kind = RollbackVfxSlotKind::PrimaryParticle;
            index = -1;
            actor = 0;
            actor_vtable = 0;
            if (!RollbackVfxNativeSlotId(native_id)
                || !m_vfx_subsystem_identity.valid)
                return false;
            const uintptr_t subsystem = m_vfx_subsystem_identity.subsystem;
            bool found = false;
            for (uint8_t table = 0; table < 2; ++table)
            {
                uintptr_t records = 0;
                int32_t count = 0;
                const uintptr_t header = subsystem
                    + (table == 0 ? 0x3E8 : 0x3F8);
                if (!SafeReadBytes(reinterpret_cast<const void*>(header),
                        &records, sizeof(records))
                    || !SafeReadInt32(reinterpret_cast<const void*>(
                            header + 8), &count)
                    || count < 0 || count > 0x10000
                    || (count > 0 && records == 0))
                    return false;
                for (int32_t candidate = 0; candidate < count; ++candidate)
                {
                    const uintptr_t record = records
                        + static_cast<uintptr_t>(candidate) * 0xC0;
                    int32_t slot_id = -1;
                    if (!SafeReadInt32(reinterpret_cast<const void*>(
                            record + 8), &slot_id))
                        return false;
                    if (slot_id != native_id) continue;
                    if (found
                        || !SafeReadBytes(reinterpret_cast<const void*>(
                                record), &actor, sizeof(actor))
                        || actor == 0
                        || !SafeReadBytes(reinterpret_cast<const void*>(
                                actor), &actor_vtable,
                            sizeof(actor_vtable))
                        || actor_vtable == 0)
                        return false;
                    found = true;
                    kind = table == 0
                        ? RollbackVfxSlotKind::PrimaryParticle
                        : RollbackVfxSlotKind::SecondaryGroundDebris;
                    index = candidate;
                }
            }
            return found;
        }

        bool seed_vfx_slot_shadow(uint64_t epoch) noexcept
        {
            if (!m_vfx_subsystem_identity.valid
                || m_vfx_subsystem_identity.epoch != epoch)
                return false;
            const uintptr_t subsystem = m_vfx_subsystem_identity.subsystem;
            std::array<int32_t, 512> native_ids {};
            size_t seeded = 0;
            for (uint8_t table = 0; table < 2; ++table)
            {
                uintptr_t records = 0;
                int32_t count = 0;
                const uintptr_t header = subsystem
                    + (table == 0 ? 0x3E8 : 0x3F8);
                if (!SafeReadBytes(reinterpret_cast<const void*>(header),
                        &records, sizeof(records))
                    || !SafeReadInt32(reinterpret_cast<const void*>(
                            header + 8), &count)
                    || count < 0 || count > 512
                    || seeded + static_cast<size_t>(count)
                        > native_ids.size()
                    || (count > 0 && records == 0))
                    return false;
                for (int32_t index = 0; index < count; ++index)
                {
                    const uintptr_t record = records
                        + static_cast<uintptr_t>(index) * 0xC0;
                    std::array<uint8_t, 0xC0> bytes {};
                    if (!SafeReadBytes(reinterpret_cast<const void*>(record),
                            bytes.data(), bytes.size()))
                        return false;
                    uintptr_t actor = 0;
                    int32_t native_id = -1;
                    std::memcpy(&actor, bytes.data(), 8);
                    std::memcpy(&native_id, bytes.data() + 8, 4);
                    if (actor == 0 || !RollbackVfxNativeSlotId(native_id))
                        return false;
                    uintptr_t actor_vtable = 0;
                    if (!SafeReadBytes(reinterpret_cast<const void*>(actor),
                            &actor_vtable, sizeof(actor_vtable))
                        || actor_vtable == 0)
                        return false;
                    for (size_t prior = 0; prior < seeded; ++prior)
                        if (native_ids[prior] == native_id) return false;
                    native_ids[seeded] = native_id;
                    RollbackVfxSlotKey key {};
                    std::memcpy(&key.effect_id, bytes.data() + 0x10, 4);
                    key.kind_tag = bytes[0x14];
                    std::memcpy(&key.kind_arg, bytes.data() + 0x18, 4);
                    std::memcpy(&key.group, bytes.data() + 0x1C, 4);
                    std::memcpy(&key.variant, bytes.data() + 0x20, 4);
                    key.id_wildcard_guard = bytes[0x7F] != 0;
                    const uint32_t logical_id =
                        MakeRollbackVfxBaselineLogicalSlotId(
                            static_cast<uint32_t>(seeded));
                    const RollbackVfxSlotKind kind = table == 0
                        ? RollbackVfxSlotKind::PrimaryParticle
                        : RollbackVfxSlotKind::SecondaryGroundDebris;
                    if (!m_vfx_slot_shadow.reserve_create(epoch,
                            logical_id, kind, key, {}, 0)
                        || !m_vfx_slot_shadow.complete_create(epoch,
                            logical_id, native_id, kind))
                        return false;
                    ++seeded;
                }
            }
            return true;
        }

        bool commit_vfx_logical_terminal(
            uint64_t epoch,
            const RollbackVfxTerminalInvocation& invocation) noexcept
        {
            if (!invocation.valid()
                || !validate_vfx_subsystem_identity(epoch))
                return false;
            int32_t native_id = -1;
            if (!m_vfx_slot_shadow.resolve_native(
                    epoch, invocation.logical_slot_id, native_id))
                return false;
            RollbackVfxSlotKind kind {};
            int32_t index = -1;
            uintptr_t actor = 0;
            uintptr_t actor_vtable = 0;
            if (!find_live_vfx_slot(native_id, kind, index,
                    actor, actor_vtable))
                return false;
            const auto* shadow =
                m_vfx_slot_shadow.lookup(invocation.logical_slot_id);
            if (!shadow || shadow->kind != kind)
                return false;
            const auto executable = [&](uintptr_t address) noexcept {
                MEMORY_BASIC_INFORMATION memory {};
                return address != 0
                    && VirtualQuery(reinterpret_cast<const void*>(address),
                        &memory, sizeof(memory)) == sizeof(memory)
                    && memory.AllocationBase
                        == reinterpret_cast<const void*>(m_image_base)
                    && (memory.Protect
                        & (PAGE_EXECUTE | PAGE_EXECUTE_READ
                            | PAGE_EXECUTE_READWRITE
                            | PAGE_EXECUTE_WRITECOPY)) != 0;
            };
            if (invocation.terminal == RollbackVfxPendingTerminal::Remove)
            {
                uintptr_t deactivate = 0;
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        actor_vtable + 0x360), &deactivate,
                    sizeof(deactivate)) || !executable(deactivate))
                    return false;
                reinterpret_cast<void(__fastcall*)(uintptr_t, uint8_t)>(
                    deactivate)(actor, 0);
                reinterpret_cast<DispatchVfxWeakSlotCallbacksFn>(
                    m_image_base
                        + kRollbackProductionRvaDispatchVfxWeakSlotCallbacks)(
                    m_vfx_subsystem_identity.subsystem + 0x388,
                    &native_id);
                const uintptr_t header = m_vfx_subsystem_identity.subsystem
                    + (kind == RollbackVfxSlotKind::PrimaryParticle
                        ? 0x3E8 : 0x3F8);
                reinterpret_cast<RemoveLiveMeshActorSlotRangeFn>(
                    m_image_base
                        + kRollbackProductionRvaRemoveLiveMeshActorSlotRange)(
                    header, index, 1,
                    kind == RollbackVfxSlotKind::PrimaryParticle);
            }
            else if (kind == RollbackVfxSlotKind::PrimaryParticle)
            {
                uintptr_t soft_disable = 0;
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        actor_vtable + 0x238), &soft_disable,
                    sizeof(soft_disable)) || !executable(soft_disable))
                    return false;
                reinterpret_cast<void(__fastcall*)(uintptr_t)>(
                    soft_disable)(actor);
            }
            else
            {
                MEMORY_BASIC_INFORMATION memory {};
                const uintptr_t last_write = actor + 0xA10 + 4;
                if (VirtualQuery(reinterpret_cast<const void*>(actor),
                        &memory, sizeof(memory)) != sizeof(memory)
                    || memory.State != MEM_COMMIT
                    || reinterpret_cast<uintptr_t>(memory.BaseAddress)
                        > actor
                    || reinterpret_cast<uintptr_t>(memory.BaseAddress)
                            + memory.RegionSize < last_write
                    || (memory.Protect
                        & (PAGE_READWRITE | PAGE_WRITECOPY
                            | PAGE_EXECUTE_READWRITE
                            | PAGE_EXECUTE_WRITECOPY)) == 0)
                    return false;
                uint8_t state = 0;
                float fade_clock = 0.0f;
                uint32_t current_time = 0;
                if (!SafeReadBytes(reinterpret_cast<const void*>(
                        actor + 0x830), &state, sizeof(state))
                    || !SafeReadFloat(reinterpret_cast<const void*>(
                        actor + 0x93C), &fade_clock)
                    || !SafeReadUInt32(reinterpret_cast<const void*>(
                        actor + 0xA04), &current_time))
                    return false;
                if (static_cast<uint8_t>(state - 3u) > 1u)
                {
                    const uint8_t enabled = 1;
                    if (!SafeWriteUInt32(reinterpret_cast<void*>(
                            actor + 0x87C), current_time)
                        || !SafeWriteBytes(reinterpret_cast<void*>(
                            actor + 0x878), &enabled, sizeof(enabled))
                        || !SafeWriteUInt32(reinterpret_cast<void*>(
                            actor + 0x880), 0))
                        return false;
                }
                if (fade_clock <= 0.0f && fade_clock != 0.0f)
                {
                    if (!SafeWriteUInt32(reinterpret_cast<void*>(
                            actor + 0x93C), current_time)
                        || !SafeWriteUInt32(reinterpret_cast<void*>(
                            actor + 0x938), 0))
                        return false;
                }
                constexpr uint32_t kNegativeOneFloatBits = 0xBF800000u;
                if (!SafeWriteUInt32(reinterpret_cast<void*>(
                        actor + 0xA0C), kNegativeOneFloatBits)
                    || !SafeWriteUInt32(reinterpret_cast<void*>(
                        actor + 0xA10), kNegativeOneFloatBits))
                    return false;
            }
            return m_vfx_slot_shadow.finalize_terminal(
                epoch, invocation.logical_slot_id,
                invocation.terminal);
        }

        bool commit_vfx_manager_invocation(
            uint64_t epoch,
            const RollbackVfxManagerInvocation& invocation) noexcept
        {
            if (!invocation.valid()
                || !validate_vfx_subsystem_identity(epoch))
                return false;
            const uintptr_t manager = m_vfx_subsystem_identity.subsystem;
            if (invocation.operation
                == RollbackVfxManagerOperation::SetGroupTimeDilation)
            {
                int32_t group_count = 0;
                if (m_vfx_set_group_time_dilation_trampoline == 0
                    || !SafeReadInt32(reinterpret_cast<const void*>(
                        manager + 0x470), &group_count)
                    || invocation.group >= group_count)
                    return false;
                reinterpret_cast<SetVfxGroupTimeDilationFn>(
                    m_vfx_set_group_time_dilation_trampoline)(
                        manager, invocation.group,
                        invocation.time_dilation);
                return true;
            }
            if (invocation.operation
                == RollbackVfxManagerOperation::SetHiddenFilter)
            {
                if (m_vfx_set_hidden_filter_trampoline == 0)
                    return false;
                std::array<uint8_t, 12> filter {};
                filter[0] = invocation.filter_kind_tag;
                std::memcpy(filter.data() + 4,
                    &invocation.filter_group, sizeof(int32_t));
                std::memcpy(filter.data() + 8,
                    &invocation.filter_variant, sizeof(int32_t));
                reinterpret_cast<SetVfxHiddenFilterFn>(
                    m_vfx_set_hidden_filter_trampoline)(
                        manager, filter.data(), invocation.hidden != 0);
                return true;
            }
            if (invocation.operation
                == RollbackVfxManagerOperation::ClearHiddenFilters)
            {
                if (m_vfx_clear_hidden_filters_trampoline == 0)
                    return false;
                reinterpret_cast<ClearVfxHiddenFiltersFn>(
                    m_vfx_clear_hidden_filters_trampoline)(manager);
                return true;
            }
            return false;
        }

        void revoke_vfx_terminal_epoch() noexcept
        {
            m_vfx_slot_shadow.revoke();
            m_vfx_subsystem_identity = {};
            m_vfx_create_ordinal = 0;
        }

        bool queue_side_effect_at_current_frame(
            RollbackSideEffectType type,
            const void* payload,
            uint16_t bytes,
            uint8_t lane) noexcept
        {
            if (!m_accept_effects.load(std::memory_order_acquire)
                || !m_current_frame.valid
                || m_manifest.epoch.generation == 0
                || static_cast<size_t>(type)
                    >= kRollbackSideEffectTypeCount
                || lane >= kRollbackSideEffectLaneCount)
                return false;
            if (m_simulation_thread_id == 0
                || GetCurrentThreadId() != m_simulation_thread_id)
            {
                fail_closed("presentation-capture-off-simulation-thread");
                return false;
            }
            const uint32_t ordinal = m_effect_ordinals.next(type, lane);
            if (ordinal == ~uint32_t {0}) return false;
            const uint64_t key = ComputeRollbackSideEffectIdentityKey(
                type, lane, payload, bytes, ordinal);
            const bool queued = m_ledger.enqueue(
                m_manifest.epoch.generation, m_current_frame.value,
                type, key, payload, bytes, lane, 0);
            if (queued)
                mark_coverage(
                    RollbackCoverageCapabilityId::PresentationDispatch);
            update_presentation_status();
            return queued;
        }

        bool queue_side_effect(
            RollbackSideEffectType type,
            const void* payload,
            uint16_t bytes,
            uint8_t lane = 0,
            bool fixture_replay = false) noexcept
        {
            // The narrow native-correction diagnostic still samples transition
            // state for fixture distance and input evidence, but presentation
            // interception is intentionally outside that gate.
            if (RollbackNativeCorrectionBypassesSideEffectLedger(
                    m_config.native_correction_only, type))
                return true;
            if (!m_accept_effects || !m_effect_frame.valid)
                return false;
            const size_t type_index = static_cast<size_t>(type);
            if (type_index >= kRollbackSideEffectTypeCount
                || lane >= kRollbackSideEffectLaneCount)
                return false;
            if (m_simulation_thread_id == 0
                || GetCurrentThreadId() != m_simulation_thread_id)
            {
                fail_closed("presentation-capture-off-simulation-thread");
                return false;
            }
            const uint64_t key = ComputeRollbackSideEffectIdentityKey(
                type, lane, payload, bytes,
                m_effect_ordinals.next(type, lane));
            const RollbackResimContext& resim =
                CurrentRollbackResimContext();
            const bool fixture_provenance =
                m_fixture_effect_witness.state().valid
                && m_fixture_effect_witness.state().epoch == m_effect_epoch
                && RollbackFixtureEvidenceFrame(
                    m_config.deterministic_input, m_effect_frame.value)
                && (fixture_replay
                    || (resim.active && resim.epoch == m_effect_epoch
                        && resim.frame == m_effect_frame.value));
            const uint32_t fixture_generation = fixture_provenance
                ? m_config.deterministic_input.fixture_id : 0u;
            const uint64_t queued_before = m_ledger.report().queued;
            const bool queued = m_ledger.enqueue(
                m_effect_epoch, m_effect_frame.value,
                type, key, payload, bytes, lane, fixture_generation);
            const bool inserted = queued
                && m_ledger.report().queued == queued_before + 1u;
            if (queued)
            {
                mark_coverage(
                    RollbackCoverageCapabilityId::PresentationDispatch);
                if (type == RollbackSideEffectType::Camera)
                    mark_coverage(
                        RollbackCoverageCapabilityId::HistoricalCamera);
            }
            if (inserted && fixture_generation != 0)
            {
                size_t index = 4;
                switch (type)
                {
                case RollbackSideEffectType::Audio: index = 0; break;
                case RollbackSideEffectType::Vfx: index = 1; break;
                case RollbackSideEffectType::Camera: index = 2; break;
                case RollbackSideEffectType::ConfirmedTransition:
                    index = 3;
                    break;
                default: break;
                }
                if (index < std::size(
                        m_status.fixture_replayed_effect_frame))
                {
                    if (!m_status.fixture_replayed_effect_seen[index])
                    {
                        m_status.fixture_replayed_effect_seen[index] = true;
                        m_status.fixture_replayed_effect_frame[index] =
                            m_effect_frame.value;
                    }
                }
            }
            update_presentation_status();
            return queued;
        }

        bool capture_and_queue_transitions(
            uint32_t frame, bool rolling_back) noexcept
        {
            RollbackProductionTransitionFrame current {};
            current.epoch = m_manifest.epoch.generation;
            current.frame = frame;
            current.valid = true;
            uintptr_t fighters[2] {};
            if (!accepted_fighter_pointers(fighters[0], fighters[1]))
                return false;

            float position[2][2] {};
            if (!SafeReadFloat(reinterpret_cast<const void*>(
                    fighters[0] + 0xA0), &position[0][0])
                || !SafeReadFloat(reinterpret_cast<const void*>(
                    fighters[0] + 0xA8), &position[0][1])
                || !SafeReadFloat(reinterpret_cast<const void*>(
                    fighters[1] + 0xA0), &position[1][0])
                || !SafeReadFloat(reinterpret_cast<const void*>(
                    fighters[1] + 0xA8), &position[1][1]))
            {
                fail_closed("transition-position-read-failed");
                return false;
            }
            const float delta_x = position[0][0] - position[1][0];
            const float delta_z = position[0][1] - position[1][1];
            const float opponent_distance = std::hypot(delta_x, delta_z);
            if (!std::isfinite(opponent_distance))
            {
                fail_closed("transition-position-invalid");
                return false;
            }
            const bool sample_fixture_distance =
                m_config.deterministic_input.enabled
                && frame >= kRollbackFixtureApproachUpdates;
            if (sample_fixture_distance
                && !m_status.fixture_distance_valid)
            {
                m_status.fixture_distance_valid = true;
                m_status.fixture_initial_distance = opponent_distance;
                m_status.fixture_minimum_distance = opponent_distance;
                m_status.fixture_minimum_distance_frame = frame;
            }
            else if (sample_fixture_distance
                && opponent_distance < m_status.fixture_minimum_distance)
            {
                m_status.fixture_minimum_distance = opponent_distance;
                m_status.fixture_minimum_distance_frame = frame;
            }
            if (m_config.deterministic_input.enabled
                && !m_status.fixture_action_distance_valid
                && frame >= RollbackFixturePreCorrectionActionStart(
                        m_config.deterministic_input))
            {
                m_status.fixture_action_distance_valid = true;
                m_status.fixture_action_distance = opponent_distance;
            }

            int16_t round_result = 0;
            if (!SafeReadInt16(reinterpret_cast<const void*>(
                    m_image_base + 0x4846408), &round_result))
            {
                fail_closed("transition-round-result-read-failed");
                return false;
            }
            for (size_t slot = 0; slot < 2; ++slot)
            {
                auto& state = current.fighter[slot];
                const auto* fighter = reinterpret_cast<const uint8_t*>(
                    fighters[slot]);
                state.chara_slot = static_cast<uint8_t>(slot);
                state.round_result = round_result;
                if (!SafeReadInt32(fighter + 0x43DA0,
                        &state.hit_result))
                    return fail_transition_read("transition-hit-read-failed");
                if (!SafeReadFloat(fighter + 0x43E08,
                        &state.vital_candidate))
                    return fail_transition_read("transition-vital-read-failed");
                if (!SafeReadFloat(fighter + 0x43E14,
                        &state.vital_displayed))
                    return fail_transition_read(
                        "transition-vital-display-read-failed");
                if (!SafeReadUInt32(fighter + 0x43E18,
                        &state.vital_category_bits))
                    return fail_transition_read(
                        "transition-vital-category-read-failed");
                if (!SafeReadInt16(fighter + 0x3D0,
                        &state.vital_state))
                    return fail_transition_read(
                        "transition-vital-state-read-failed");
                if (!SafeReadUInt16(fighter + 0x1314,
                        &state.round_wins))
                    return fail_transition_read(
                        "transition-round-wins-read-failed");
            }

            RollbackProductionTransitionFrame previous {};
            bool previous_valid = false;
            if (frame != 0)
            {
                previous = m_transition_history[
                    (frame - 1u) & kRollbackProductionFrameHistoryMask];
                previous_valid = previous.valid
                    && previous.epoch == current.epoch
                    && previous.frame == frame - 1u;
            }
            m_transition_history[
                frame & kRollbackProductionFrameHistoryMask] = current;
            if (!previous_valid)
            {
                if (!m_confirmed_round_transition_pending)
                    return true;
                auto event = current.fighter[0];
                event.flags = RollbackTransitionRound;
                m_last_advance_round_transition_observed = true;
                if (!queue_side_effect(
                        RollbackSideEffectType::ConfirmedTransition,
                        &event, sizeof(event)))
                {
                    if (m_status.state != RollbackProductionState::Fatal)
                        fail_closed("round-transition-journal-enqueue-failed");
                    return false;
                }
                // Frame 0 cannot be rolled back behind. The ledger still
                // commits this at the normal contiguous confirmation frontier.
                m_confirmed_round_transition_pending = false;
                return true;
            }

            for (size_t slot = 0; slot < 2; ++slot)
            {
                auto event = current.fighter[slot];
                const auto& before = previous.fighter[slot];
                event.flags = 0;
                if (event.hit_result != before.hit_result
                    || event.vital_state != before.vital_state
                    || event.vital_category_bits
                        != before.vital_category_bits)
                {
                    event.flags |= RollbackTransitionHit;
                }
                if (std::memcmp(&event.vital_candidate,
                        &before.vital_candidate, sizeof(float)) != 0)
                    event.flags |= RollbackTransitionDamage;
                if (std::memcmp(&event.vital_displayed,
                        &before.vital_displayed, sizeof(float)) != 0)
                    event.flags |= RollbackTransitionMeter;
                if (event.round_wins != before.round_wins
                    || event.round_result != before.round_result)
                {
                    event.flags |= RollbackTransitionRound;
                }
                if (event.flags != 0
                    && !queue_side_effect(
                        RollbackSideEffectType::ConfirmedTransition,
                        &event, sizeof(event), 0, rolling_back))
                {
                    if (m_status.state != RollbackProductionState::Fatal)
                        fail_closed("transition-journal-enqueue-failed");
                    return false;
                }
                if ((event.flags & RollbackTransitionRound) != 0)
                    m_last_advance_round_transition_observed = true;
            }
            return true;
        }

        bool fail_transition_read(const char* reason) noexcept
        {
            fail_closed(reason);
            return false;
        }

        void update_presentation_status() noexcept
        {
            const RollbackSideEffectLedgerReport& report = m_ledger.report();
            m_status.presentation_queued = report.queued;
            m_status.presentation_duplicates_suppressed = report.duplicates;
            m_status.presentation_discarded = report.discarded;
            m_status.presentation_committed = report.committed;
            const size_t audio = static_cast<size_t>(
                RollbackSideEffectType::Audio);
            const size_t vfx = static_cast<size_t>(
                RollbackSideEffectType::Vfx);
            const size_t camera = static_cast<size_t>(
                RollbackSideEffectType::Camera);
            const size_t transition = static_cast<size_t>(
                RollbackSideEffectType::ConfirmedTransition);
            m_status.audio_effects_queued = report.queued_by_type[audio];
            m_status.audio_effects_discarded =
                report.discarded_by_type[audio];
            m_status.audio_effects_committed =
                report.committed_by_type[audio];
            m_status.audio_effects_committed_digest =
                report.committed_digest_by_type[audio];
            m_status.vfx_effects_queued = report.queued_by_type[vfx];
            m_status.vfx_effects_discarded =
                report.discarded_by_type[vfx];
            m_status.vfx_effects_committed =
                report.committed_by_type[vfx];
            m_status.vfx_effects_committed_digest =
                report.committed_digest_by_type[vfx];
            for (size_t route = 0; route < kRollbackVfxRouteCount; ++route)
            {
                m_status.vfx_route_queued[route] =
                    report.queued_by_lane[vfx][route];
                m_status.vfx_route_committed[route] =
                    report.committed_by_lane[vfx][route];
                m_status.vfx_route_committed_digest[route] =
                    report.committed_digest_by_lane[vfx][route];
            }
            m_status.camera_effects_queued = report.queued_by_type[camera];
            m_status.camera_effects_discarded =
                report.discarded_by_type[camera];
            m_status.camera_effects_committed =
                report.committed_by_type[camera];
            m_status.camera_effects_committed_digest =
                report.committed_digest_by_type[camera];
            m_status.transitions_queued = report.queued_by_type[transition];
            m_status.transitions_discarded =
                report.discarded_by_type[transition];
            m_status.transitions_committed =
                report.committed_by_type[transition];
            m_status.transitions_committed_digest =
                report.committed_digest_by_type[transition];
            const bool stage_exactly_once =
                m_status.stage_breakable_actor_count == 0
                || (m_status.stage_reconciliation_committed
                        <= m_status.stage_reconciliation_queued
                    && m_status.stage_reconciliation_discarded == 0
                    && m_status.stage_reconciliation_digest != 0);
            bool vfx_routes_valid = true;
            for (size_t route = 0;
                 route < kRollbackVfxRouteCount; ++route)
            {
                vfx_routes_valid = vfx_routes_valid
                    && m_status.vfx_route_committed[route]
                        <= m_status.vfx_route_queued[route];
            }
            // This is deliberately an accounting invariant, not proof that a
            // stock-equivalent presentation happened exactly once. The event
            // hub and upstream audio adapters are source-time passthroughs.
            m_status.presentation_accounting_consistent = report.ok
                && vfx_routes_valid
                && report.committed <= report.queued
                && m_status.model_reconciliation_committed
                    <= m_status.model_reconciliation_queued
                && m_status.model_reconciliation_discarded == 0
                && stage_exactly_once;
        }

        bool capture_presentation_checkpoint(uint32_t confirmed) noexcept
        {
            if (m_pending_presentation_checkpoint.valid
                || m_pair_epoch == 0)
            {
                return false;
            }
            RollbackProductionPresentationCheckpoint checkpoint {};
            if (!m_ledger.project_confirmed_through(
                    m_manifest.epoch.generation,
                    confirmed, checkpoint.ledger))
            {
                return false;
            }
            checkpoint.valid = true;
            checkpoint.round_generation = m_round_generation;
            checkpoint.round_ordinal =
                m_manifest.epoch.round_ordinal & 0xFFFFu;
            checkpoint.round_epoch = m_pair_epoch;
            checkpoint.fixture_evidence_start_frame =
                RollbackFixtureEvidenceStartFrame(
                    m_config.deterministic_input);
            checkpoint.fixture_evidence_end_frame =
                RollbackFixtureEvidenceEndFrame(
                    m_config.deterministic_input);
            checkpoint.fixture_checkpoint_frame =
                RollbackFixtureCheckpointFrame(
                    m_config.deterministic_input);
            checkpoint.fixture_correction_load_frame =
                m_status.fixture_correction_load_frame;
            checkpoint.fixture_load_candidates =
                m_status.fixture_load_candidates;
            checkpoint.fixture_load_promotions =
                m_status.fixture_load_promotions;
            checkpoint.fixture_load_rejections =
                m_status.fixture_load_rejections;
            std::copy(std::begin(m_status.fixture_discarded_effect_frame),
                std::end(m_status.fixture_discarded_effect_frame),
                checkpoint.fixture_discarded_effect_frame.begin());
            std::copy(std::begin(m_status.fixture_replayed_effect_frame),
                std::end(m_status.fixture_replayed_effect_frame),
                checkpoint.fixture_replayed_effect_frame.begin());
            std::copy(std::begin(m_status.fixture_discarded_effect_seen),
                std::end(m_status.fixture_discarded_effect_seen),
                checkpoint.fixture_discarded_effect_seen.begin());
            std::copy(std::begin(m_status.fixture_replayed_effect_seen),
                std::end(m_status.fixture_replayed_effect_seen),
                checkpoint.fixture_replayed_effect_seen.begin());
            checkpoint.fixture_witness = m_fixture_effect_witness.state();
            const size_t vfx = static_cast<size_t>(
                RollbackSideEffectType::Vfx);
            for (size_t route = 0; route < kRollbackVfxRouteCount; ++route)
            {
                checkpoint.vfx_route_queued[route] =
                    checkpoint.ledger.queued_by_lane[vfx][route];
                checkpoint.vfx_route_committed[route] =
                    checkpoint.ledger.committed_by_lane[vfx][route];
                checkpoint.vfx_route_committed_digest[route] =
                    checkpoint.ledger.committed_digest_by_lane[vfx][route];
            }
            m_pending_presentation_checkpoint = checkpoint;
            return true;
        }

        void emit_presentation_checkpoint(uint32_t confirmed) noexcept
        {
            auto& checkpoint = m_pending_presentation_checkpoint;
            if (!checkpoint.valid
                || (confirmed != checkpoint.ledger.frame
                    && RollbackFrameIsBefore(
                        confirmed, checkpoint.ledger.frame)))
            {
                return;
            }
            if (m_status.state != RollbackProductionState::Active)
                return;
            if (checkpoint.round_epoch != m_pair_epoch
                || checkpoint.round_generation != m_round_generation
                || checkpoint.round_ordinal
                    != (m_manifest.epoch.round_ordinal & 0xFFFFu))
            {
                fail_closed("presentation-checkpoint-lifecycle-mismatch");
                return;
            }
            const auto& baseline = m_presentation_round_baseline;
            checkpoint.model_reconciliation_queued =
                m_status.model_reconciliation_queued - baseline.model_queued;
            checkpoint.model_reconciliation_discarded =
                m_status.model_reconciliation_discarded
                - baseline.model_discarded;
            checkpoint.model_reconciliation_committed =
                m_status.model_reconciliation_committed
                - baseline.model_committed;
            checkpoint.model_reconciliation_after_load =
                m_status.loads > baseline.loads
                && checkpoint.model_reconciliation_committed != 0;
            checkpoint.stage_reconciliation_queued =
                m_status.stage_reconciliation_queued - baseline.stage_queued;
            checkpoint.stage_reconciliation_discarded =
                m_status.stage_reconciliation_discarded
                - baseline.stage_discarded;
            checkpoint.stage_reconciliation_committed =
                m_status.stage_reconciliation_committed
                - baseline.stage_committed;
            checkpoint.stage_reconciliation_digest =
                m_status.stage_reconciliation_digest;
            checkpoint.stage_breakable_actor_count =
                m_status.stage_breakable_actor_count;
            checkpoint.stage_reconciliation_after_load =
                m_status.loads > baseline.loads
                && (checkpoint.stage_reconciliation_committed != 0
                    || checkpoint.stage_breakable_actor_count == 0);
            checkpoint.presentation_root_publish_valid =
                m_status.presentation_root_publish_valid;
            checkpoint.presentation_accounting_consistent =
                m_status.presentation_accounting_consistent;
            checkpoint.fixture_packets_held =
                m_status.fixture_packets_held
                - baseline.fixture_packets_held;
            checkpoint.fixture_packets_released =
                m_status.fixture_packets_released
                - baseline.fixture_packets_released;
            checkpoint.fixture_delay_sender =
                checkpoint.fixture_packets_held != 0;
            static constexpr const char* kQueuedFields[] = {
                "audio_effects_queued", "vfx_effects_queued",
                "camera_effects_queued", "transitions_queued",
            };
            static constexpr const char* kDiscardedFields[] = {
                "audio_effects_discarded", "vfx_effects_discarded",
                "camera_effects_discarded", "transitions_discarded",
            };
            static constexpr const char* kCommittedFields[] = {
                "audio_effects_committed", "vfx_effects_committed",
                "camera_effects_committed", "transitions_committed",
            };
            static constexpr const char* kDigestFields[] = {
                "audio_effects_committed_digest",
                "vfx_effects_committed_digest",
                "camera_effects_committed_digest",
                "transitions_committed_digest",
            };
            static constexpr const char* kFixtureDiscardedFields[] = {
                "fixture_discarded_audio_frame",
                "fixture_discarded_vfx_frame",
                "fixture_discarded_camera_frame",
                "fixture_discarded_transition_frame",
            };
            static constexpr const char* kFixtureReplayedFields[] = {
                "fixture_replayed_audio_frame",
                "fixture_replayed_vfx_frame",
                "fixture_replayed_camera_frame",
                "fixture_replayed_transition_frame",
            };
            static constexpr const char* kFixtureDiscardedSeenFields[] = {
                "fixture_discarded_audio_seen",
                "fixture_discarded_vfx_seen",
                "fixture_discarded_camera_seen",
                "fixture_discarded_transition_seen",
            };
            static constexpr const char* kFixtureReplayedSeenFields[] = {
                "fixture_replayed_audio_seen",
                "fixture_replayed_vfx_seen",
                "fixture_replayed_camera_seen",
                "fixture_replayed_transition_seen",
            };
            static constexpr const char* kFixtureDiscardedCountFields[] = {
                "fixture_discarded_audio_count",
                "fixture_discarded_vfx_count",
                "fixture_discarded_camera_count",
                "fixture_discarded_transition_count",
            };
            static constexpr const char* kFixtureDiscardedDigestFields[] = {
                "fixture_discarded_audio_digest",
                "fixture_discarded_vfx_digest",
                "fixture_discarded_camera_digest",
                "fixture_discarded_transition_digest",
            };
            static constexpr const char* kFixtureTaggedQueuedFields[] = {
                "fixture_tagged_audio_queued",
                "fixture_tagged_vfx_queued",
                "fixture_tagged_camera_queued",
                "fixture_tagged_transition_queued",
            };
            static constexpr const char* kFixtureTaggedDiscardedFields[] = {
                "fixture_tagged_audio_discarded",
                "fixture_tagged_vfx_discarded",
                "fixture_tagged_camera_discarded",
                "fixture_tagged_transition_discarded",
            };
            static constexpr const char* kFixtureTaggedCommittedFields[] = {
                "fixture_tagged_audio_committed",
                "fixture_tagged_vfx_committed",
                "fixture_tagged_camera_committed",
                "fixture_tagged_transition_committed",
            };
            static constexpr const char* kFixtureTaggedDigestFields[] = {
                "fixture_tagged_audio_committed_digest",
                "fixture_tagged_vfx_committed_digest",
                "fixture_tagged_camera_committed_digest",
                "fixture_tagged_transition_committed_digest",
            };
            ReplayTraceFields fields;
            fields
                .string("request_id", m_config.request_id)
                .string("client_role", m_config.client_role)
                .uinteger("round_generation", checkpoint.round_generation)
                .uinteger("round_ordinal", checkpoint.round_ordinal)
                .hex("round_epoch", checkpoint.round_epoch)
                .uinteger("confirmed_frame", checkpoint.ledger.frame)
                .boolean("fixture_converged", true)
                .uinteger("fixture_evidence_start_frame",
                    checkpoint.fixture_evidence_start_frame)
                .uinteger("fixture_evidence_end_frame",
                    checkpoint.fixture_evidence_end_frame)
                .uinteger("fixture_checkpoint_frame",
                    checkpoint.fixture_checkpoint_frame)
                .uinteger("fixture_correction_load_frame",
                    checkpoint.fixture_correction_load_frame)
                .uinteger("fixture_load_candidates",
                    checkpoint.fixture_load_candidates)
                .uinteger("fixture_load_promotions",
                    checkpoint.fixture_load_promotions)
                .uinteger("fixture_load_rejections",
                    checkpoint.fixture_load_rejections)
                .uinteger("fixture_packets_held",
                    checkpoint.fixture_packets_held)
                .uinteger("fixture_packets_released",
                    checkpoint.fixture_packets_released)
                .boolean("fixture_delay_sender",
                    checkpoint.fixture_delay_sender)
                .boolean("fixture_requires_all_effect_types",
                    !m_config.replay_input.enabled)
                .boolean("fixture_witness_valid",
                    checkpoint.fixture_witness.valid)
                .uinteger("fixture_witness_load_frame",
                    checkpoint.fixture_witness.load_frame);
            for (size_t type = 0; type < std::size(kQueuedFields); ++type)
            {
                fields
                    .uinteger(kQueuedFields[type],
                        checkpoint.ledger.queued_by_type[type])
                    .uinteger(kDiscardedFields[type],
                        checkpoint.ledger.discarded_by_type[type])
                    .uinteger(kCommittedFields[type],
                        checkpoint.ledger.committed_by_type[type])
                    .hex(kDigestFields[type],
                        checkpoint.ledger.committed_digest_by_type[type])
                    .uinteger(kFixtureDiscardedFields[type],
                        checkpoint.fixture_discarded_effect_frame[type])
                    .uinteger(kFixtureReplayedFields[type],
                        checkpoint.fixture_replayed_effect_frame[type])
                    .boolean(kFixtureDiscardedSeenFields[type],
                        checkpoint.fixture_discarded_effect_seen[type])
                    .boolean(kFixtureReplayedSeenFields[type],
                        checkpoint.fixture_replayed_effect_seen[type])
                    .uinteger(kFixtureDiscardedCountFields[type],
                        checkpoint.fixture_witness.discarded_count[type])
                    .hex(kFixtureDiscardedDigestFields[type],
                        checkpoint.fixture_witness.discarded_digest[type])
                    .uinteger(kFixtureTaggedQueuedFields[type],
                        checkpoint.ledger.fixture_queued_by_type[type])
                    .uinteger(kFixtureTaggedDiscardedFields[type],
                        checkpoint.ledger.fixture_discarded_by_type[type])
                    .uinteger(kFixtureTaggedCommittedFields[type],
                        checkpoint.ledger.fixture_committed_by_type[type])
                    .hex(kFixtureTaggedDigestFields[type],
                        checkpoint.ledger
                            .fixture_committed_digest_by_type[type]);
            }
            for (size_t route = 0;
                 route < kRollbackVfxRouteCount; ++route)
            {
                char queued_key[40] {};
                char committed_key[40] {};
                char digest_key[48] {};
                const uint16_t offset =
                    kRollbackVfxRoutes[route].vtable_offset;
                if (!FormatRollbackVfxRouteTraceKey(
                        queued_key, sizeof(queued_key), offset, "queued")
                    || !FormatRollbackVfxRouteTraceKey(
                        committed_key, sizeof(committed_key), offset,
                        "committed")
                    || !FormatRollbackVfxRouteTraceKey(
                        digest_key, sizeof(digest_key), offset,
                        "committed_digest"))
                {
                    fail_closed("vfx-route-trace-key-invalid");
                    m_pending_presentation_checkpoint = {};
                    return;
                }
                fields
                    .uinteger(queued_key,
                        checkpoint.vfx_route_queued[route])
                    .uinteger(committed_key,
                        checkpoint.vfx_route_committed[route])
                    .hex(digest_key,
                        checkpoint.vfx_route_committed_digest[route]);
            }
            fields
                .uinteger("model_reconciliation_queued",
                    checkpoint.model_reconciliation_queued)
                .uinteger("model_reconciliation_discarded",
                    checkpoint.model_reconciliation_discarded)
                .uinteger("model_reconciliation_committed",
                    checkpoint.model_reconciliation_committed)
                .boolean("model_reconciliation_after_load",
                    checkpoint.model_reconciliation_after_load)
                .uinteger("stage_reconciliation_queued",
                    checkpoint.stage_reconciliation_queued)
                .uinteger("stage_reconciliation_discarded",
                    checkpoint.stage_reconciliation_discarded)
                .uinteger("stage_reconciliation_committed",
                    checkpoint.stage_reconciliation_committed)
                .hex("stage_reconciliation_digest",
                    checkpoint.stage_reconciliation_digest)
                .uinteger("stage_breakable_actor_count",
                    checkpoint.stage_breakable_actor_count)
                .boolean("stage_reconciliation_after_load",
                    checkpoint.stage_reconciliation_after_load)
                .boolean("presentation_root_publish_valid",
                    checkpoint.presentation_root_publish_valid)
                .boolean("presentation_accounting_consistent",
                    checkpoint.presentation_accounting_consistent);
            ReplayDebugTrace::instance().event(
                "rollback_presentation_confirmed_checkpoint", fields);
            m_pending_presentation_checkpoint = {};
        }

        static bool finite_presentation_transform(
            const NativeFTransform48& transform) noexcept
        {
            const float* values = transform.rotation;
            for (size_t index = 0; index < 12; ++index)
                if (!std::isfinite(values[index])) return false;
            return true;
        }

        static float quaternion_yaw_turns(
            const NativeFTransform48& transform) noexcept
        {
            const float x = transform.rotation[0];
            const float y = transform.rotation[1];
            const float z = transform.rotation[2];
            const float w = transform.rotation[3];
            const float sin_yaw = 2.0f * (w * z + x * y);
            const float cos_yaw = 1.0f - 2.0f * (y * y + z * z);
            constexpr float kTwoPi = 6.28318530717958647692f;
            return std::atan2(sin_yaw, cos_yaw) / kTwoPi;
        }

        bool reconcile_confirmed_breakable_presentation(
            uint32_t frame) noexcept
        {
            m_status.stage_reconciliation_failure = "ok";
            const auto* confirmed = m_stage_presentation_history.find(
                m_manifest.epoch.generation, frame);
            if (!confirmed)
            {
                m_status.stage_reconciliation_failure =
                    "confirmed-presentation-frame-missing";
                return false;
            }
            if (!m_stage_reconciliation_pending
                && m_last_confirmed_stage_hash
                    == confirmed->canonical_hash)
            {
                return true;
            }
            if (confirmed->stage_layout_digest
                    != m_stage_identity.stage_layout_digest
                || confirmed->actor_set_digest
                    != m_stage_identity.actor_set_digest
                || confirmed->count != m_stage_identity.records.size())
            {
                m_status.stage_reconciliation_failure =
                    "confirmed-presentation-identity-mismatch";
                return false;
            }
            if (confirmed->count == 0)
            {
                m_status.stage_reconciliation_digest = 0;
                m_stage_reconciliation_pending = false;
                m_last_confirmed_stage_hash = confirmed->canonical_hash;
                return true;
            }

            using WallVisibilityFn = void(__fastcall*)(void*);
            using SceneVisibilityFn = void(__fastcall*)(void*, uint8_t, uint8_t);
            const auto wall_visibility = reinterpret_cast<WallVisibilityFn>(
                m_image_base
                    + kRollbackProductionRvaSetStageBreakableWallVisibility);
            const auto scene_visibility = reinterpret_cast<SceneVisibilityFn>(
                m_image_base + kRollbackProductionRvaSetSceneVisibility);
            RollbackHash digest {};
            for (size_t i = 0; i < confirmed->count; ++i)
            {
                const RollbackBreakablePresentationValue& value =
                    confirmed->values[i];
                const RollbackBreakableStageRecord& identity =
                    m_stage_identity.records[i];
                ++m_status.stage_reconciliation_queued;
                if (!identity.actor)
                {
                    ++m_status.stage_reconciliation_discarded;
                    m_status.stage_reconciliation_failure =
                        "confirmed-presentation-actor-missing";
                    return false;
                }
                digest.add_scalar(static_cast<uint8_t>(identity.kind));
                digest.add_scalar(identity.id);
                digest.add_scalar(identity.ordinal);
                digest.add_scalar(value.scalar);
                digest.add_scalar(value.endurance);
                digest.add_scalar(value.fade_timer);
                digest.add_scalar(value.fade_rate);
                if (identity.kind == RollbackBreakableActorKind::Wall)
                {
                    // Ghidra: SetStageBreakableWallVisibilityFromState is a
                    // pure native reconciler. It reads only the restored
                    // +0x468/+0x46C/+0x470 state and the six component slots.
                    wall_visibility(reinterpret_cast<void*>(identity.actor));
                }
                else
                {
                    uintptr_t face = 0;
                    uintptr_t back = 0;
                    uintptr_t breaking = 0;
                    if (!SafeReadBytes(reinterpret_cast<const void*>(
                            identity.actor + kRollbackStageBarrierFaceOffset),
                            &face, sizeof(face))
                        || !SafeReadBytes(reinterpret_cast<const void*>(
                            identity.actor + kRollbackStageBarrierBackOffset),
                            &back, sizeof(back))
                        || !SafeReadBytes(reinterpret_cast<const void*>(
                            identity.actor
                                + kRollbackStageBarrierBreakingOffset),
                            &breaking, sizeof(breaking)))
                    {
                        ++m_status.stage_reconciliation_discarded;
                        m_status.stage_reconciliation_failure =
                            "confirmed-barrier-component-read-failed";
                        return false;
                    }
                    const RollbackBarrierPresentationVisibility visibility =
                        ComputeRollbackBarrierPresentationVisibility(
                            value.scalar, value.endurance);
                    if (!visibility.valid)
                    {
                        ++m_status.stage_reconciliation_discarded;
                        m_status.stage_reconciliation_failure =
                            "confirmed-barrier-state-invalid";
                        return false;
                    }
                    if (face) scene_visibility(
                        reinterpret_cast<void*>(face),
                        static_cast<uint8_t>(visibility.face_visible), 1);
                    if (back) scene_visibility(
                        reinterpret_cast<void*>(back),
                        static_cast<uint8_t>(visibility.back_visible), 1);
                    if (breaking) scene_visibility(
                        reinterpret_cast<void*>(breaking),
                        static_cast<uint8_t>(visibility.breaking_visible), 1);
                }
                ++m_status.stage_reconciliation_committed;
            }
            m_status.stage_reconciliation_digest =
                digest.value ? digest.value : 1;
            mark_coverage(
                RollbackCoverageCapabilityId::BreakablePresentation);
            if (m_stage_reconciliation_pending && m_status.loads != 0)
                m_status.stage_reconciliation_after_load = true;
            m_stage_reconciliation_pending = false;
            m_last_confirmed_stage_hash = confirmed->canonical_hash;
            return true;
        }

        bool reconcile_confirmed_presentation(uint32_t frame) noexcept
        {
            if (m_last_model_reconciliation_frame.valid
                && m_last_model_reconciliation_frame.value == frame
                && !m_model_reconciliation_pending)
                return true;
            uintptr_t simulation[2] {};
            if (!accepted_fighter_pointers(
                    simulation[0], simulation[1]))
            {
                return false;
            }

            for (size_t slot = 0; slot < 2; ++slot)
            {
                ++m_status.model_reconciliation_queued;
                auto& state = m_status.presentation_slot[slot];
                const float previous_x = state.actor_x;
                const float previous_y = state.actor_y;
                const float previous_z = state.actor_z;
                const bool had_previous = state.update_serial != 0;
                NativeFTransform48 transform {};
                NativePresentationPublishReport publish {};
                const bool published =
                    NativeBinding::publishCharaPresentationTransform(
                        reinterpret_cast<void*>(m_presentation_actors[slot]),
                        transform, &publish);
                const bool finite = finite_presentation_transform(transform);
                state.actor_bound = true;
                state.actor_identity_valid = publish.identity_valid;
                state.actor = publish.actor;
                state.root_component = publish.root_component;
                state.actor_x = transform.translation[0];
                state.actor_y = transform.translation[1];
                state.actor_z = transform.translation[2];
                state.actor_facing_turns = quaternion_yaw_turns(transform);
                state.root_transform_finite = finite;
                state.actor_transform_changed = had_previous
                    && (std::fabs(previous_x - state.actor_x) > 0.01f
                        || std::fabs(previous_y - state.actor_y) > 0.01f
                        || std::fabs(previous_z - state.actor_z) > 0.01f);
                state.reconciliation_ok = published && finite
                    && publish.identity_valid
                    && publish.getter_called && publish.setter_called
                    && publish.setter_returned_true && !publish.exception;
                if (!state.reconciliation_ok)
                {
                    m_status.presentation_root_publish_valid = false;
                    ++m_status.model_reconciliation_discarded;
                    return false;
                }
                ++state.update_serial;
                state.last_reconciled_epoch = m_manifest.epoch.generation;
                state.last_reconciled_frame = frame;
                ++m_status.model_reconciliation_committed;
            }
            if (m_status.loads != 0)
                m_status.model_reconciliation_after_load = true;
            m_last_model_reconciliation_frame = frame;
            return true;
        }

        static bool commit_side_effect(
            const RollbackSideEffectEvent& event,
            void* context) noexcept
        {
            auto* runtime = static_cast<RollbackProductionRuntime*>(context);
            if (!runtime) return false;
            if (runtime->m_simulation_thread_id == 0
                || GetCurrentThreadId()
                    != runtime->m_simulation_thread_id)
            {
                runtime->fail_closed(
                    "presentation-commit-off-simulation-thread");
                return false;
            }
            runtime->m_committing_effect = true;
            bool committed = false;
            if (event.type == RollbackSideEffectType::Audio
                && event.lane == kRollbackProductionAudioTerminalLane
                && event.payload_bytes
                    == sizeof(RollbackProductionAudioInvocation))
            {
                RollbackProductionAudioInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                uintptr_t owner = 0;
                uint64_t runtime_handle = 0;
                const bool owner_ok = invocation.valid()
                    && event.epoch == runtime->m_manifest.epoch.generation
                    && runtime->validate_audio_manager_owner_graph(
                        event.epoch)
                    && runtime->m_audio_owner_resolver.resolve_owner(
                        event.epoch, invocation.owner, owner)
                    && owner != 0
                    && SafeReadUInt64(reinterpret_cast<const void*>(owner),
                        &runtime_handle)
                    && runtime_handle != 0
                    && runtime->m_audio_register_active_voice_trampoline != 0
                    && runtime->m_audio_append_stop_voice_trampoline != 0
                    && runtime->m_audio_append_stop_all_trampoline != 0
                    && runtime->m_audio_append_named_parameter_trampoline != 0;
                if (!owner_ok)
                {
                    runtime->fail_closed(
                        "confirmed-audio-owner-identity-mismatch");
                }
                else if (invocation.operation
                    == RollbackAudioOperation::Create)
                {
                    const uint32_t native_id =
                        reinterpret_cast<RegisterActiveVoiceFn>(
                            runtime->m_audio_register_active_voice_trampoline)(
                                owner, invocation.cue_sheet_id,
                                invocation.cue_id,
                                invocation.playback_flags);
                    committed = RollbackAudioNativePlaybackId(native_id)
                        && runtime->m_audio_playback_map.complete_create(
                            event.epoch, invocation.logical_playback_id,
                            native_id);
                    if (!committed)
                        runtime->fail_closed(
                            "confirmed-audio-create-terminal-failed");
                }
                else if (invocation.operation
                    == RollbackAudioOperation::StopOne)
                {
                    uint32_t native_id = invocation.logical_playback_id;
                    const bool logical = RollbackAudioLogicalPlaybackId(
                        invocation.logical_playback_id);
                    const bool mapped = !logical
                        || runtime->m_audio_playback_map.resolve_stop(
                            event.epoch, invocation.owner,
                            invocation.logical_playback_id, native_id);
                    if (mapped && RollbackAudioNativePlaybackId(native_id)
                        && runtime->m_audio_append_stop_voice_trampoline != 0)
                    {
                        reinterpret_cast<AppendStopVoiceFn>(
                            runtime->m_audio_append_stop_voice_trampoline)(
                                owner, native_id,
                                static_cast<uint8_t>(
                                    invocation.playback_flags != 0));
                        committed = !logical
                            || runtime->m_audio_playback_map.retire_one(
                                event.epoch, invocation.owner,
                                invocation.logical_playback_id);
                    }
                    if (!committed)
                        runtime->fail_closed(
                            "confirmed-audio-stop-one-terminal-failed");
                }
                else if (invocation.operation
                    == RollbackAudioOperation::StopAll)
                {
                    if (runtime->m_audio_append_stop_all_trampoline != 0)
                    {
                        reinterpret_cast<AppendStopAllVoicesFn>(
                            runtime->m_audio_append_stop_all_trampoline)(
                                owner, static_cast<uint8_t>(
                                    invocation.playback_flags != 0));
                        committed = runtime->m_audio_playback_map.retire_all(
                            event.epoch, invocation.owner);
                    }
                    if (!committed)
                        runtime->fail_closed(
                            "confirmed-audio-stop-all-terminal-failed");
                }
                else if (invocation.operation
                    == RollbackAudioOperation::SetParameter)
                {
                    const wchar_t* parameter_name =
                        rollback_audio_parameter_name(
                            invocation.cue_sheet_id);
                    float value = 0.0f;
                    std::memcpy(&value, &invocation.playback_flags,
                        sizeof(value));
                    if (parameter_name)
                    {
                        const int32_t count = static_cast<int32_t>(
                            std::wcslen(parameter_name) + 1u);
                        const NativeFStringView view {
                            parameter_name, count, count};
                        reinterpret_cast<AppendNamedAudioParameterFn>(
                            runtime->m_audio_append_named_parameter_trampoline)(
                                owner, &view, value);
                        committed = true;
                    }
                    if (!committed)
                        runtime->fail_closed(
                            "confirmed-audio-parameter-terminal-failed");
                }
            }
            else if (event.type == RollbackSideEffectType::Audio)
            {
                runtime->fail_closed(
                    "confirmed-audio-terminal-payload-invalid");
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionVfxWorldSpawnLane
                     && event.payload_bytes
                        == sizeof(RollbackVfxTerminalInvocation))
            {
                RollbackVfxTerminalInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                committed = event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->commit_vfx_logical_terminal(
                        event.epoch, invocation);
                if (!committed)
                    runtime->fail_closed(
                        "confirmed-vfx-logical-terminal-failed");
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionVfxWorldSpawnLane
                     && event.payload_bytes
                        == sizeof(RollbackVfxManagerInvocation))
            {
                RollbackVfxManagerInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                committed = event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->commit_vfx_manager_invocation(
                        event.epoch, invocation);
                if (!committed)
                    runtime->fail_closed(
                        "confirmed-vfx-manager-terminal-failed");
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionVfxWorldSpawnLane
                     && event.payload_bytes
                        == sizeof(RollbackVfxWorldSpawnInvocation))
            {
                RollbackVfxWorldSpawnInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                std::array<uint8_t, 0xB0> request {};
                const bool identity_ok = invocation.valid()
                    && event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->validate_vfx_subsystem_identity(event.epoch)
                    && runtime->m_vfx_lookup_allocate_trampoline != 0
                    && runtime->rebuild_vfx_world_spawn_request(
                        invocation, request);
                int32_t native_id = -1;
                bool provider_destroyed = false;
                RollbackVfxSlotKind native_kind =
                    RollbackVfxSlotKind::PrimaryParticle;
                int32_t native_index = -1;
                uintptr_t native_actor = 0;
                uintptr_t native_actor_vtable = 0;
                if (identity_ok)
                {
                    native_id =
                        reinterpret_cast<LookupOrAllocateMeshActorSlotFn>(
                            runtime->m_vfx_lookup_allocate_trampoline)(
                            runtime->m_vfx_subsystem_identity.subsystem,
                                request.data());
                    provider_destroyed =
                        runtime->destroy_rebuilt_vfx_provider(request);
                    committed = provider_destroyed
                        && RollbackVfxNativeSlotId(native_id)
                        && runtime->find_live_vfx_slot(native_id,
                            native_kind, native_index, native_actor,
                            native_actor_vtable)
                        && runtime->m_vfx_slot_shadow.complete_create(
                            event.epoch, invocation.logical_slot_id,
                            native_id, native_kind);
                }
                if (!committed)
                {
                    (void)runtime->m_vfx_slot_shadow.cancel_create(
                        event.epoch, invocation.logical_slot_id);
                    runtime->fail_closed(identity_ok
                        ? (provider_destroyed
                            ? "confirmed-vfx-world-spawn-terminal-failed"
                            : "confirmed-vfx-provider-destroy-failed")
                        : "confirmed-vfx-subsystem-identity-mismatch");
                }
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionCharaPresentationLane
                     && event.payload_bytes
                        == sizeof(RollbackCharaPresentationInvocation))
            {
                RollbackCharaPresentationInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                uintptr_t actor = 0;
                uint64_t trampoline = 0;
                if (invocation.valid()
                    && event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->m_presentation_semantic_identity
                        .well_formed()
                    && RollbackPresentationSemanticIdentityLive(
                        runtime->m_presentation_semantic_identity))
                {
                    actor = runtime->m_presentation_semantic_identity
                        .chara_owner[invocation.chara_role];
                    switch (invocation.operation)
                    {
                    case RollbackCharaPresentationOperation::SetupWeaponBones:
                        trampoline = runtime
                            ->m_chara_setup_weapon_bones_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::SetupWeaponActors:
                        trampoline = runtime
                            ->m_chara_setup_weapon_actors_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::
                            MovePhaseActiveLatch:
                        trampoline = runtime
                            ->m_chara_move_phase_latch_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::MovePhaseActive:
                        trampoline = runtime
                            ->m_chara_move_phase_active_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::SoulChargeState:
                        trampoline = runtime->m_chara_soul_charge_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::EffectColorFade:
                        trampoline = runtime->m_chara_color_fade_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::
                            ResetBreakAndAttackPresentation:
                        trampoline = runtime
                            ->m_chara_reset_presentation_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::PlayerVisibility:
                        trampoline = runtime->m_chara_visibility_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::WeaponNodeAlpha:
                        trampoline = runtime->m_chara_weapon_node_trampoline;
                        break;
                    case RollbackCharaPresentationOperation::MaterialChargeRate:
                        trampoline = runtime
                            ->m_chara_material_charge_trampoline;
                        break;
                    }
                }
                const void* value = invocation.value_bytes
                    ? invocation.value.data() : nullptr;
                committed = actor != 0 && trampoline != 0
                    && RollbackSafeInvokeCharaPresentationCallback(
                        reinterpret_cast<CharaPresentationCallbackFn>(
                            trampoline), actor, value);
                if (!committed)
                    runtime->fail_closed(
                        "confirmed-chara-presentation-terminal-failed");
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionStageBarrierPresentationLane
                     && event.payload_bytes
                        == sizeof(RollbackProductionStageBarrierInvocation))
            {
                RollbackProductionStageBarrierInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                const bool epoch_ok = event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->m_stage_identity.stage_actor_manager != 0
                    && runtime->m_stage_identity.stage_actor_manager
                        == runtime->m_manifest.epoch.stage_actor_manager
                    && invocation.stage_layout_digest
                        == runtime->m_stage_identity.stage_layout_digest
                    && invocation.actor_set_digest
                        == runtime->m_stage_identity.actor_set_digest;
                uintptr_t actor = 0;
                const bool resolved = epoch_ok
                    && ResolveRollbackBreakableStageActor(
                        runtime->m_stage_identity.stage_actor_manager,
                        RollbackBreakableActorKind::Barrier,
                        invocation.actor_id, actor);
                const RollbackBreakableStageRecord* identity = nullptr;
                if (resolved)
                {
                    for (const auto& record :
                            runtime->m_stage_identity.records)
                    {
                        if (record.kind
                                != RollbackBreakableActorKind::Barrier
                            || record.id != invocation.actor_id)
                            continue;
                        if (identity != nullptr)
                        {
                            identity = nullptr;
                            break;
                        }
                        identity = &record;
                    }
                }
                void* live_vtable = nullptr;
                int32_t logical_state = 0;
                const bool identity_ok = identity
                    && identity->actor == actor
                    && identity->vtable != 0
                    && SafeReadPtr(reinterpret_cast<const void*>(actor),
                        &live_vtable)
                    && reinterpret_cast<uintptr_t>(live_vtable)
                        == identity->vtable
                    && SafeReadInt32(reinterpret_cast<const void*>(
                            actor + kRollbackStageBarrierHitCountOffset),
                        &logical_state)
                    && runtime->m_stage_barrier_presentation_trampoline != 0;
                if (identity_ok)
                {
                    reinterpret_cast<StageBarrierPresentationFn>(
                        runtime->m_stage_barrier_presentation_trampoline)(
                            actor, invocation.state);
                    committed = SafeWriteUInt32(
                        reinterpret_cast<void*>(actor
                            + kRollbackStageBarrierHitCountOffset),
                        static_cast<uint32_t>(logical_state));
                }
                if (!committed)
                {
                    runtime->fail_closed(identity_ok
                        ? "confirmed-stage-barrier-logical-state-restore-failed"
                        : "confirmed-stage-barrier-identity-mismatch");
                }
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionStageBarrierHitLane
                     && event.payload_bytes
                        == sizeof(
                            RollbackProductionStageBarrierHitInvocation))
            {
                RollbackProductionStageBarrierHitInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                const bool payload_ok = invocation.reserved == 0
                    && invocation.pre_hit_state >= 0
                    && std::isfinite(invocation.hit_direction.x)
                    && std::isfinite(invocation.hit_direction.y)
                    && std::isfinite(invocation.hit_direction.z);
                const bool epoch_ok = payload_ok
                    && event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->m_stage_identity.stage_actor_manager != 0
                    && runtime->m_stage_identity.stage_actor_manager
                        == runtime->m_manifest.epoch.stage_actor_manager
                    && invocation.stage_layout_digest
                        == runtime->m_stage_identity.stage_layout_digest
                    && invocation.actor_set_digest
                        == runtime->m_stage_identity.actor_set_digest;
                uintptr_t actor = 0;
                const bool resolved = epoch_ok
                    && ResolveRollbackBreakableStageActor(
                        runtime->m_stage_identity.stage_actor_manager,
                        RollbackBreakableActorKind::Barrier,
                        invocation.actor_id, actor);
                const RollbackBreakableStageRecord* identity = nullptr;
                if (resolved)
                {
                    for (const auto& record :
                            runtime->m_stage_identity.records)
                    {
                        if (record.kind
                                != RollbackBreakableActorKind::Barrier
                            || record.id != invocation.actor_id)
                            continue;
                        if (identity != nullptr)
                        {
                            identity = nullptr;
                            break;
                        }
                        identity = &record;
                    }
                }
                void* live_vtable = nullptr;
                int32_t logical_state = 0;
                int32_t endurance = 0;
                const bool identity_ok = identity
                    && identity->actor == actor
                    && identity->vtable != 0
                    && SafeReadPtr(reinterpret_cast<const void*>(actor),
                        &live_vtable)
                    && reinterpret_cast<uintptr_t>(live_vtable)
                        == identity->vtable
                    && SafeReadInt32(reinterpret_cast<const void*>(actor
                            + kRollbackStageBarrierHitCountOffset),
                        &logical_state)
                    && SafeReadInt32(reinterpret_cast<const void*>(actor
                            + kRollbackStageBarrierEnduranceOffset),
                        &endurance)
                    && invocation.pre_hit_state < endurance
                    && logical_state >= invocation.pre_hit_state + 1
                    && runtime->m_stage_barrier_hit_trampoline != 0
                    && !runtime->m_stage_barrier_hit_transaction.active
                    && !runtime->m_stage_break_terminal_capture_active
                    && !runtime->m_stage_break_commit_active;
                bool pre_state_written = false;
                if (identity_ok)
                {
                    pre_state_written = SafeWriteUInt32(
                        reinterpret_cast<void*>(actor
                            + kRollbackStageBarrierHitCountOffset),
                        static_cast<uint32_t>(
                            invocation.pre_hit_state));
                }
                if (pre_state_written)
                {
                    runtime->m_stage_break_commit_active = true;
                    reinterpret_cast<StageBarrierHitFn>(
                        runtime->m_stage_barrier_hit_trampoline)(actor,
                            &invocation.hit_direction);
                    runtime->m_stage_break_commit_active = false;
                    committed = SafeWriteUInt32(
                        reinterpret_cast<void*>(actor
                            + kRollbackStageBarrierHitCountOffset),
                        static_cast<uint32_t>(logical_state));
                }
                if (!committed)
                {
                    runtime->m_stage_break_commit_active = false;
                    runtime->fail_closed(pre_state_written
                        ? "confirmed-stage-barrier-hit-logical-state-restore-failed"
                        : "confirmed-stage-barrier-hit-identity-mismatch");
                }
            }
            else if (event.type == RollbackSideEffectType::Vfx
                     && event.lane
                        == kRollbackProductionStageBarrierHitLane
                     && event.payload_bytes
                        == sizeof(
                            RollbackProductionStageWallBrokenInvocation))
            {
                RollbackProductionStageWallBrokenInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                    sizeof(invocation));
                bool payload_ok = invocation.reserved == 0
                    && invocation.immediately <= 1
                    && invocation.root_present <= 1
                    && (invocation.pre_break_state_word & 0xFFu) == 0
                    && std::isfinite(invocation.pre_fade_timer)
                    && std::isfinite(invocation.pre_fade_rate)
                    && std::isfinite(invocation.root_translation.x)
                    && std::isfinite(invocation.root_translation.y)
                    && std::isfinite(invocation.root_translation.z);
                for (float value : invocation.root_rotation)
                    payload_ok = payload_ok && std::isfinite(value);
                const bool epoch_ok = payload_ok
                    && event.epoch
                        == runtime->m_manifest.epoch.generation
                    && runtime->m_stage_identity.stage_actor_manager != 0
                    && runtime->m_stage_identity.stage_actor_manager
                        == runtime->m_manifest.epoch.stage_actor_manager
                    && invocation.stage_layout_digest
                        == runtime->m_stage_identity.stage_layout_digest
                    && invocation.actor_set_digest
                        == runtime->m_stage_identity.actor_set_digest;
                uintptr_t actor = 0;
                const bool resolved = epoch_ok
                    && ResolveRollbackBreakableStageActor(
                        runtime->m_stage_identity.stage_actor_manager,
                        RollbackBreakableActorKind::Wall,
                        invocation.actor_id, actor);
                const RollbackBreakableStageRecord* identity = nullptr;
                if (resolved)
                {
                    for (const auto& record :
                            runtime->m_stage_identity.records)
                    {
                        if (record.kind != RollbackBreakableActorKind::Wall
                            || record.id != invocation.actor_id)
                            continue;
                        if (identity != nullptr)
                        {
                            identity = nullptr;
                            break;
                        }
                        identity = &record;
                    }
                }
                void* live_vtable = nullptr;
                void* live_root_vtable = nullptr;
                uintptr_t root_component = 0;
                std::array<float, 4> root_rotation {};
                RollbackProductionNativeVector3 root_translation {};
                uint32_t logical_state_word = 0;
                float logical_fade_timer = 0.0f;
                float logical_fade_rate = 0.0f;
                bool identity_ok = identity
                    && identity->actor == actor
                    && identity->vtable != 0
                    && SafeReadPtr(reinterpret_cast<const void*>(actor),
                        &live_vtable)
                    && reinterpret_cast<uintptr_t>(live_vtable)
                        == identity->vtable
                    && SafeReadBytes(reinterpret_cast<const void*>(actor
                            + kRollbackStageWallRootComponentOffset),
                        &root_component, sizeof(root_component))
                    && root_component == identity->root_component
                    && (root_component != 0)
                        == (invocation.root_present != 0)
                    && SafeReadUInt32(reinterpret_cast<const void*>(actor
                            + kRollbackStageWallBreakStateOffset),
                        &logical_state_word)
                    && SafeReadFloat(reinterpret_cast<const void*>(actor
                            + kRollbackStageWallFadeTimerOffset),
                        &logical_fade_timer)
                    && SafeReadFloat(reinterpret_cast<const void*>(actor
                            + kRollbackStageWallFadeRateOffset),
                        &logical_fade_rate)
                    && (logical_state_word & 0xFFu) != 0
                    && runtime->m_stage_wall_broken_trampoline != 0
                    && !runtime->m_stage_barrier_hit_transaction.active
                    && !runtime->m_stage_wall_broken_transaction.active
                    && !runtime->m_stage_break_terminal_capture_active
                    && !runtime->m_stage_break_commit_active;
                if (identity_ok && root_component)
                {
                    identity_ok = identity->root_component_vtable != 0
                        && SafeReadPtr(reinterpret_cast<const void*>(
                                root_component), &live_root_vtable)
                        && reinterpret_cast<uintptr_t>(live_root_vtable)
                            == identity->root_component_vtable
                        && SafeReadBytes(reinterpret_cast<const void*>(
                                root_component
                                + kRollbackSceneComponentWorldRotationOffset),
                            root_rotation.data(), sizeof(root_rotation))
                        && SafeReadBytes(reinterpret_cast<const void*>(
                                root_component
                                + kRollbackSceneComponentWorldTranslationOffset),
                            &root_translation, sizeof(root_translation))
                        && std::memcmp(root_rotation.data(),
                            invocation.root_rotation.data(),
                            sizeof(root_rotation)) == 0
                        && std::memcmp(&root_translation,
                            &invocation.root_translation,
                            sizeof(root_translation)) == 0;
                }
                bool pre_state_written = false;
                if (identity_ok)
                {
                    pre_state_written = SafeWriteUInt32(
                            reinterpret_cast<void*>(actor
                                + kRollbackStageWallBreakStateOffset),
                            invocation.pre_break_state_word)
                        && SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeTimerOffset),
                            invocation.pre_fade_timer)
                        && SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeRateOffset),
                            invocation.pre_fade_rate);
                }
                if (pre_state_written)
                {
                    runtime->m_stage_break_commit_active = true;
                    reinterpret_cast<StageWallBrokenFn>(
                        runtime->m_stage_wall_broken_trampoline)(actor,
                            invocation.immediately != 0);
                    runtime->m_stage_break_commit_active = false;
                    committed = SafeWriteUInt32(
                            reinterpret_cast<void*>(actor
                                + kRollbackStageWallBreakStateOffset),
                            logical_state_word)
                        && SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeTimerOffset),
                            logical_fade_timer)
                        && SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeRateOffset),
                            logical_fade_rate);
                }
                if (!committed)
                {
                    runtime->m_stage_break_commit_active = false;
                    if (identity_ok)
                    {
                        // Repair a partial pre-state write before failing
                        // closed; no terminal replay occurs unless all three
                        // authoritative fields were installed.
                        SafeWriteUInt32(reinterpret_cast<void*>(actor
                                + kRollbackStageWallBreakStateOffset),
                            logical_state_word);
                        SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeTimerOffset),
                            logical_fade_timer);
                        SafeWriteFloat(reinterpret_cast<void*>(actor
                                + kRollbackStageWallFadeRateOffset),
                            logical_fade_rate);
                    }
                    runtime->fail_closed(pre_state_written
                        ? "confirmed-stage-wall-logical-state-restore-failed"
                        : "confirmed-stage-wall-identity-mismatch");
                }
            }
            else if (event.type == RollbackSideEffectType::Vfx)
            {
                runtime->fail_closed(
                    "semantic-side-effect-journal-entry-unsupported");
            }
            else if (event.type == RollbackSideEffectType::Camera
                     && event.payload_bytes
                        == sizeof(RollbackProductionCameraInvocation))
            {
                RollbackProductionCameraInvocation invocation {};
                std::memcpy(&invocation, event.payload.data(),
                            sizeof(invocation));
                void* camera_raw = nullptr;
                void* snapshot_state_raw = nullptr;
                void* output_raw = nullptr;
                const bool camera_ok =
                    RollbackCameraPresentationValueValid(invocation)
                    && SafeReadPtr(reinterpret_cast<const void*>(
                        runtime->m_image_base
                        + kRollbackProductionRvaCameraWorld),
                        &camera_raw)
                    && SafeReadPtr(reinterpret_cast<const void*>(
                        runtime->m_image_base
                            + kRollbackProductionRvaCameraSnapshotState),
                        &snapshot_state_raw)
                    && camera_raw && camera_raw == snapshot_state_raw
                    && SafeReadPtr(static_cast<const uint8_t*>(camera_raw)
                        + 0x90, &output_raw)
                    && output_raw;
                const bool write_ok = camera_ok
                    && RollbackCommitCameraPresentation(
                        invocation,
                        [output_raw](size_t offset, float value) noexcept
                        {
                            return SafeWriteFloat(
                                static_cast<uint8_t*>(output_raw)
                                    + 0x340 + offset,
                                value);
                        },
                        [output_raw](uint32_t active) noexcept
                        {
                            return SafeWriteUInt32(
                                static_cast<uint8_t*>(output_raw) + 0x350,
                                active);
                        });
                if (!write_ok)
                {
                    runtime->fail_closed(
                        "confirmed-camera-vibration-output-write-failed");
                }
                committed = write_ok;
            }
            else if (event.type
                        == RollbackSideEffectType::ConfirmedTransition
                     && event.payload_bytes
                        == sizeof(RollbackProductionTransitionInvocation))
            {
                // Transition events are the exactly-once audit journal.
                // Gameplay state is already present in the confirmed
                // snapshot; committing the journal must not mutate it.
                RollbackProductionTransitionInvocation transition {};
                std::memcpy(&transition, event.payload.data(),
                            sizeof(transition));
                if (transition.flags & RollbackTransitionHit)
                    ++runtime->m_status.transition_hit_committed;
                if (transition.flags & RollbackTransitionDamage)
                    ++runtime->m_status.transition_damage_committed;
                if (transition.flags & RollbackTransitionMeter)
                    ++runtime->m_status.transition_meter_committed;
                if (transition.flags & RollbackTransitionRound)
                    ++runtime->m_status.transition_round_committed;
                committed = true;
            }
            else
            {
                runtime->fail_closed(
                    "confirmed-presentation-payload-invalid");
            }
            runtime->m_committing_effect = false;
            return committed;
        }

        static void __fastcall stage_barrier_presentation_hook(
            uintptr_t actor, int32_t requested_state)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [runtime, actor, requested_state]() {
                if (runtime->m_stage_barrier_presentation_trampoline)
                {
                    reinterpret_cast<StageBarrierPresentationFn>(
                        runtime->m_stage_barrier_presentation_trampoline)(
                            actor, requested_state);
                }
            };
            if (!lease || runtime->m_committing_effect
                || !runtime->m_hook_owns_tick
                || CurrentRollbackNativeSimulationScope(runtime) == nullptr
                || !runtime->m_accept_effects.load(
                    std::memory_order_acquire))
            {
                pass_through();
                return;
            }
            if (!runtime->m_effect_frame.valid)
            {
                runtime->fail_closed(
                    "stage-barrier-presentation-frame-missing");
                return;
            }
            int32_t actor_id = 0;
            uintptr_t resolved_actor = 0;
            const int32_t logical_state = requested_state < 0
                ? 0 : requested_state;
            const bool epoch_ok = actor != 0
                && runtime->m_stage_identity.stage_actor_manager != 0
                && runtime->m_stage_identity.stage_actor_manager
                    == runtime->m_manifest.epoch.stage_actor_manager
                && runtime->m_stage_identity.stage_layout_digest != 0
                && runtime->m_stage_identity.actor_set_digest != 0;
            const bool actor_ok = epoch_ok
                && SafeReadInt32(reinterpret_cast<const void*>(
                        actor + kRollbackStageBarrierIdOffset), &actor_id)
                && ResolveRollbackBreakableStageActor(
                    runtime->m_stage_identity.stage_actor_manager,
                    RollbackBreakableActorKind::Barrier,
                    actor_id, resolved_actor)
                && resolved_actor == actor;
            const RollbackBreakableStageRecord* identity = nullptr;
            if (actor_ok)
            {
                for (const auto& record : runtime->m_stage_identity.records)
                {
                    if (record.kind != RollbackBreakableActorKind::Barrier
                        || record.id != actor_id)
                        continue;
                    if (identity != nullptr)
                    {
                        identity = nullptr;
                        break;
                    }
                    identity = &record;
                }
            }
            void* live_vtable = nullptr;
            if (!identity || identity->actor != actor
                || identity->vtable == 0
                || !SafeReadPtr(reinterpret_cast<const void*>(actor),
                    &live_vtable)
                || reinterpret_cast<uintptr_t>(live_vtable)
                    != identity->vtable)
            {
                runtime->fail_closed(
                    "stage-barrier-presentation-identity-mismatch");
                return;
            }
            if (!SafeWriteUInt32(reinterpret_cast<void*>(
                    actor + kRollbackStageBarrierHitCountOffset),
                    static_cast<uint32_t>(logical_state)))
            {
                runtime->fail_closed(
                    "stage-barrier-logical-state-write-failed");
                return;
            }
            RollbackProductionStageBarrierInvocation invocation {};
            invocation.actor_id = actor_id;
            invocation.state = logical_state;
            invocation.stage_layout_digest =
                runtime->m_stage_identity.stage_layout_digest;
            invocation.actor_set_digest =
                runtime->m_stage_identity.actor_set_digest;
            if (!runtime->queue_side_effect(
                    RollbackSideEffectType::Vfx,
                    &invocation, sizeof(invocation),
                    kRollbackProductionStageBarrierPresentationLane))
            {
                runtime->fail_closed(runtime->m_ledger.report().failure);
            }
        }

        bool restore_stage_barrier_hit_source_presentation() noexcept
        {
            auto& transaction = m_stage_barrier_hit_transaction;
            if (!transaction.active) return false;
            if (transaction.restored) return true;
            void* live_vtable = nullptr;
            if (!transaction.actor || !transaction.vtable
                || !SafeReadPtr(reinterpret_cast<const void*>(
                        transaction.actor), &live_vtable)
                || reinterpret_cast<uintptr_t>(live_vtable)
                    != transaction.vtable)
                return false;
            if (!SafeWriteBytes(reinterpret_cast<void*>(transaction.actor
                        + kRollbackStageBarrierHitEffectOffset),
                    &transaction.hit_effect,
                    sizeof(transaction.hit_effect))
                || !SafeWriteBytes(reinterpret_cast<void*>(transaction.actor
                        + kRollbackStageBarrierBreakEffectOffset),
                    &transaction.break_effect,
                    sizeof(transaction.break_effect))
                || !SafeWriteUInt32(reinterpret_cast<void*>(transaction.actor
                        + kRollbackStageBarrierMaterialRuntimeDirtyOffset),
                    transaction.material_runtime_dirty))
                return false;
            transaction.restored = true;
            return true;
        }

        bool restore_stage_wall_broken_source_presentation() noexcept
        {
            auto& transaction = m_stage_wall_broken_transaction;
            if (!transaction.active) return false;
            if (transaction.restored) return true;
            void* live_vtable = nullptr;
            if (!transaction.actor || !transaction.vtable
                || !SafeReadPtr(reinterpret_cast<const void*>(
                        transaction.actor), &live_vtable)
                || reinterpret_cast<uintptr_t>(live_vtable)
                    != transaction.vtable)
                return false;
            if (!SafeWriteBytes(reinterpret_cast<void*>(transaction.actor
                        + kRollbackStageWallParticleSystemOffset),
                    &transaction.particle_system,
                    sizeof(transaction.particle_system))
                || !SafeWriteBytes(reinterpret_cast<void*>(transaction.actor
                        + kRollbackStageWallParticleComponentOffset),
                    &transaction.particle_component,
                    sizeof(transaction.particle_component)))
                return false;
            transaction.restored = true;
            return true;
        }

        static void __fastcall stage_barrier_hit_hook(
            uintptr_t actor,
            const RollbackProductionNativeVector3* hit_direction)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [runtime, actor, hit_direction]() {
                if (runtime->m_stage_barrier_hit_trampoline)
                {
                    reinterpret_cast<StageBarrierHitFn>(
                        runtime->m_stage_barrier_hit_trampoline)(
                            actor, hit_direction);
                }
            };
            if (!lease || runtime->m_committing_effect
                || !runtime->m_hook_owns_tick
                || CurrentRollbackNativeSimulationScope(runtime) == nullptr
                || !runtime->m_accept_effects.load(
                    std::memory_order_acquire))
            {
                pass_through();
                return;
            }
            if (runtime->m_stage_barrier_hit_transaction.active
                || runtime->m_stage_wall_broken_transaction.active
                || runtime->m_stage_break_terminal_capture_active)
            {
                runtime->fail_closed(
                    "stage-barrier-hit-transaction-nested");
                return;
            }
            if (!runtime->m_effect_frame.valid)
            {
                runtime->fail_closed("stage-barrier-hit-frame-missing");
                return;
            }

            RollbackProductionNativeVector3 direction {};
            int32_t actor_id = 0;
            int32_t pre_hit_state = 0;
            int32_t endurance = 0;
            uintptr_t hit_effect = 0;
            uintptr_t break_effect = 0;
            uint32_t material_runtime_dirty = 0;
            void* live_vtable = nullptr;
            uintptr_t resolved_actor = 0;
            const bool epoch_ok = actor != 0 && hit_direction != nullptr
                && runtime->m_stage_identity.stage_actor_manager != 0
                && runtime->m_stage_identity.stage_actor_manager
                    == runtime->m_manifest.epoch.stage_actor_manager
                && runtime->m_stage_identity.stage_layout_digest != 0
                && runtime->m_stage_identity.actor_set_digest != 0;
            const bool source_ok = epoch_ok
                && SafeReadBytes(hit_direction, &direction,
                    sizeof(direction))
                && std::isfinite(direction.x)
                && std::isfinite(direction.y)
                && std::isfinite(direction.z)
                && SafeReadInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierIdOffset), &actor_id)
                && SafeReadInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierHitCountOffset),
                    &pre_hit_state)
                && SafeReadInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierEnduranceOffset), &endurance)
                && SafeReadPtr(reinterpret_cast<const void*>(actor),
                    &live_vtable)
                && SafeReadBytes(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierHitEffectOffset), &hit_effect,
                    sizeof(hit_effect))
                && SafeReadBytes(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierBreakEffectOffset),
                    &break_effect, sizeof(break_effect))
                && SafeReadUInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageBarrierMaterialRuntimeDirtyOffset),
                    &material_runtime_dirty)
                && ResolveRollbackBreakableStageActor(
                    runtime->m_stage_identity.stage_actor_manager,
                    RollbackBreakableActorKind::Barrier, actor_id,
                    resolved_actor)
                && resolved_actor == actor;
            const RollbackBreakableStageRecord* identity = nullptr;
            if (source_ok)
            {
                for (const auto& record : runtime->m_stage_identity.records)
                {
                    if (record.kind
                            != RollbackBreakableActorKind::Barrier
                        || record.id != actor_id)
                        continue;
                    if (identity != nullptr)
                    {
                        identity = nullptr;
                        break;
                    }
                    identity = &record;
                }
            }
            if (!identity || identity->actor != actor
                || identity->vtable == 0
                || reinterpret_cast<uintptr_t>(live_vtable)
                    != identity->vtable
                || pre_hit_state < 0 || endurance < 0)
            {
                runtime->fail_closed(
                    "stage-barrier-hit-source-identity-mismatch");
                return;
            }
            if (pre_hit_state >= endurance)
            {
                // Native behavior is a strict no-op once endurance is met.
                pass_through();
                return;
            }

            RollbackProductionStageBarrierHitInvocation invocation {};
            invocation.actor_id = actor_id;
            invocation.pre_hit_state = pre_hit_state;
            invocation.hit_direction = direction;
            invocation.stage_layout_digest =
                runtime->m_stage_identity.stage_layout_digest;
            invocation.actor_set_digest =
                runtime->m_stage_identity.actor_set_digest;
            if (!runtime->queue_side_effect(
                    RollbackSideEffectType::Vfx, &invocation,
                    sizeof(invocation),
                    kRollbackProductionStageBarrierHitLane))
            {
                runtime->fail_closed(runtime->m_ledger.report().failure);
                return;
            }

            auto& transaction = runtime->m_stage_barrier_hit_transaction;
            transaction.actor = actor;
            transaction.vtable = identity->vtable;
            transaction.hit_effect = hit_effect;
            transaction.break_effect = break_effect;
            transaction.material_runtime_dirty = material_runtime_dirty;
            transaction.active = true;
            const uintptr_t null_effect = 0;
            if (!SafeWriteBytes(reinterpret_cast<void*>(actor
                        + kRollbackStageBarrierHitEffectOffset),
                    &null_effect, sizeof(null_effect))
                || !SafeWriteBytes(reinterpret_cast<void*>(actor
                        + kRollbackStageBarrierBreakEffectOffset),
                    &null_effect, sizeof(null_effect)))
            {
                const bool restored = runtime
                    ->restore_stage_barrier_hit_source_presentation();
                transaction = {};
                runtime->fail_closed(restored
                    ? "stage-barrier-hit-source-mask-failed"
                    : "stage-barrier-hit-source-mask-restore-failed");
                return;
            }

            runtime->m_stage_break_terminal_capture_active = true;
            pass_through();
            if (runtime->m_stage_break_terminal_capture_active)
            {
                runtime->m_stage_break_terminal_capture_active = false;
                if (!runtime->restore_stage_barrier_hit_source_presentation())
                {
                    transaction = {};
                    runtime->fail_closed(
                        "stage-barrier-hit-source-restore-failed");
                    return;
                }
            }
            const bool restored = transaction.restored;
            transaction = {};
            if (!restored)
            {
                runtime->fail_closed(
                    "stage-barrier-hit-source-restore-missing");
            }
        }

        static void __fastcall stage_wall_broken_hook(
            uintptr_t actor, bool immediately)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [runtime, actor, immediately]() {
                if (runtime->m_stage_wall_broken_trampoline)
                {
                    reinterpret_cast<StageWallBrokenFn>(
                        runtime->m_stage_wall_broken_trampoline)(
                            actor, immediately);
                }
            };
            if (!lease || runtime->m_committing_effect
                || !runtime->m_hook_owns_tick
                || CurrentRollbackNativeSimulationScope(runtime) == nullptr
                || !runtime->m_accept_effects.load(
                    std::memory_order_acquire))
            {
                pass_through();
                return;
            }
            if (runtime->m_stage_barrier_hit_transaction.active
                || runtime->m_stage_wall_broken_transaction.active
                || runtime->m_stage_break_terminal_capture_active)
            {
                runtime->fail_closed(
                    "stage-wall-broken-transaction-nested");
                return;
            }
            if (!runtime->m_effect_frame.valid)
            {
                runtime->fail_closed("stage-wall-broken-frame-missing");
                return;
            }

            RollbackProductionStageWallBrokenInvocation invocation {};
            uintptr_t particle_system = 0;
            uintptr_t particle_component = 0;
            uintptr_t root_component = 0;
            uintptr_t resolved_actor = 0;
            void* live_vtable = nullptr;
            void* live_root_vtable = nullptr;
            const bool epoch_ok = actor != 0
                && runtime->m_stage_identity.stage_actor_manager != 0
                && runtime->m_stage_identity.stage_actor_manager
                    == runtime->m_manifest.epoch.stage_actor_manager
                && runtime->m_stage_identity.stage_layout_digest != 0
                && runtime->m_stage_identity.actor_set_digest != 0;
            bool source_ok = epoch_ok
                && SafeReadInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallIdOffset),
                    &invocation.actor_id)
                && SafeReadUInt32(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallBreakStateOffset),
                    &invocation.pre_break_state_word)
                && SafeReadFloat(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallFadeTimerOffset),
                    &invocation.pre_fade_timer)
                && SafeReadFloat(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallFadeRateOffset),
                    &invocation.pre_fade_rate)
                && SafeReadPtr(reinterpret_cast<const void*>(actor),
                    &live_vtable)
                && SafeReadBytes(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallParticleSystemOffset),
                    &particle_system, sizeof(particle_system))
                && SafeReadBytes(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallParticleComponentOffset),
                    &particle_component, sizeof(particle_component))
                && SafeReadBytes(reinterpret_cast<const void*>(actor
                        + kRollbackStageWallRootComponentOffset),
                    &root_component, sizeof(root_component))
                && ResolveRollbackBreakableStageActor(
                    runtime->m_stage_identity.stage_actor_manager,
                    RollbackBreakableActorKind::Wall,
                    invocation.actor_id, resolved_actor)
                && resolved_actor == actor
                && std::isfinite(invocation.pre_fade_timer)
                && std::isfinite(invocation.pre_fade_rate);
            if (source_ok && root_component)
            {
                source_ok = SafeReadPtr(reinterpret_cast<const void*>(
                        root_component), &live_root_vtable)
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            root_component
                            + kRollbackSceneComponentWorldRotationOffset),
                        invocation.root_rotation.data(),
                        sizeof(invocation.root_rotation))
                    && SafeReadBytes(reinterpret_cast<const void*>(
                            root_component
                            + kRollbackSceneComponentWorldTranslationOffset),
                        &invocation.root_translation,
                        sizeof(invocation.root_translation));
            }
            invocation.immediately = immediately ? 1 : 0;
            invocation.root_present = root_component ? 1 : 0;
            invocation.stage_layout_digest =
                runtime->m_stage_identity.stage_layout_digest;
            invocation.actor_set_digest =
                runtime->m_stage_identity.actor_set_digest;
            for (float value : invocation.root_rotation)
                source_ok = source_ok && std::isfinite(value);
            source_ok = source_ok
                && std::isfinite(invocation.root_translation.x)
                && std::isfinite(invocation.root_translation.y)
                && std::isfinite(invocation.root_translation.z);

            const RollbackBreakableStageRecord* identity = nullptr;
            if (source_ok)
            {
                for (const auto& record : runtime->m_stage_identity.records)
                {
                    if (record.kind != RollbackBreakableActorKind::Wall
                        || record.id != invocation.actor_id)
                        continue;
                    if (identity != nullptr)
                    {
                        identity = nullptr;
                        break;
                    }
                    identity = &record;
                }
            }
            if (!identity || identity->actor != actor
                || identity->vtable == 0
                || reinterpret_cast<uintptr_t>(live_vtable)
                    != identity->vtable
                || identity->root_component != root_component
                || (root_component
                    && (identity->root_component_vtable == 0
                        || reinterpret_cast<uintptr_t>(live_root_vtable)
                            != identity->root_component_vtable)))
            {
                runtime->fail_closed(
                    "stage-wall-broken-source-identity-mismatch");
                return;
            }
            if ((invocation.pre_break_state_word & 0xFFu) != 0)
            {
                // Native behavior is a strict no-op after the first break.
                pass_through();
                return;
            }
            if (!runtime->queue_side_effect(
                    RollbackSideEffectType::Vfx, &invocation,
                    sizeof(invocation),
                    kRollbackProductionStageBarrierHitLane))
            {
                runtime->fail_closed(runtime->m_ledger.report().failure);
                return;
            }

            auto& transaction = runtime->m_stage_wall_broken_transaction;
            transaction.actor = actor;
            transaction.vtable = identity->vtable;
            transaction.particle_system = particle_system;
            transaction.particle_component = particle_component;
            transaction.active = true;
            const uintptr_t null_pointer = 0;
            if (!SafeWriteBytes(reinterpret_cast<void*>(actor
                        + kRollbackStageWallParticleSystemOffset),
                    &null_pointer, sizeof(null_pointer))
                || !SafeWriteBytes(reinterpret_cast<void*>(actor
                        + kRollbackStageWallParticleComponentOffset),
                    &null_pointer, sizeof(null_pointer)))
            {
                const bool restored = runtime
                    ->restore_stage_wall_broken_source_presentation();
                transaction = {};
                runtime->fail_closed(restored
                    ? "stage-wall-broken-source-mask-failed"
                    : "stage-wall-broken-source-mask-restore-failed");
                return;
            }

            runtime->m_stage_break_terminal_capture_active = true;
            pass_through();
            runtime->m_stage_break_terminal_capture_active = false;
            runtime->m_stage_break_listener_source_active = false;
            const bool restored = runtime
                ->restore_stage_wall_broken_source_presentation();
            transaction = {};
            if (!restored)
            {
                runtime->fail_closed(
                    "stage-wall-broken-source-restore-failed");
            }
        }

        static uintptr_t __fastcall stage_particle_spawn_hook(
            uintptr_t owner, uintptr_t particle_system,
            const void* location, const void* rotation, const void* scale,
            uint8_t auto_activate)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return 0;
            CallbackLease lease(runtime, true);
            if (lease && runtime->m_stage_break_terminal_capture_active
                && !runtime->m_stage_break_listener_source_active)
                return 0;
            const bool unclassified_owned_spawn = lease
                && runtime->m_hook_owns_tick
                && CurrentRollbackNativeSimulationScope(runtime) != nullptr
                && runtime->m_accept_effects.load(
                    std::memory_order_acquire)
                && !runtime->m_committing_effect
                && !runtime->m_stage_break_commit_active;
            if (unclassified_owned_spawn)
            {
                // The reflected SpawnLuxEmitterAtLocation ABI returns a live
                // UParticleSystemComponent that Blueprint may retain and
                // mutate.  A null/speculative substitute is not semantics
                // preserving.  The only stock package reference is
                // BP_Kuroko::ReceiveTick, which UE dispatches outside Horse's
                // owned SimulationLoop scope.  Any other source-time call in
                // an owned iteration is therefore an unsupported route, not
                // a terminal that may be allowed to leak speculatively.
                runtime->fail_closed(
                    "owned-particle-spawn-route-unclassified");
                return 0;
            }
            if (!runtime->m_stage_particle_spawn_trampoline) return 0;
            return reinterpret_cast<StageParticleSpawnFn>(
                runtime->m_stage_particle_spawn_trampoline)(owner,
                    particle_system, location, rotation, scale,
                    auto_activate);
        }

