        static void __fastcall stage_break_event_dispatch_hook(
            uintptr_t emitter, int32_t actor_id,
            const RollbackProductionNativeVector3* location)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [runtime, emitter, actor_id, location]() {
                if (runtime->m_stage_break_event_dispatch_trampoline)
                {
                    reinterpret_cast<StageBreakEventDispatchFn>(
                        runtime->m_stage_break_event_dispatch_trampoline)(
                            emitter, actor_id, location);
                }
            };
            if (!lease)
            {
                pass_through();
                return;
            }
            if (runtime->m_stage_break_commit_active)
                return;
            if (runtime->m_stage_break_terminal_capture_active)
            {
                const bool restored =
                    runtime->m_stage_wall_broken_transaction.active
                    ? runtime
                        ->restore_stage_wall_broken_source_presentation()
                    : runtime
                        ->restore_stage_barrier_hit_source_presentation();
                if (!restored)
                {
                    runtime->m_stage_break_terminal_capture_active = false;
                    runtime->fail_closed(
                        "stage-break-predispatch-restore-failed");
                    return;
                }
                // Listener callbacks execute at source time and are outside
                // the terminal-suppression scope.
                runtime->m_stage_break_listener_source_active = true;
            }
            pass_through();
            runtime->m_stage_break_listener_source_active = false;
        }

        bool resolve_chara_presentation_role(
            uintptr_t actor, uint8_t& role) const noexcept
        {
            role = 0xFF;
            if (!m_presentation_semantic_identity.well_formed()
                || !RollbackPresentationSemanticIdentityLive(
                    m_presentation_semantic_identity))
                return false;
            int32_t player_index = -1;
            void* vtable = nullptr;
            if (!SafeReadInt32(reinterpret_cast<const void*>(
                    actor + 0x3A0), &player_index)
                || player_index < 0 || player_index > 1
                || m_presentation_semantic_identity.chara_owner[
                    static_cast<size_t>(player_index)] != actor
                || !SafeReadPtr(reinterpret_cast<const void*>(actor),
                    &vtable)
                || reinterpret_cast<uintptr_t>(vtable)
                    != m_presentation_semantic_identity
                        .chara_owner_vtable[
                            static_cast<size_t>(player_index)])
                return false;
            role = static_cast<uint8_t>(player_index);
            return true;
        }

        static void dispatch_chara_presentation_callback(
            RollbackCharaPresentationOperation operation,
            uintptr_t actor, const void* value, uint16_t value_bytes,
            uint64_t trampoline) noexcept
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [&]() noexcept {
                if (trampoline)
                    reinterpret_cast<CharaPresentationCallbackFn>(
                        trampoline)(actor, value);
            };
            if (!lease || runtime->m_committing_effect
                || !runtime->m_hook_owns_tick.load(
                    std::memory_order_acquire)
                || CurrentRollbackNativeSimulationScope(runtime) == nullptr)
            {
                pass_through();
                return;
            }
            uint8_t role = 0xFF;
            RollbackCharaPresentationInvocation invocation {};
            invocation.operation = operation;
            invocation.value_bytes = value_bytes;
            const bool input_ok = runtime->m_accept_effects.load(
                    std::memory_order_acquire)
                && runtime->m_effect_frame.valid
                && runtime->resolve_chara_presentation_role(actor, role)
                && value_bytes
                    == RollbackCharaPresentationInvocation::
                        expected_value_bytes(operation)
                && value_bytes <= invocation.value.size()
                && (value_bytes == 0
                    || (value && SafeReadBytes(value,
                        invocation.value.data(), value_bytes)));
            if (!input_ok)
            {
                runtime->fail_closed(
                    "owned-chara-presentation-callback-unresolved");
                return;
            }
            invocation.chara_role = role;
            if (!invocation.valid()
                || !runtime->queue_side_effect(
                    RollbackSideEffectType::Vfx,
                    &invocation, sizeof(invocation),
                    kRollbackProductionCharaPresentationLane))
            {
                runtime->fail_closed(
                    "owned-chara-presentation-journal-failed");
            }
        }

