        static void __fastcall camera_vibration_hook(uintptr_t camera)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            if (!lease)
            {
                if (runtime->m_camera_vibration_trampoline)
                {
                    reinterpret_cast<CameraVibrationFn>(
                        runtime->m_camera_vibration_trampoline)(camera);
                }
                return;
            }
            if (runtime->m_committing_effect || !runtime->m_hook_owns_tick)
            {
                if (runtime->m_camera_vibration_trampoline)
                {
                    reinterpret_cast<CameraVibrationFn>(
                        runtime->m_camera_vibration_trampoline)(camera);
                }
                return;
            }
            const bool owned_native_simulation =
                CurrentRollbackNativeSimulationScope(runtime) != nullptr;
            const auto route = SelectRollbackCameraPresentationRoute(
                owned_native_simulation,
                runtime->m_accept_effects.load(std::memory_order_acquire),
                runtime->m_effect_frame.valid);
            if (route == RollbackCameraPresentationRoute::PassThrough)
            {
                if (runtime->m_camera_vibration_trampoline)
                {
                    reinterpret_cast<CameraVibrationFn>(
                        runtime->m_camera_vibration_trampoline)(camera);
                }
                return;
            }

            void* expected_raw = nullptr;
            if (!SafeReadPtr(reinterpret_cast<const void*>(
                    runtime->m_image_base
                    + kRollbackProductionRvaCameraWorld),
                    &expected_raw)
                || reinterpret_cast<uintptr_t>(expected_raw) != camera)
            {
                runtime->fail_closed(
                    "camera-vibration-world-mismatch");
                return;
            }
            void* snapshot_state_raw = nullptr;
            void* output_raw = nullptr;
            if (!SafeReadPtr(reinterpret_cast<const void*>(
                    runtime->m_image_base
                        + kRollbackProductionRvaCameraSnapshotState),
                    &snapshot_state_raw)
                || reinterpret_cast<uintptr_t>(snapshot_state_raw) != camera
                || !SafeReadPtr(reinterpret_cast<const void*>(
                    camera + 0x90), &output_raw)
                || !output_raw)
            {
                runtime->fail_closed(
                    "camera-vibration-snapshot-state-mismatch");
                return;
            }

            auto read_output = [output_raw](
                RollbackCameraOutputValue& value) noexcept
            {
                return SafeReadFloat(static_cast<const uint8_t*>(output_raw)
                        + 0x340, &value.x)
                    && SafeReadFloat(static_cast<const uint8_t*>(output_raw)
                        + 0x344, &value.y)
                    && SafeReadFloat(static_cast<const uint8_t*>(output_raw)
                        + 0x348, &value.z)
                    && SafeReadUInt32(static_cast<const uint8_t*>(output_raw)
                        + 0x350, &value.active);
            };
            auto write_output = [output_raw](
                const RollbackCameraOutputValue& value) noexcept
            {
                return RollbackRestoreCameraOutput(
                    value,
                    [output_raw](size_t offset, float field) noexcept
                    {
                        return SafeWriteFloat(
                            static_cast<uint8_t*>(output_raw)
                                + 0x340 + offset,
                            field);
                    },
                    [output_raw](uint32_t active) noexcept
                    {
                        return SafeWriteUInt32(
                            static_cast<uint8_t*>(output_raw) + 0x350,
                            active);
                    });
            };
            RollbackProductionCameraInvocation invocation {};
            const auto capture = RollbackCaptureCameraPresentationOutput(
                read_output,
                [runtime, camera]() noexcept
                {
                    reinterpret_cast<CameraVibrationFn>(
                        runtime->m_camera_vibration_trampoline)(camera);
                },
                write_output,
                invocation);
            if (!capture.ok())
            {
                runtime->fail_closed(!capture.output_restored
                    ? "camera-vibration-output-restore-failed"
                    : "camera-vibration-output-capture-failed");
                return;
            }
            if (route == RollbackCameraPresentationRoute::CaptureAndQueue
                && !runtime->queue_side_effect(
                    RollbackSideEffectType::Camera,
                    &invocation, sizeof(invocation)))
            {
                runtime->fail_closed(runtime->m_ledger.report().failure);
            }
        }

