        static const wchar_t* rollback_audio_parameter_name(
            uint32_t parameter_id) noexcept
        {
            static constexpr std::array<const wchar_t*, 25> kNames {{
                L"Any", L"Pan", L"Distance", L"Height", L"Slow", L"Fade",
                L"State", L"State_BGM", L"Ambience", L"Finish_Hit",
                L"Pinch", L"Swing_V", L"Swing_H", L"Swing_S",
                L"Parrying", L"Character_Weight", L"Main_Menu_Control",
                L"Special_Parts_Type", L"SE_Battle_Start_End_Event",
                L"Battle_Round", L"Story_BGM_Volume",
                L"Story_BGM_Komori", L"Story_BGM_Pitch",
                L"Astral_Hall_Stage", L"3D_Demo_SoulType",
            }};
            return parameter_id < kNames.size() ? kNames[parameter_id]
                                                : nullptr;
        }

        static bool resolve_rollback_audio_parameter(
            const NativeFStringView* parameter_name,
            uint32_t& parameter_id) noexcept
        {
            parameter_id = 0;
            NativeFStringView view {};
            if (!parameter_name
                || !SafeReadBytes(parameter_name, &view, sizeof(view))
                || view.data == nullptr || view.count <= 1
                || view.count > 64)
                return false;
            std::array<wchar_t, 64> value {};
            if (!SafeReadBytes(view.data, value.data(),
                    static_cast<size_t>(view.count) * sizeof(wchar_t))
                || value[static_cast<size_t>(view.count - 1)] != L'\0')
                return false;
            for (uint32_t index = 0; index < 25u; ++index)
            {
                const wchar_t* known = rollback_audio_parameter_name(index);
                if (known && std::wcscmp(value.data(), known) == 0)
                {
                    parameter_id = index;
                    return true;
                }
            }
            return false;
        }

        static uint32_t __fastcall audio_register_active_voice_hook(
            uintptr_t owner, uint32_t cue_sheet_id, int32_t cue_id,
            uint32_t playback_flags)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return kRollbackAudioInvalidPlaybackId;
            CallbackLease lease(runtime, true);
            const auto pass_through = [&]() noexcept -> uint32_t {
                return runtime->m_audio_register_active_voice_trampoline
                    ? reinterpret_cast<RegisterActiveVoiceFn>(
                        runtime->m_audio_register_active_voice_trampoline)(
                            owner, cue_sheet_id, cue_id, playback_flags)
                    : kRollbackAudioInvalidPlaybackId;
            };

            RollbackAudioTerminalContext context {};
            context.committing_confirmed_event = runtime->m_committing_effect;
            context.owned_complete_iteration = lease
                && runtime->m_hook_owns_tick.load(std::memory_order_acquire)
                && CurrentRollbackNativeSimulationScope(runtime) != nullptr;
            context.presentation_enabled = runtime->m_accept_effects.load(
                std::memory_order_acquire);
            context.effect_frame_valid = runtime->m_effect_frame.valid;
            if (context.owned_complete_iteration
                && context.effect_frame_valid
                && runtime->validate_audio_manager_owner_graph(
                    runtime->m_manifest.epoch.generation))
            {
                context.owner_resolved =
                    runtime->m_audio_owner_resolver.resolve(
                        runtime->m_manifest.epoch.generation,
                        owner, context.owner);
            }
            const RollbackAudioTerminalRoute route =
                SelectRollbackAudioTerminalRoute(context);
            if (!lease || route == RollbackAudioTerminalRoute::PassThrough)
                return pass_through();
            if (route == RollbackAudioTerminalRoute::Reject)
            {
                runtime->fail_closed(
                    "owned-audio-create-owner-unclassified");
                return kRollbackAudioInvalidPlaybackId;
            }
            const uint64_t epoch = runtime->m_manifest.epoch.generation;
            const uint32_t frame = runtime->m_effect_frame.value;
            if (runtime->m_ledger.frame_is_confirmed(epoch, frame))
                return pass_through();
            if (runtime->m_audio_create_ordinal
                    >= kRollbackAudioOrdinalsPerFrame)
            {
                runtime->fail_closed(
                    "owned-audio-create-ordinal-exhausted");
                return kRollbackAudioInvalidPlaybackId;
            }
            const uint32_t logical_id = MakeRollbackAudioLogicalPlaybackId(
                frame, runtime->m_audio_create_ordinal++);
            RollbackProductionAudioInvocation invocation {};
            invocation.operation = RollbackAudioOperation::Create;
            invocation.owner = context.owner;
            invocation.logical_playback_id = logical_id;
            invocation.cue_sheet_id = cue_sheet_id;
            invocation.cue_id = cue_id;
            invocation.playback_flags = playback_flags;
            if (!invocation.valid()
                || !runtime->m_audio_playback_map.reserve_create(
                    epoch, context.owner, logical_id, frame))
            {
                runtime->fail_closed(
                    "owned-audio-create-logical-reservation-failed");
                return kRollbackAudioInvalidPlaybackId;
            }
            if (!runtime->queue_side_effect(
                    RollbackSideEffectType::Audio,
                    &invocation, sizeof(invocation),
                    kRollbackProductionAudioTerminalLane))
            {
                (void)runtime->m_audio_playback_map.cancel_create(
                    epoch, logical_id);
                runtime->fail_closed(runtime->m_ledger.report().failure);
                return kRollbackAudioInvalidPlaybackId;
            }
            return logical_id;
        }

        static bool queue_audio_stop_terminal(
            RollbackProductionRuntime* runtime,
            uintptr_t owner,
            RollbackAudioOperation operation,
            uint32_t playback_id,
            uint8_t immediate) noexcept
        {
            if (!runtime || !runtime->m_effect_frame.valid) return false;
            const uint64_t epoch = runtime->m_manifest.epoch.generation;
            if (!runtime->validate_audio_manager_owner_graph(epoch))
                return false;
            RollbackAudioOwnerSelector selector {};
            if (!runtime->m_audio_owner_resolver.resolve(
                    epoch, owner, selector))
                return false;
            RollbackProductionAudioInvocation invocation {};
            invocation.operation = operation;
            invocation.owner = selector;
            invocation.logical_playback_id = operation
                    == RollbackAudioOperation::StopAll
                ? kRollbackAudioInvalidPlaybackId : playback_id;
            invocation.cue_id = -1;
            invocation.playback_flags = immediate ? 1u : 0u;
            return invocation.valid()
                && runtime->queue_side_effect(
                    RollbackSideEffectType::Audio,
                    &invocation, sizeof(invocation),
                    kRollbackProductionAudioTerminalLane);
        }

