        static void __fastcall audio_build_schedule_hook(
            uintptr_t schedule_state, void* schedule_context,
            int32_t schedule_index)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [&]() noexcept {
                if (runtime->m_audio_build_schedule_trampoline)
                    reinterpret_cast<BuildEnshutsuAudioScheduleFn>(
                        runtime->m_audio_build_schedule_trampoline)(
                            schedule_state, schedule_context,
                            schedule_index);
            };
            const bool owned = lease && !runtime->m_committing_effect
                && runtime->m_hook_owns_tick.load(std::memory_order_acquire)
                && CurrentRollbackNativeSimulationScope(runtime) != nullptr;
            if (owned)
            {
                // Ghidra: BuildLuxEnshutsuScheduleCallbacks @ 0x140555B90
                // mutates the schedule callback array and installs callbacks
                // before any lower audio terminal. It has no static path from
                // SimulationLoop in the supported stock-online graph, so an
                // owned observation violates admission and is stopped at the
                // first mutation rather than partially journaled.
                runtime->fail_closed(
                    "owned-enshutsu-audio-schedule-builder-unreachable");
                return;
            }
            pass_through();
        }

