        static void __fastcall vfx_disable_filter_hook(
            uintptr_t subsystem, const void* command)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [&]() noexcept {
                if (runtime->m_vfx_disable_filter_trampoline)
                {
                    reinterpret_cast<ApplyVfxDisableFilterFn>(
                        runtime->m_vfx_disable_filter_trampoline)(
                            subsystem, command);
                }
            };
            if (!lease || runtime->m_committing_effect
                || !runtime->m_hook_owns_tick
                || CurrentRollbackNativeSimulationScope(runtime) == nullptr
                || !runtime->m_accept_effects.load(
                    std::memory_order_acquire))
            {
                pass_through();
                return;
            }

            if (!runtime->m_effect_frame.valid || command == nullptr)
            {
                runtime->fail_closed("owned-vfx-disable-frame-missing");
                return;
            }
            const uint64_t epoch = runtime->m_manifest.epoch.generation;
            if (runtime->m_ledger.frame_is_confirmed(
                    epoch, runtime->m_effect_frame.value))
            {
                pass_through();
                return;
            }
            if (subsystem == 0
                || subsystem != runtime->m_vfx_subsystem_identity.subsystem
                || !runtime->validate_vfx_subsystem_identity(epoch))
            {
                runtime->fail_closed(
                    "owned-vfx-disable-subsystem-identity-mismatch");
                return;
            }
            RollbackVfxDisableFilter filter {};
            if (!SafeReadBytes(command, &filter, sizeof(filter)))
            {
                runtime->fail_closed(
                    "owned-vfx-disable-command-unreadable");
                return;
            }
            filter.reserved[0] = filter.reserved[1] =
                filter.reserved[2] = 0;
            filter.tail_reserved[0] = filter.tail_reserved[1] =
                filter.tail_reserved[2] = 0;
            std::array<uint32_t, 512> logical_ids {};
            size_t logical_id_count = 0;
            if (!runtime->m_vfx_slot_shadow.apply_disable(
                    epoch, filter, logical_ids, logical_id_count,
                    runtime->m_effect_frame.value))
            {
                runtime->fail_closed(
                    "owned-vfx-disable-shadow-resolution-failed");
                return;
            }
            const RollbackVfxPendingTerminal terminal =
                filter.remove_immediately
                ? RollbackVfxPendingTerminal::Remove
                : RollbackVfxPendingTerminal::SoftDisable;
            for (size_t index = 0; index < logical_id_count; ++index)
            {
                RollbackVfxTerminalInvocation invocation {};
                invocation.logical_slot_id = logical_ids[index];
                invocation.terminal = terminal;
                if (!invocation.valid()
                    || !runtime->queue_side_effect(
                        RollbackSideEffectType::Vfx,
                        &invocation, sizeof(invocation),
                        kRollbackProductionVfxWorldSpawnLane))
                {
                    runtime->fail_closed(
                        "owned-vfx-disable-journal-failed");
                    return;
                }
            }
        }

