        static void __fastcall stage_cut_overlap_hook(
            uintptr_t actor, void* overlapped_component, void* other_actor,
            void* other_component, int32_t other_body_index,
            bool from_sweep, void* sweep_result)
        {
            RollbackProductionRuntime* runtime =
                s_callback_runtime.load(std::memory_order_acquire);
            if (!runtime) return;
            CallbackLease lease(runtime, true);
            const auto pass_through = [&]() noexcept {
                if (runtime->m_stage_cut_overlap_trampoline)
                    reinterpret_cast<HandleStageCutWeaponOverlapFn>(
                        runtime->m_stage_cut_overlap_trampoline)(
                            actor, overlapped_component, other_actor,
                            other_component, other_body_index, from_sweep,
                            sweep_result);
            };
            const bool owned = lease && !runtime->m_committing_effect
                && runtime->m_hook_owns_tick.load(std::memory_order_acquire)
                && CurrentRollbackNativeSimulationScope(runtime) != nullptr;
            if (owned)
            {
                // Ghidra xrefs prove this UE BeginOverlap delegate is one of
                // only two producers of ApplyLuxStageCutFromMoveEvent. The
                // delayed path mutates actor state before Apply, so guard the
                // producer itself when stock-online admission is violated.
                runtime->fail_closed(
                    "owned-stage-cut-overlap-callback-unreachable");
                return;
            }
            pass_through();
        }

